export default "as.logging import get_logger\\nfrom ...extras.misc import calculate_tps\\nfrom ...extras.packages import is_hyper_parallel_available, is_transformers_version_greater_than\\nfrom ...extras.ploting import plot_loss\\nfrom ...model import load_model, load_tokenizer\\nfrom ..sft.metric import ComputeAccuracy, ComputeSimilarity, eval_logit_processor\\nfrom ..trainer_utils import create_modelcard_and_push, create_ref_model\\nfrom .trainer import HyperParallelTrainer\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import Seq2SeqTrainingArguments, TrainerCallback\\n\\n    from ...hparams import DataArguments, FinetuningArguments, GeneratingArguments, ModelArguments\\n\\n\\nlogger = get_logger(__name__)\\n\\n\\ndef _prepare_hp_args(finetuning_args: \\\"FinetuningArguments\\\", model_args: \\\"ModelArguments\\\"):\\n    r\\\"\\\"\\\"Load HyperParallel arguments and apply LlamaFactory-side overrides.\\n\\n    When activation optimization is enabled, skip native gradient checkpointing\\n    so HP can install its own via ``setup_activation_optimization``.\\n    \\\"\\\"\\\"\\n    if not is_hyper_parallel_available():\\n        raise ImportError(\\\"hyper_parallel is not installed. Please install it with `pip install hyper_parallel`.\\\")\\n\\n    from hyper_parallel.integration.llamafactory import HyperParallelArguments  # pylint: disable=C0415\\n\\n    hp_args = HyperParallelArguments.from_finetuning_args(finetuning_args)\\n\\n    if getattr(hp_args, \\\"cp_size\\\", None) != finetuning_args.hyper_parallel_cp_size:\\n        setattr(hp_args, \\\"cp_size\\\", finetuning_args.hyper_parallel_cp_size)\\n\\n    if getattr(hp_args, \\\"ep_size\\\", None) != finetuning_args.hyper_parallel_ep_size:\\n        setattr(hp_args, \\\"ep_size\\\", finetuning_args.hyper_parallel_ep_size)\\n\\n    if getattr(hp_args, \\\"efsdp_size\\\", None) != finetuning_args.hyper_parallel_efsdp_size:\\n        setattr(hp_args, \\\"efsdp_size\\\", finetuning_args.hyper_parallel_efsdp_size)\\n\\n    if getattr(hp_args, \\\"token_dispatcher\\\", None) != finetuning_args.hyper_parallel_token_dispatcher:\\n        setattr(hp_args, \\\"token_dispatcher\\\", finetuning_args.hyper_parallel_token_dispatcher)\\n\\n    hp_args.validate()\\n\\n    if hp_args.activation_mode != \\\"none\\\":\\n        model_args.disable_gradient_checkpointing = True\\n    return hp_args\\n\\n\\ndef run_pt(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"Seq2SeqTrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    callbacks: Optional[list[\\\"TrainerCallback\\\"]] = None,\\n):\\n    hp_args = _prepare_hp_args(finetuning_args, model_args)\\n\\n    tokenizer_module = load_tokenizer(model_args)\\n    tokenizer = tokenizer_module[\\\"tokenizer\\\"]\\n    template = get_template_and_fix_tokenizer(tokenizer, data_args)\\n    dataset_module = get_dataset(template, model_args, data_args, training_args, stage=\\\"pt\\\", **tokenizer_module)\\n    model = load_model(tokenizer, model_args, finetuning_args, training_args.do_train)\\n    data_collator = DataCollatorForLanguageModeling(tokenizer=tokenizer, mlm=False)\\n\\n    trainer = HyperParallelTrainer(\\n        hp_args=hp_args,\\n        model=model,\\n        args=training_args,\\n        finetuning_args=finetuning_args,\\n        data_collator=data_collator,\\n        callbacks=callbacks,\\n        **dataset_module,\\n        **tokenizer_module,\\n    )\\n\\n    if training_args.do_train:\\n        train_result = trainer.train(resume_from_checkpoint=training_args.resume_from_checkpoint)\\n        trainer.save_model()\\n        trainer.log_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_state()\\n        if trainer.is_world_process_zero() and finetuning_args.plot_loss:\\n            keys = [\\\"loss\\\"]\\n            if isinstance(dataset_module.get(\\\"eval_dataset\\\"), dict):\\n                keys += [f\\\"eval_{key}_loss\\\" for key in dataset_module[\\\"eval_dataset\\\"].keys()]\\n            else:\\n                keys += [\\\"eval_loss\\\"]\\n\\n            plot_loss(training_args.output_dir, keys=keys)\\n\\n    if training_args.do_eval:\\n        metrics = trainer.evaluate(metric_key_prefix=\\\"eval\\\")\\n\\n        if isinstance(dataset_module.get(\\\"eval_dataset\\\"), dict):\\n            for key in dataset_module[\\\"eval_dataset\\\"].keys():\\n                try:\\n                    perplexity = math.exp(metrics[f\\\"eval_{key}_loss\\\"])\\n                except OverflowError:\\n                    perplexity = float(\\\"inf\\\")\\n\\n                metrics[f\\\"eval_{key}_perplexity\\\"] = perplexity\\n        else:\\n            try:\\n                perplexity = math.exp(metrics[\\\"eval_loss\\\"])\\n            except OverflowError:\\n                perplexity = float(\\\"inf\\\")\\n\\n            metrics[\\\"eval_perplexity\\\"] = perplexity\\n\\n        trainer.log_metrics(\\\"eval\\\", metrics)\\n        trainer.save_metrics(\\\"eval\\\", metrics)\\n\\n    create_modelcard_and_push(trainer, model_args, data_args, training_args, finetuning_args)\\n\\n\\ndef run_sft(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"Seq2SeqTrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    generating_args: \\\"GeneratingArguments\\\",\\n    callbacks: Optional[list[\\\"TrainerCallback\\\"]] = None,\\n):\\n    hp_args = _prepare_hp_args(finetuning_args, model_args)\\n\\n    tokenizer_module = load_tokenizer(model_args)\\n    tokenizer = tokenizer_module[\\\"tokenizer\\\"]\\n    template = get_template_and_fix_tokenizer(tokenizer, data_args)\\n    dataset_module = get_dataset(template, model_args, data_args, training_args, stage=\\\"sft\\\", **tokenizer_module)\\n    model = load_model(tokenizer, model_args, finetuning_args, training_args.do_train)\\n\\n    ref_model = None\\n    if finetuning_args.use_asft_loss:\\n        ref_model = create_ref_model(model_args, finetuning_args)\\n\\n    data_collator = SFTDataCollatorWith4DAttentionMask(\\n        template=template,\\n        model=model if not training_args.predict_with_generate else None,\\n        pad_to_multiple_of=8 if training_args.do_train else None,\\n        label_pad_token_id=IGNORE_INDEX if data_args.ignore_pad_token_for_loss else tokenizer.pad_token_id,\\n        block_diag_attn=model_args.block_diag_attn,\\n        attn_implementation=getattr(model.config, \\\"_attn_implementation\\\", None),\\n        compute_dtype=model_args.compute_dtype,\\n        **tokenizer_module,\\n    )\\n\\n    # Metric utils\\n    metric_module = {}\\n    if training_args.predict_with_generate:\\n        metric_module[\\\"compute_metrics\\\"] = ComputeSimilarity(tokenizer=tokenizer)\\n    elif finetuning_args.compute_accuracy:\\n        metric_module[\\\"compute_metrics\\\"] = ComputeAccuracy()\\n        metric_module[\\\"preprocess_logits_for_metrics\\\"] = eval_logit_processor\\n\\n    # Keyword arguments for `model.generate`\\n    gen_kwargs = generating_args.to_dict(obey_generation_config=True)\\n    if is_transformers_version_greater_than(\\\"4.58.0\\\"):\\n        extra_ids = getattr(tokenizer, \\\"additional_special_tokens_ids\\\", None)\\n        if not isinstance(extra_ids, list):\\n            extra_special_tokens = getattr(tokenizer, \\\"_extra_special_tokens\\\", [])\\n            string_tokens = [str(t) for t in extra_special_tokens]\\n            extra_ids = tokenizer.convert_tokens_to_ids(string_tokens)\\n        all_eos_ids = [tokenizer.eos_token_id] + [i for i in extra_ids if i != -1]\\n        gen_kwargs[\\\"eos_token_id\\\"] = list(dict.fromkeys(all_eos_ids))\\n    else:\\n        gen_kwargs[\\\"eos_token_id\\\"] = [tokenizer.eos_token_id] + tokenizer.additional_special_tokens_ids\\n    gen_kwargs[\\\"pad_token_id\\\"] = tokenizer.pad_token_id\\n\\n    trainer = HyperParallelTrainer(\\n        hp_args=hp_args,\\n        model=model,\\n        args=training_args,\\n        finetuning_args=finetuning_args,\\n        data_collator=data_collator,\\n        callbacks=callbacks,\\n        gen_kwargs=gen_kwargs,\\n        ref_model=ref_model,\\n        **dataset_module,\\n        **tokenizer_module,\\n        **metric_module,\\n    )\\n\\n    # Training\\n    if training_args.do_train:\\n        train_result = trainer.train(resume_from_checkpoint=training_args.resume_from_checkpoint)\\n        trainer.save_model()\\n        if finetuning_args.include_effective_tokens_per_second:\\n            train_result.metrics[\\\"effective_tokens_per_sec\\\"] = calculate_tps(\\n                dataset_module[\\\"train_dataset\\\"], train_result.metrics, stage=\\\"sft\\\"\\n            )\\n\\n        trainer.log_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_state()\\n        if trainer.is_world_process_zero() and finetuning_args.plot_loss:\\n            keys = [\\\"loss\\\"]\\n            if isinstance(dataset_module.get(\\\"eval_dataset\\\"), dict):\\n                keys += sum(\\n                    [[f\\\"eval_{key}_loss\\\", f\\\"eval_{key}_accuracy\\\"] for key in dataset_module[\\\"eval_dataset\\\"].keys()],\\n                    [],\\n                )\\n            else:\\n                keys += [\\\"eval_loss\\\", \\\"eval_accuracy\\\"]\\n\\n            plot_loss(training_args.output_dir, keys=keys)\\n\\n    if training_args.predict_with_generate:\\n        tokenizer.padding_side = \\\"left\\\"\\n\\n    # Evaluation\\n    if training_args.do_eval:\\n        metrics = trainer.evaluate(metric_key_prefix=\\\"eval\\\", **gen_kwargs)\\n        trainer.log_metrics(\\\"eval\\\", metrics)\\n        trainer.save_metrics(\\\"eval\\\", metrics)\\n\\n    # Predict\\n    if training_args.do_predict:\\n        logger.warning_rank0_once(\\\"Batch generation can be very slow. Consider using `scripts/vllm_infer.py` instead.\\\")\\n        predict_results = trainer.predict(dataset_module[\\\"eval_dataset\\\"], metric_key_prefix=\\\"predict\\\", **gen_kwargs)\\n        trainer.log_metrics(\\\"predict\\\", predict_results.metrics)\\n        trainer.save_metrics(\\\"predict\\\", predict_results.metrics)\\n        trainer.save_predictions(dataset_module[\\\"eval_dataset\\\"], predict_results, generating_args.skip_special_tokens)\\n\\n    # Create model card\\n    create_modelcard_and_push(trainer, model_args, data_args, training_args, finetuning_args)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/kto/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"40bade681d34f680959be317376ceadcea6504164debc937455a07900ce3692b\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom .workflow import run_kto\\n\\n\\n__all__ = [\\\"run_kto\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/kto/trainer.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d3de48842e55186c391a6311181e8239c5dbbf4d9a5a95f4b1e4d7d24c24df4a\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's TRL library.\\n# https://github.com/huggingface/trl/blob/v0.8.0/trl/trainer/kto_trainer.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport warnings\\nfrom collections import defaultdict\\nfrom contextlib import nullcontext\\nfrom types import MethodType\\nfrom typing import TYPE_CHECKING, Literal, Optional, Union\\n\\nimport torch\\nfrom transformers import Trainer\\nfrom trl import KTOTrainer\\nfrom trl.models.utils import prepare_deepspeed, prepare_fsdp\\nfrom trl.trainer import disable_dropout_in_model\\nfrom typing_extensions import override\\n\\nfrom ...extras.constants import IGNORE_INDEX\\nfrom ...extras.packages import is_transformers_version_greater_than\\nfrom ..callbacks import SaveProcessorCallback\\nfrom ..trainer_utils import create_custom_optimizer, create_custom_scheduler, get_batch_logps, nested_detach\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import PreTrainedModel, ProcessorMixin\\n\\n    from ...hparams import FinetuningArguments\\n\\n\\nclass CustomKTOTrainer(KTOTrainer):\\n    def __init__(\\n        self,\\n        model: Union[\\\"PreTrainedModel\\\", torch.nn.Module],\\n        ref_model: Optional[Union[\\\"PreTrainedModel\\\", torch.nn.Module]],\\n        finetuning_args: \\\"FinetuningArguments\\\",\\n        processor: Optional[\\\"ProcessorMixin\\\"],\\n        disable_dropout: bool = True,\\n        **kwargs,\\n    ):\\n        if is_transformers_version_greater_than(\\\"4.46\\\"):\\n            kwargs[\\\"processing_class\\\"] = kwargs.pop(\\\"tokenizer\\\")\\n\\n        if disable_dropout:\\n            disable_dropout_in_model(model)\\n            if ref_model is not None:\\n                disable_dropout_in_model(ref_model)\\n\\n        self.finetuning_args = finetuning_args\\n        self.reference_free = False\\n        self.use_dpo_data_collator = True  # hack to avoid warning\\n        self.generate_during_eval = False  # disable at evaluation\\n        self.label_pad_token_id = IGNORE_INDEX\\n        self.padding_value = 0\\n        self.is_encoder_decoder = model.config.is_encoder_decoder\\n        self.precompute_ref_log_probs = False\\n        self._precomputed_train_ref_log_probs = False\\n        self._precomputed_eval_ref_log_probs = False\\n        self._peft_has_been_casted_to_bf16 = False\\n\\n        self.ref_model = ref_model\\n        self._stored_metrics = defaultdict(lambda: defaultdict(list))\\n\\n        # kto hyperparams\\n        self.beta = finetuning_args.pref_beta\\n        self.desirable_weight = finetuning_args.kto_chosen_weight\\n        self.undesirable_weight = finetuning_args.kto_rejected_weight\\n        self.ftx_gamma = finetuning_args.pref_ftx\\n        # trl\\n        # Not all losses require a KL calculation\\n        self.calculate_KL = True\\n        if hasattr(self, \\\"loss_type\\\") and self.loss_type in [\\\"apo_zero_unpaired\\\"]:\\n            self.calculate_KL = False\\n        else:\\n            self.loss_type = \\\"kto\\\"\\n\\n        Trainer.__init__(self, model=model, **kwargs)\\n        self.model_accepts_loss_kwargs = False  # overwrite trainer's default behavior\\n        if not hasattr(self, \\\"accelerator\\\"):\\n            raise AttributeError(\\\"Please update `transformers`.\\\")\\n\\n        warnings.simplefilter(\\\"ignore\\\")  # remove gc warnings on ref model\\n\\n        if ref_model is not None:\\n            if self.is_deepspeed_enabled:\\n                if not (\\n                    getattr(ref_model, \\\"is_loaded_in_8bit\\\", False) or getattr(ref_model, \\\"is_loaded_in_4bit\\\", False)\\n                ):  # quantized models are already set on the correct device\\n                    self.ref_model = prepare_deepspeed(self.ref_model, self.accelerator)\\n            elif self.is_fsdp_enabled:\\n                if self.accelerator.is_fsdp2:\\n                    from accelerate.utils.fsdp_utils import fsdp2_prepare_model\\n\\n                    self.ref_model = fsdp2_prepare_model(self.accelerator, self.ref_model)\\n                else:\\n                    self.ref_model = prepare_fsdp(self.ref_model, self.accelerator)\\n            else:\\n                self.ref_model = self.accelerator.prepare_model(self.ref_model, evaluation_mode=True)\\n                self.ref_model.eval()\\n\\n        if processor is not None:\\n            self.add_callback(SaveProcessorCallback(processor))\\n\\n        if finetuning_args.use_badam:\\n            from badam import BAdamCallback, clip_grad_norm_old_version  # type: ignore\\n\\n            self.accelerator.clip_grad_norm_ = MethodType(clip_grad_norm_old_version, self.accelerator)\\n            self.add_callback(BAdamCallback)\\n\\n    @override\\n    def create_optimizer(self, *args, **kwargs) -> \\\"torch.optim.Optimizer\\\":\\n        if self.optimizer is None:\\n            self.optimizer = create_custom_optimizer(self.model, self.args, self.finetuning_args)\\n        return super().create_optimizer(*args, **kwargs)\\n\\n    @override\\n    def create_scheduler(\\n        self, num_training_steps: int, optimizer: Optional[\\\"torch.optim.Optimizer\\\"] = None\\n    ) -> \\\"torch.optim.lr_scheduler.LRScheduler\\\":\\n        create_custom_scheduler(self.args, num_training_steps, optimizer)\\n        return super().create_scheduler(num_training_steps, optimizer)\\n\\n    @override\\n    def _get_train_sampler(self, *args, **kwargs) -> Optional[\\\"torch.utils.data.Sampler\\\"]:\\n        r\\\"\\\"\\\"Replace the sequential sampler of KTO Trainer created by trl with the random sampler.\\\"\\\"\\\"\\n        if self.finetuning_args.disable_shuffling:\\n            return torch.utils.data.SequentialSampler(self.train_dataset)\\n\\n        return Trainer._get_train_sampler(self, *args, **kwargs)\\n\\n    @override\\n    def get_batch_samples(self, *args, **kwargs):\\n        r\\\"\\\"\\\"Replace the method of KTO Trainer with the one of the standard Trainer.\\\"\\\"\\\"\\n        return Trainer.get_batch_samples(self, *args, **kwargs)\\n\\n    @override\\n    def forward(\\n        self, model: \\\"PreTrainedModel\\\", batch: dict[str, \\\"torch.Tensor\\\"], prefix: Literal[\\\"\\\", \\\"kl_\\\"] = \\\"\\\"\\n    ) -> tuple[\\\"torch.Tensor\\\", \\\"torch.Tensor\\\", \\\"torch.Tensor\\\"]:\\n        r\\\"\\\"\\\"Run forward pass and computes the log probabilities.\\\"\\\"\\\"\\n        batch = nested_detach(batch, clone=True)  # avoid error\\n        model_inputs = {\\n            \\\"input_ids\\\": batch[f\\\"{prefix}input_ids\\\"],\\n            \\\"attention_mask\\\": batch[f\\\"{prefix}attention_mask\\\"],\\n        }\\n        if f\\\"{prefix}token_type_ids\\\" in batch:\\n            model_inputs[\\\"token_type_ids\\\"] = batch[f\\\"{prefix}token_type_ids\\\"]\\n\\n        if \\\"pixel_values\\\" in batch:\\n            model_inputs[\\\"pixel_values\\\"] = batch[\\\"pixel_values\\\"]\\n\\n        if \\\"image_sizes\\\" in batch:\\n            model_inputs[\\\"image_sizes\\\"] = batch[\\\"image_sizes\\\"]\\n\\n        if \\\"image_grid_thw\\\" in batch:\\n            model_inputs[\\\"image_grid_thw\\\"] = batch[\\\"image_grid_thw\\\"]\\n\\n        if \\\"aspect_ratio_ids\\\" in batch:\\n            model_inputs[\\\"aspect_ratio_ids\\\"] = batch[\\\"aspect_ratio_ids\\\"]\\n\\n        if \\\"aspect_ratio_mask\\\" in batch:\\n            model_inputs[\\\"aspect_ratio_mask\\\"] = batch[\\\"aspect_ratio_mask\\\"]\\n\\n        if f\\\"{prefix}cross_attention_mask\\\" in batch:\\n            model_inputs[\\\"cross_attention_mask\\\"] = batch[f\\\"{prefix}cross_attention_mask\\\"]\\n\\n        logits = model(**model_inputs, return_dict=True, use_cache=False).logits.to(torch.float32)\\n        logps, valid_length = get_batch_logps(logits=logits, labels=batch[f\\\"{prefix}labels\\\"])\\n        return logits, logps, logps / valid_length\\n\\n    @override\\n    def concatenated_forward(\\n        self, model: \\\"PreTrainedModel\\\", batch: dict[str, \\\"torch.Tensor\\\"]\\n    ) -> tuple[\\\"torch.Tensor\\\", \\\"torch.Tensor\\\", \\\"torch.Tensor\\\", \\\"torch.Tensor\\\", \\\"torch.Tensor\\\", \\\"torch.Tensor\\\"]:\\n        target_logits, target_logps, target_logps_avg = self.forward(model, batch)\\n        with torch.no_grad():\\n            _, kl_logps, _ = self.forward(model, batch, prefix=\\\"kl_\\\")\\n\\n        if len(target_logps) != len(batch[\\\"kto_tags\\\"]):\\n            raise ValueError(\\\"Mismatched shape of inputs and labels.\\\")\\n\\n        chosen_logits = target_logits[batch[\\\"kto_tags\\\"]]\\n        chosen_logps = target_logps[batch[\\\"kto_tags\\\"]]\\n        rejected_logits = target_logits[~batch[\\\"kto_tags\\\"]]\\n        rejected_logps = target_logps[~batch[\\\"kto_tags\\\"]]\\n        chosen_logps_avg = target_logps_avg[batch[\\\"kto_tags\\\"]]\\n        return chosen_logps, rejected_logps, chosen_logits, rejected_logits, kl_logps, chosen_logps_avg\\n\\n    @override\\n    def compute_reference_log_probs(\\n        self, model: \\\"PreTrainedModel\\\", batch: dict[str, \\\"torch.Tensor\\\"]\\n    ) -> tuple[\\\"torch.Tensor\\\", \\\"torch.Tensor\\\", \\\"torch.Tensor\\\"]:\\n        r\\\"\\\"\\\"Compute log probabilities of the reference model.\\\"\\\"\\\"\\n        if self.ref_model is None:\\n            ref_model = model\\n            ref_context = self.accelerator.unwrap_model(model).disable_adapter()\\n        else:\\n            ref_model = self.ref_model\\n            ref_context = nullcontext()\\n\\n        with torch.no_grad(), ref_context:\\n            reference_chosen_logps, reference_rejected_logps, _, _, reference_kl_logps, _ = self.concatenated_forward(\\n                ref_model, batch\\n            )\\n\\n        return reference_chosen_logps, reference_rejected_logps, reference_kl_logps\\n\\n    @override\\n    def get_batch_loss_metrics(\\n        self,\\n        model: \\\"PreTrainedModel\\\",\\n        batch: dict[str, \\\"torch.Tensor\\\"],\\n    ) -> tuple[\\\"torch.Tensor\\\", dict[str, \\\"torch.Tensor\\\"]]:\\n        r\\\"\\\"\\\"Compute the DPO loss and other metrics for the given batch of inputs for train or test.\\\"\\\"\\\"\\n        metrics = {}\\n        (\\n            policy_chosen_logps,\\n            policy_rejected_logps,\\n            policy_chosen_logits,\\n            policy_rejected_logits,\\n            policy_kl_logps,\\n            policy_chosen_logps_avg,\\n        ) = self.concatenated_forward(model, batch)\\n        reference_chosen_logps, reference_rejected_logps, reference_kl_logps = self.compute_reference_log_probs(\\n            model, batch\\n        )\\n        losses, chosen_rewards, rejected_rewards, kl = self.kto_loss(\\n            policy_chosen_logps,\\n            policy_rejected_logps,\\n            policy_kl_logps,\\n            reference_chosen_logps,\\n            reference_rejected_logps,\\n            reference_kl_logps,\\n        )\\n        losses = losses.nanmean()\\n\\n        if self.ftx_gamma > 1e-6 and len(policy_chosen_logps) > 0:  # remember to rescale\\n            sft_loss = -policy_chosen_logps_avg\\n            losses += self.ftx_gamma * sft_loss.nanmean() / len(policy_chosen_logps) * len(batch[\\\"labels\\\"])\\n\\n        num_chosen = len(chosen_rewards)\\n        num_rejected = len(rejected_rewards)\\n        if num_chosen > 0:\\n            metrics[\\\"rewards/chosen_sum\\\"] = chosen_rewards.nansum().item()\\n            metrics[\\\"logps/chosen_sum\\\"] = policy_chosen_logps.nansum().item()\\n            metrics[\\\"logits/chosen_sum\\\"] = policy_chosen_logits.nansum().item()\\n            metrics[\\\"count/chosen\\\"] = float(num_chosen)\\n\\n        if num_rejected > 0:\\n            metrics[\\\"rewards/rejected_sum\\\"] = rejected_rewards.nansum().item()\\n            metrics[\\\"logps/rejected_sum\\\"] = policy_rejected_logps.nansum().item()\\n            metrics[\\\"logits/rejected_sum\\\"] = policy_rejected_logits.nansum().item()\\n            metrics[\\\"count/rejected\\\"] = float(num_rejected)\\n\\n        metrics[\\\"kl\\\"] = kl.item()\\n        return losses, metrics\\n\\n    @override\\n    def compute_loss(\\n        self, model: \\\"PreTrainedModel\\\", inputs: dict[str, \\\"torch.Tensor\\\"], return_outputs: bool = False, **kwargs\\n    ) -> Union[\\\"torch.Tensor\\\", tuple[\\\"torch.Tensor\\\", list[\\\"torch.Tensor\\\"]]]:\\n        r\\\"\\\"\\\"Subclass and override to accept extra kwargs.\\\"\\\"\\\"\\n        return super().compute_loss(model, inputs, return_outputs)\\n\\n    @override\\n    def log(self, logs: dict[str, float], *args, **kwargs) -> None:\\n        r\\\"\\\"\\\"Log `logs` on the various objects watching training, including stored metrics.\\\"\\\"\\\"\\n        # logs either has \\\"loss\\\" or \\\"eval_loss\\\"\\n        train_eval = \\\"train\\\" if \\\"loss\\\" in logs else \\\"eval\\\"\\n        prefix = \\\"eval_\\\" if train_eval == \\\"eval\\\" else \\\"\\\"\\n        # Add averaged stored metrics to logs\\n        key_list, metric_list = [], []\\n        for key, metrics in self._stored_metrics[train_eval].items():\\n            key_list.append(key)\\n            metric_list.append(torch.tensor(metrics, dtype=torch.float).to(self.accelerator.device).sum().item())\\n\\n        del self._stored_metrics[train_eval]\\n        if len(metric_list) < 9:  # pad to for all reduce\\n            for i in range(9 - len(metric_list)):\\n                key_list.append(f\\\"dummy_{i}\\\")\\n                metric_list.append(0.0)\\n\\n        metric_list = torch.tensor(metric_list, dtype=torch.float).to(self.accelerator.device)\\n        metric_list = self.accelerator.reduce(metric_list, \\\"sum\\\").tolist()\\n        metric_dict: dict[str, float] = dict(zip(key_list, metric_list))\\n        for split in [\\\"chosen\\\", \\\"rejected\\\"]:  # accumulate average metrics from sums and lengths\\n            if f\\\"count/{split}\\\" in metric_dict:\\n                for key in (\\\"rewards\\\", \\\"logps\\\", \\\"logits\\\"):\\n                    logs[f\\\"{prefix}{key}/{split}\\\"] = metric_dict[f\\\"{key}/{split}_sum\\\"] / metric_dict[f\\\"count/{split}\\\"]\\n                    del metric_dict[f\\\"{key}/{split}_sum\\\"]\\n                del metric_dict[f\\\"count/{split}\\\"]\\n\\n        if f\\\"{prefix}rewards/chosen\\\" in logs and f\\\"{prefix}rewards/rejected\\\" in logs:  # calculate reward margin\\n            logs[f\\\"{prefix}rewards/margins\\\"] = logs[f\\\"{prefix}rewards/chosen\\\"] - logs[f\\\"{prefix}rewards/rejected\\\"]\\n\\n        for key, metric in metric_dict.items():  # add remaining items\\n            if not key.startswith(\\\"dummy_\\\"):\\n                logs[key] = metric\\n\\n        return Trainer.log(self, logs, *args, **kwargs)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/kto/workflow.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"694d66cadb3d0f0e6e7611753e7067b78fdd2f99dccb4388fef783f8eb0d9777\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's TRL library.\\n# https://github.com/huggingface/trl/blob/v0.8.0/examples/scripts/kto.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import TYPE_CHECKING, Optional\\n\\nfrom ...data import KTODataCollatorWithPadding, get_dataset, get_template_and_fix_tokenizer\\nfrom ...extras.constants import IGNORE_INDEX\\nfrom ...extras.ploting import plot_loss\\nfrom ...hparams import ModelArguments\\nfrom ...model import load_model, load_tokenizer\\nfrom ..trainer_utils import create_modelcard_and_push, create_ref_model\\nfrom .trainer import CustomKTOTrainer\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import Seq2SeqTrainingArguments, TrainerCallback\\n\\n    from ...hparams import DataArguments, FinetuningArguments\\n\\n\\ndef run_kto(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"Seq2SeqTrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    callbacks: Optional[list[\\\"TrainerCallback\\\"]] = None,\\n):\\n    tokenizer_module = load_tokenizer(model_args)\\n    tokenizer = tokenizer_module[\\\"tokenizer\\\"]\\n    template = get_template_and_fix_tokenizer(tokenizer, data_args)\\n    dataset_module = get_dataset(template, model_args, data_args, training_args, stage=\\\"kto\\\", **tokenizer_module)\\n    model = load_model(tokenizer, model_args, finetuning_args, training_args.do_train)\\n\\n    data_collator = KTODataCollatorWithPadding(\\n        template=template,\\n        model=model,\\n        pad_to_multiple_of=8,\\n        label_pad_token_id=IGNORE_INDEX if data_args.ignore_pad_token_for_loss else tokenizer.pad_token_id,\\n        **tokenizer_module,\\n    )\\n\\n    # Create reference model\\n    if finetuning_args.ref_model is None and (not training_args.do_train):  # use the model itself\\n        ref_model = model\\n    else:\\n        ref_model = create_ref_model(model_args, finetuning_args)\\n\\n    # Initialize our Trainer\\n    trainer = CustomKTOTrainer(\\n        model=model,\\n        ref_model=ref_model,\\n        args=training_args,\\n        finetuning_args=finetuning_args,\\n        data_collator=data_collator,\\n        callbacks=callbacks,\\n        **dataset_module,\\n        **tokenizer_module,\\n    )\\n\\n    # Training\\n    if training_args.do_train:\\n        train_result = trainer.train(resume_from_checkpoint=training_args.resume_from_checkpoint)\\n        trainer.save_model()\\n        trainer.log_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_state()\\n        if trainer.is_world_process_zero() and finetuning_args.plot_loss:\\n            keys = [\\\"loss\\\", \\\"rewards/chosen\\\"]\\n            if isinstance(dataset_module.get(\\\"eval_dataset\\\"), dict):\\n                keys += [f\\\"eval_{key}_loss\\\" for key in dataset_module[\\\"eval_dataset\\\"].keys()]\\n            else:\\n                keys += [\\\"eval_loss\\\"]\\n\\n            plot_loss(training_args.output_dir, keys=keys)\\n\\n    # Evaluation\\n    if training_args.do_eval:\\n        metrics = trainer.evaluate(metric_key_prefix=\\\"eval\\\")\\n        if id(model) == id(ref_model):  # unable to compute rewards without a reference model\\n            remove_keys = [key for key in metrics.keys() if \\\"rewards\\\" in key]\\n            for key in remove_keys:\\n                metrics.pop(key)\\n        trainer.log_metrics(\\\"eval\\\", metrics)\\n        trainer.save_metrics(\\\"eval\\\", metrics)\\n\\n    # Create model card\\n    create_modelcard_and_push(trainer, model_args, data_args, training_args, finetuning_args)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/mca/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ba72c89df2a9c836622adb550b513efcdf11465af981c688b2d58a2761b55338\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom .workflow import run_dpo, run_pt, run_sft\\n\\n\\n__all__ = [\\\"run_dpo\\\", \\\"run_pt\\\", \\\"run_sft\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/mca/trainer.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e53f5c8e8c67b4df994d60ee0e15ebac4c1a3de0354e522294128e8464e81613\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import Any\\n\\nimport torch.nn.functional as F\\nfrom mcore_adapter.trainer import McaTrainer\\nfrom torch import Tensor\\nfrom transformers import PreTrainedTokenizerBase\\nfrom typing_extensions import override\\n\\nfrom ...extras.constants import IGNORE_INDEX\\n\\n\\nclass CustomMcaTrainer(McaTrainer):\\n    def __init__(self, *args, **kwargs):\\n        super().__init__(*args, **kwargs)\\n\\n    @override\\n    def _pad_batched_inputs(self, inputs: dict[str, Tensor | Any], seq_length: int):\\n        r\\\"\\\"\\\"Override to avoid padding error when handling 3d posids.\\\"\\\"\\\"\\n        padding_inputs = {\\n            k: v.tolist() if v is not None and isinstance(v, Tensor) else v\\n            for k, v in inputs.items()\\n            if k in self._language_input_names\\n        }\\n\\n        position_ids_3d = None\\n        if isinstance(inputs.get(\\\"position_ids\\\"), Tensor) and inputs[\\\"position_ids\\\"].dim() == 3:\\n            position_ids_3d = inputs[\\\"position_ids\\\"]\\n            padding_inputs.pop(\\\"position_ids\\\", None)\\n\\n        if \\\"labels\\\" in padding_inputs:\\n            padding_inputs[\\\"labels\\\"] = [\\n                labels + [IGNORE_INDEX] * (seq_length - len(labels)) for labels in padding_inputs[\\\"labels\\\"]\\n            ]\\n        tokenizer = (\\n            self.processing_class\\n            if isinstance(self.processing_class, PreTrainedTokenizerBase)\\n            else getattr(self.processing_class, \\\"tokenizer\\\", self.processing_class)\\n        )\\n        padding_side = getattr(tokenizer, \\\"padding_side\\\", \\\"right\\\")\\n        padding_inputs = tokenizer.pad(\\n            padding_inputs,\\n            padding=\\\"max_length\\\",\\n            max_length=seq_length,\\n            return_tensors=\\\"pt\\\",\\n        ).to(self.args.device)\\n        inputs.update(padding_inputs)\\n\\n        if position_ids_3d is not None:\\n            current_seq_len = position_ids_3d.size(-1)\\n            if current_seq_len < seq_length:\\n                pad_len = seq_length - current_seq_len\\n                if padding_side == \\\"left\\\":\\n                    position_ids_3d = F.pad(position_ids_3d, (pad_len, 0), value=0)\\n                else:\\n                    position_ids_3d = F.pad(position_ids_3d, (0, pad_len), value=0)\\n\\n            inputs[\\\"position_ids\\\"] = position_ids_3d.to(self.args.device)\\n\\n        return inputs\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/mca/workflow.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"37532cc23ba41395541c41258f44432b8dff482018df2ad26ffd7f856f65708e\",\"content\":\"# Copyright 2025 the ROLL team and the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport functools\\nimport json\\nimport os\\nfrom collections.abc import Sequence\\nfrom copy import deepcopy\\nfrom typing import TYPE_CHECKING, Any, Optional\\n\\nimport torch\\nfrom transformers import DataCollatorForSeq2Seq\\n\\nfrom ...data import (\\n    SFTDataCollatorWith4DAttentionMask,\\n    get_dataset,\\n    get_template_and_fix_tokenizer,\\n)\\nfrom ...data.collator import (\\n    PairwiseDataCollatorWithPadding,\\n)\\nfrom ...extras.constants import IGNORE_INDEX, MCA_SUPPORTED_MODELS\\nfrom ...extras.logging import get_logger\\nfrom ...extras.misc import calculate_tps\\nfrom ...extras.packages import is_mcore_adapter_available\\nfrom ...extras.ploting import plot_loss\\nfrom ...model import load_tokenizer\\nfrom ..callbacks import SaveProcessorCallback\\n\\n\\nif not is_mcore_adapter_available():\\n    raise ImportError(\\\"mcore_adapter is not installed. Please install it with `pip install mcore-adapter`.\\\")\\n\\nfrom mcore_adapter.models import AutoConfig, AutoModel\\nfrom mcore_adapter.trainer import DPOTrainer as McaDPOTrainer\\nfrom mcore_adapter.trainer.dpo_config import DPOConfig\\n\\nfrom .trainer import CustomMcaTrainer\\n\\n\\nif TYPE_CHECKING:\\n    from mcore_adapter.training_args import Seq2SeqTrainingArguments as McaSeq2SeqTrainingArguments\\n    from transformers import TrainerCallback\\n\\n    from ...hparams import DataArguments, FinetuningArguments, ModelArguments\\n\\n\\nlogger = get_logger(__name__)\\n\\n\\ndef _data_collator_wrapper(data_collator: Any):\\n    @functools.wraps(data_collator)\\n    def wrapper(features: Sequence[dict[str, Any]]):\\n        labels_key = [k for k in features[0].keys() if k.endswith(\\\"labels\\\")]\\n        input_ids_key = [k for k in features[0].keys() if k.endswith(\\\"input_ids\\\")]\\n        for feature in features:\\n            if len(labels_key) == 0:  # pt\\n                feature[\\\"labels\\\"] = deepcopy(feature[\\\"input_ids\\\"])[1:]\\n            for k in labels_key:\\n                feature[k] = feature[k][1:]\\n            for k in input_ids_key:\\n                feature[k] = feature[k][:-1]\\n            for k in [\\\"attention_mask\\\", \\\"position_ids\\\"]:\\n                if k in feature:\\n                    feature[k] = feature[k][:-1]\\n\\n        # for qwen vl series model\\n        tmp_features = data_collator(features)\\n        tmp_features.pop(\\\"rope_deltas\\\", None)\\n        position_ids = tmp_features.get(\\\"position_ids\\\", None)\\n\\n        if position_ids is not None and position_ids.dim() == 3:\\n            if position_ids.shape[0] == 4:\\n                position_ids = position_ids[1:]\\n            tmp_features[\\\"position_ids\\\"] = position_ids\\n\\n        return tmp_features\\n\\n    return wrapper\\n\\n\\ndef _check_model_support(model_args: \\\"ModelArguments\\\"):\\n    from transformers import AutoConfig as HfAutoConfig\\n\\n    if os.path.exists(os.path.join(model_args.model_name_or_path, \\\"mca_config.json\\\")):  # load from mcore ckpt\\n        mca_config = json.load(open(os.path.join(model_args.model_name_or_path, \\\"mca_config.json\\\")))\\n        model_type = mca_config.get(\\\"hf_model_type\\\", None)\\n    else:\\n        config = HfAutoConfig.from_pretrained(\\n            model_args.model_name_or_path, trust_remote_code=model_args.trust_remote_code\\n        )\\n        model_type = config.model_type\\n\\n    if model_type not in MCA_SUPPORTED_MODELS:\\n        raise ValueError(\\n            f\\\"Model {model_type} is not supported by mcore_adapter.\\\"\\n            \\\"You can try to upgrade mcore_adapter to the latest version for more supported models.\\\"\\n        )\\n\\n\\ndef _freeze_model_parameters(model: Any, finetuning_args: \\\"FinetuningArguments\\\"):\\n    \\\"\\\"\\\"Freeze model parameters for qwen_vl series models based on finetuning arguments.\\\"\\\"\\\"\\n    if getattr(model.config, \\\"hf_model_type\\\", None) not in [\\n        \\\"qwen2_vl\\\",\\n        \\\"qwen2_5_vl\\\",\\n        \\\"qwen3_vl\\\",\\n        \\\"qwen3_vl_moe\\\",\\n        \\\"qwen3_5\\\",\\n        \\\"qwen3_5_moe\\\",\\n    ]:\\n        return\\n\\n    params_to_freeze = []\\n    if finetuning_args.freeze_vision_tower:\\n        params_to_freeze.extend([\\\"vision_model.blocks\\\", \\\"vision_model.patch_embed\\\"])\\n        if getattr(model.config, \\\"hf_model_type\\\", None) in [\\\"qwen3_vl\\\", \\\"qwen3_vl_moe\\\", \\\"qwen3_5\\\", \\\"qwen3_5_moe\\\"]:\\n            params_to_freeze.extend([\\\"vision_model.pos_embed\\\"])\\n\\n    if finetuning_args.freeze_multi_modal_projector:\\n        params_to_freeze.extend([\\\"vision_model.merger\\\"])\\n\\n    if finetuning_args.freeze_language_model:\\n        params_to_freeze.extend([\\\"embedding\\\", \\\"decoder\\\", \\\"output_layer\\\"])\\n\\n    if params_to_freeze:\\n        for name, p in model.named_parameters():\\n            if any(name.startswith(k) for k in params_to_freeze):\\n                p.requires_grad_(False)\\n\\n\\ndef _build_meta_hf_model_for_collator(model_args: \\\"ModelArguments\\\") -> Any | None:\\n    r\\\"\\\"\\\"Build a lightweight HF model on meta device for compatibility with collator.\\\"\\\"\\\"\\n    from transformers import AutoConfig as HfAutoConfig\\n    from transformers import AutoModel as HfAutoModel\\n    from transformers import AutoModelForImageTextToText\\n\\n    try:\\n        config = HfAutoConfig.from_pretrained(\\n            model_args.model_name_or_path, trust_remote_code=model_args.trust_remote_code\\n        )\\n        with torch.device(\\\"meta\\\"):\\n            try:\\n                # Prefer multimodal auto class for VLMs (e.g. qwen2-vl), so get_rope_index is available.\\n                return AutoModelForImageTextToText.from_config(config)\\n            except Exception:\\n                return HfAutoModel.from_config(config)\\n    except Exception as exc:\\n        logger.warning(\\\"Failed to build meta HF model for collator, fallback to no model. Error: %s\\\", exc)\\n        return None\\n\\n\\ndef run_pt(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"McaSeq2SeqTrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    callbacks: Optional[list[\\\"TrainerCallback\\\"]] = None,\\n):\\n    tokenizer_module = load_tokenizer(model_args)\\n    tokenizer = tokenizer_module[\\\"tokenizer\\\"]\\n    template = get_template_and_fix_tokenizer(tokenizer, data_args)\\n\\n    # dataset needs +1 then cut back due to MCA shift logic\\n    data_args.cutoff_len += 1\\n    dataset_module = get_dataset(template, model_args, data_args, training_args, stage=\\\"pt\\\", **tokenizer_module)\\n    data_args.cutoff_len -= 1\\n\\n    _check_model_support(model_args)\\n    model = AutoModel.from_pretrained(model_args.model_name_or_path, training_args)\\n    data_collator = DataCollatorForSeq2Seq(\\n        tokenizer=tokenizer,\\n        pad_to_multiple_of=8,\\n        label_pad_token_id=IGNORE_INDEX,\\n    )\\n    data_collator = _data_collator_wrapper(data_collator)\\n\\n    trainer = CustomMcaTrainer(\\n        model=model,\\n        args=training_args,\\n        tokenizer=tokenizer,\\n        data_collator=data_collator,\\n        callbacks=callbacks,\\n        **dataset_module,\\n    )\\n\\n    if \\\"processor\\\" in tokenizer_module and tokenizer_module[\\\"processor\\\"] is not None:\\n        trainer.add_callback(SaveProcessorCallback(tokenizer_module[\\\"processor\\\"]))\\n\\n    if training_args.do_train:\\n        train_result = trainer.train(training_args.resume_from_checkpoint)\\n        trainer.save_model()\\n        trainer.log_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_state()\\n        if trainer.is_world_process_zero() and finetuning_args.plot_loss:\\n            keys = [\\\"loss\\\"]\\n            if isinstance(dataset_module.get(\\\"eval_dataset\\\"), dict):\\n                keys += [f\\\"eval_{key}_loss\\\" for key in dataset_module[\\\"eval_dataset\\\"].keys()]\\n            else:\\n                keys += [\\\"eval_loss\\\"]\\n            plot_loss(training_args.output_dir, keys=keys)\\n\\n\\ndef run_sft(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"McaSeq2SeqTrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    callbacks: Optional[list[\\\"TrainerCallback\\\"]] = None,\\n):\\n    # align packing flags\\n    # TODO: FIX SequencePacking\\n    data_args.neat_packing = training_args.sequence_packing = data_args.neat_packing or training_args.sequence_packing\\n    data_args.packing = data_args.neat_packing or data_args.packing\\n\\n    tokenizer_module = load_tokenizer(model_args)\\n    tokenizer = tokenizer_module[\\\"tokenizer\\\"]\\n    template = get_template_and_fix_tokenizer(tokenizer, data_args)\\n\\n    # dataset needs +1 then cut back due to MCA shift logic\\n    data_args.cutoff_len += 1\\n    dataset_module = get_dataset(template, model_args, data_args, training_args, stage=\\\"sft\\\", **tokenizer_module)\\n    data_args.cutoff_len -= 1\\n\\n    _check_model_support(model_args)\\n    model = AutoModel.from_pretrained(model_args.model_name_or_path, training_args)\\n    collator_model = _build_meta_hf_model_for_collator(model_args)\\n\\n    # optional freezing for qwen_vl series\\n    _freeze_model_parameters(model, finetuning_args)\\n\\n    pad_to_max = training_args.expert_model_parallel_size is not None and training_args.expert_model_parallel_size > 1\\n    data_collator = SFTDataCollatorWith4DAttentionMask(\\n        template=template,\\n        model=collator_model,\\n        padding=\\\"max_length\\\" if pad_to_max else \\\"longest\\\",\\n        max_length=data_args.cutoff_len if pad_to_max else None,\\n        pad_to_multiple_of=64,\\n        label_pad_token_id=IGNORE_INDEX,\\n        **tokenizer_module,\\n    )\\n    data_collator = _data_collator_wrapper(data_collator)\\n\\n    trainer = CustomMcaTrainer(\\n        model=model,\\n        args=training_args,\\n        tokenizer=tokenizer,\\n        data_collator=data_collator,\\n        callbacks=callbacks,\\n        **dataset_module,\\n    )\\n\\n    if \\\"processor\\\" in tokenizer_module and tokenizer_module[\\\"processor\\\"] is not None:\\n        trainer.add_callback(SaveProcessorCallback(tokenizer_module[\\\"processor\\\"]))\\n\\n    train_result = trainer.train(training_args.resume_from_checkpoint)\\n    trainer.save_model()\\n    trainer.log_metrics(\\\"train\\\", train_result.metrics)\\n    trainer.save_metrics(\\\"train\\\", train_result.metrics)\\n    trainer.save_state()\\n    if trainer.is_world_process_zero() and finetuning_args.plot_loss:\\n        keys = [\\\"loss\\\"]\\n        if isinstance(dataset_module.get(\\\"eval_dataset\\\"), dict):\\n            keys += [f\\\"eval_{key}_loss\\\" for key in dataset_module[\\\"eval_dataset\\\"].keys()]\\n        else:\\n            keys += [\\\"eval_loss\\\"]\\n        plot_loss(training_args.output_dir, keys=keys)\\n\\n\\ndef run_dpo(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"McaSeq2SeqTrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    callbacks: Optional[list[\\\"TrainerCallback\\\"]] = None,\\n):\\n    tokenizer_module = load_tokenizer(model_args)\\n    tokenizer = tokenizer_module[\\\"tokenizer\\\"]\\n    template = get_template_and_fix_tokenizer(tokenizer, data_args)\\n\\n    _check_model_support(model_args)\\n    model = AutoModel.from_pretrained(model_args.model_name_or_path, training_args)\\n    collator_model = _build_meta_hf_model_for_collator(model_args)\\n\\n    _freeze_model_parameters(model, finetuning_args)\\n\\n    if finetuning_args.use_ref_model:\\n        ref_config = AutoConfig.from_pretrained(model_args.model_name_or_path, training_args)\\n        ref_model = AutoModel.from_config(ref_config)\\n        ref_model.load_state_dict(model.state_dict())\\n    else:\\n        ref_model = None\\n\\n    # dataset needs +1 then cut back due to MCA shift logic\\n    data_args.cutoff_len += 1\\n    dataset_module = get_dataset(template, model_args, data_args, training_args, stage=\\\"rm\\\", **tokenizer_module)\\n    data_args.cutoff_len -= 1\\n\\n    pad_to_max = training_args.expert_model_parallel_size is not None and training_args.expert_model_parallel_size > 1\\n    dpo_config = DPOConfig(\\n        beta=finetuning_args.pref_beta,\\n        pref_loss=finetuning_args.pref_loss,\\n        label_smoothing=finetuning_args.dpo_label_smoothing,\\n    )\\n    data_collator = PairwiseDataCollatorWithPadding(\\n        template=template,\\n        model=collator_model,\\n        pad_to_multiple_of=64,\\n        padding=\\\"max_length\\\" if pad_to_max else \\\"longest\\\",\\n        max_length=data_args.cutoff_len if pad_to_max else None,\\n        label_pad_token_id=IGNORE_INDEX,\\n        **tokenizer_module,\\n    )\\n    data_collator = _data_collator_wrapper(data_collator)\\n\\n    trainer = McaDPOTrainer(\\n        model=model,\\n        ref_model=ref_model,\\n        args=training_args,\\n        train_config=dpo_config,\\n        tokenizer=tokenizer,\\n        data_collator=data_collator,\\n        callbacks=callbacks,\\n        **dataset_module,\\n    )\\n\\n    if \\\"processor\\\" in tokenizer_module and tokenizer_module[\\\"processor\\\"] is not None:\\n        trainer.add_callback(SaveProcessorCallback(tokenizer_module[\\\"processor\\\"]))\\n\\n    train_result = trainer.train(training_args.resume_from_checkpoint)\\n    trainer.save_model()\\n    if finetuning_args.include_effective_tokens_per_second:\\n        train_result.metrics[\\\"effective_tokens_per_sec\\\"] = calculate_tps(\\n            dataset_module[\\\"train_dataset\\\"], train_result.metrics, stage=\\\"rm\\\"\\n        )\\n\\n    trainer.log_metrics(\\\"train\\\", train_result.metrics)\\n    trainer.save_metrics(\\\"train\\\", train_result.metrics)\\n    trainer.save_state()\\n    if trainer.is_world_process_zero() and finetuning_args.plot_loss:\\n        keys = [\\\"loss\\\", \\\"rewards/accuracies\\\"]\\n        if isinstance(dataset_module.get(\\\"eval_dataset\\\"), dict):\\n            keys += [f\\\"eval_{key}_loss\\\" for key in dataset_module[\\\"eval_dataset\\\"].keys()]\\n        else:\\n            keys += [\\\"eval_loss\\\"]\\n\\n        plot_loss(training_args.output_dir, keys=keys)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/megatron_bridge/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8b2510b78403d4f902dec8a76105b2b48662f03229db2ff6f3a5ff181f0e8b8b\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom .workflow import run_pt, run_sft\\n\\n\\n__all__ = [\\\"run_pt\\\", \\\"run_sft\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/megatron_bridge/config_builder.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b4c7b7597cd6b2a8161d5e14ce87d6a73c9c39ce7ee3b8a6c7cae2a5e445d9ca\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport math\\nimport os\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom ...extras.logging import get_logger\\n\\n\\nif TYPE_CHECKING:\\n    from ...hparams import (\\n        DataArguments,\\n        FinetuningArguments,\\n        MegatronBridgeArguments,\\n        ModelArguments,\\n        TrainingArguments,\\n    )\\n\\n\\nlogger = get_logger(__name__)\\n\\n_LR_SCHEDULER_MAP = {\\n    \\\"cosine\\\": \\\"cosine\\\",\\n    \\\"linear\\\": \\\"linear\\\",\\n    \\\"constant\\\": \\\"constant\\\",\\n    \\\"constant_with_warmup\\\": \\\"constant\\\",\\n}\\n\\n\\ndef _map_lr_scheduler_type(lr_scheduler_type: str) -> str:\\n    mapped = _LR_SCHEDULER_MAP.get(lr_scheduler_type)\\n    if mapped is None:\\n        logger.warning_rank0(\\n            f\\\"lr_scheduler_type '{lr_scheduler_type}' is not supported by Megatron Bridge; using cosine.\\\"\\n        )\\n        return \\\"cosine\\\"\\n    return mapped\\n\\n\\ndef _resolve_warmup_steps(training_args: \\\"TrainingArguments\\\", train_iters: int) -> int:\\n    r\\\"\\\"\\\"Resolve warmup steps with Hugging Face Trainer semantics.\\n\\n    Absolute ``warmup_steps`` are kept as-is (even when larger than ``train_iters``)\\n    so short debugging runs with ``max_steps < warmup_steps`` match HF LR values.\\n    ``lr_decay_iters`` is expanded separately to avoid Megatron capping warmup.\\n    \\\"\\\"\\\"\\n    warmup_steps = getattr(training_args, \\\"warmup_steps\\\", 0) or 0\\n    if warmup_steps > 0:\\n        return warmup_steps\\n\\n    warmup_ratio = getattr(training_args, \\\"warmup_ratio\\\", 0.0) or 0.0\\n    if warmup_ratio > 0:\\n        return min(int(train_iters * warmup_ratio), train_iters)\\n    return 0\\n\\n\\ndef _resolve_decay_iters(train_iters: int, warmup_steps: int) -> int:\\n    r\\\"\\\"\\\"Ensure decay span is longer than warmup so Megatron does not shrink warmup.\\n\\n    Megatron Bridge caps ``lr_warmup_steps`` whenever it is ``>= lr_decay_steps``,\\n    so keep decay strictly larger than warmup on short comparison runs.\\n    \\\"\\\"\\\"\\n    if warmup_steps <= 0:\\n        return train_iters\\n    return max(train_iters, warmup_steps + 1)\\n\\n\\ndef _import_training_config():\\n    from megatron.bridge.training.config import (\\n        CheckpointConfig,\\n        ConfigContainer,\\n        FinetuningDatasetConfig,\\n        GPTDatasetConfig,\\n        LoggerConfig,\\n        RNGConfig,\\n        TrainingConfig,\\n    )\\n\\n    try:\\n        from megatron.bridge.training.config import DistributedInitConfig\\n    except ImportError:\\n        DistributedInitConfig = None\\n\\n    try:\\n        from megatron.bridge.training.config import ValidationConfig\\n    except ImportError:\\n        ValidationConfig = None\\n\\n    try:\\n        from megatron.bridge.training.tokenizers.config import TokenizerConfig\\n    except ImportError:\\n        from megatron.bridge.training.config import TokenizerConfig\\n\\n    return (\\n        CheckpointConfig,\\n        ConfigContainer,\\n        DistributedInitConfig,\\n        FinetuningDatasetConfig,\\n        GPTDatasetConfig,\\n        LoggerConfig,\\n        RNGConfig,\\n        TokenizerConfig,\\n        TrainingConfig,\\n        ValidationConfig,\\n    )\\n\\n\\ndef _create_optimizer_scheduler(\\n    training_args: \\\"TrainingArguments\\\",\\n    warmup_steps: int,\\n    train_iters: int,\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    use_distributed_optimizer: bool,\\n):\\n    from megatron.bridge.training.config import OptimizerConfig, SchedulerConfig\\n\\n    finetuning_type = finetuning_args.finetuning_type\\n    learning_rate = training_args.learning_rate\\n    if finetuning_type in (\\\"lora\\\", \\\"full\\\"):\\n        max_lr, min_lr, default_beta2 = learning_rate, 0.0, 0.999\\n    else:\\n        max_lr, min_lr, default_beta2 = learning_rate, learning_rate * 0.1, 0.95\\n\\n    # Match Hugging Face Trainer defaults unless the user overrides them.\\n    adam_beta1 = getattr(training_args, \\\"adam_beta1\\\", 0.9)\\n    adam_beta2 = getattr(training_args, \\\"adam_beta2\\\", default_beta2)\\n    adam_eps = getattr(training_args, \\\"adam_epsilon\\\", 1e-8)\\n    weight_decay = getattr(training_args, \\\"weight_decay\\\", 0.0)\\n    max_grad_norm = getattr(training_args, \\\"max_grad_norm\\\", 1.0)\\n    decay_iters = _resolve_decay_iters(train_iters, warmup_steps)\\n    optimizer = OptimizerConfig(\\n        optimizer=\\\"adam\\\",\\n        lr=max_lr,\\n        min_lr=min_lr,\\n        weight_decay=weight_decay,\\n        bf16=getattr(training_args, \\\"bf16\\\", True),\\n        fp16=getattr(training_args, \\\"fp16\\\", False),\\n        adam_beta1=adam_beta1,\\n        adam_beta2=adam_beta2,\\n        adam_eps=adam_eps,\\n        use_distributed_optimizer=use_distributed_optimizer,\\n        clip_grad=max_grad_norm,\\n    )\\n    scheduler = SchedulerConfig(\\n        start_weight_decay=weight_decay,\\n        end_weight_decay=weight_decay,\\n        weight_decay_incr_style=\\\"constant\\\",\\n        lr_decay_style=_map_lr_scheduler_type(getattr(training_args, \\\"lr_scheduler_type\\\", \\\"cosine\\\")),\\n        lr_wsd_decay_style=\\\"minus_sqrt\\\",\\n        lr_wsd_decay_iters=decay_iters,\\n        lr_warmup_iters=warmup_steps,\\n        lr_warmup_init=0.0,\\n        lr_decay_iters=decay_iters,\\n        override_opt_param_scheduler=True,\\n    )\\n    return optimizer, scheduler\\n\\n\\ndef ensure_create_sft_dataset_applies_chat_template() -> None:\\n    r\\\"\\\"\\\"Apply ``dataset_kwargs['chat_template']`` before Megatron builds SFT datasets.\\n\\n    Megatron Bridge only pops ``chat_template`` on the packed-sequence path. The\\n    non-packed finetuning path would otherwise forward it as an unexpected kwarg.\\n    Patch both the defining module and the builder import binding.\\n    \\\"\\\"\\\"\\n    from megatron.bridge.data.builders import finetuning_dataset as finetuning_module\\n    from megatron.bridge.data.datasets import sft as sft_module\\n\\n    if getattr(sft_module.create_sft_dataset, \\\"_llamafactory_chat_template_patched\\\", False):\\n        return\\n\\n    original = sft_module.create_sft_dataset\\n\\n    def create_sft_dataset(*args, **kwargs):\\n        chat_template = kwargs.pop(\\\"chat_template\\\", None)\\n        tokenizer = kwargs.get(\\\"tokenizer\\\")\\n        if tokenizer is None and len(args) >= 2:\\n            tokenizer = args[1]\\n        if chat_template is not None and tokenizer is not None:\\n            # Megatron `_chat_preprocess` may read either the wrapper or the\\n            # inner HuggingFace tokenizer depending on `legacy`.\\n            if hasattr(tokenizer, \\\"chat_template\\\"):\\n                tokenizer.chat_template = chat_template\\n            hf_tokenizer = getattr(tokenizer, \\\"_tokenizer\\\", None)\\n            if hf_tokenizer is not None and hasattr(hf_tokenizer, \\\"chat_template\\\"):\\n                hf_tokenizer.chat_template = chat_template\\n        return original(*args, **kwargs)\\n\\n    create_sft_dataset._llamafactory_chat_template_patched = True  # type: ignore[attr-defined]\\n    sft_module.create_sft_dataset = create_sft_dataset\\n    finetuning_module.create_sft_dataset = create_sft_dataset\\n    logger.info_rank0(\\\"Patched Megatron create_sft_dataset to apply chat_template overrides.\\\")\\n\\n\\ndef _create_peft_config(finetuning_args: \\\"FinetuningArguments\\\"):\\n    if finetuning_args.finetuning_type != \\\"lora\\\":\\n        return None\\n\\n    from megatron.bridge.peft.lora import LoRA\\n\\n    default_targets = [\\\"linear_qkv\\\", \\\"linear_proj\\\", \\\"linear_fc1\\\", \\\"linear_fc2\\\"]\\n    if list(finetuning_args.lora_target) != [\\\"all\\\"]:\\n        logger.warning_rank0(\\n            f\\\"Custom lora_target {finetuning_args.lora_target} is not supported by Megatron Bridge. \\\"\\n            f\\\"Using default Megatron target modules: {default_targets}.\\\"\\n        )\\n\\n    return LoRA(\\n        target_modules=default_targets,\\n        dim=finetuning_args.lora_rank,\\n        alpha=finetuning_args.lora_alpha,\\n    )\\n\\n\\ndef _build_gpt_dataset_config(\\n    GPTDatasetConfig,\\n    dataset_path: str,\\n    seq_length: int,\\n    seed: int,\\n    num_workers: int,\\n):\\n    kwargs: dict[str, Any] = {\\n        \\\"random_seed\\\": seed,\\n        \\\"reset_attention_mask\\\": False,\\n        \\\"reset_position_ids\\\": False,\\n        \\\"eod_mask_loss\\\": False,\\n        \\\"blend\\\": ([dataset_path], 1.0),\\n        \\\"split\\\": \\\"100,0,0\\\",\\n        \\\"num_workers\\\": num_workers,\\n        \\\"data_sharding\\\": True,\\n        \\\"dataloader_type\\\": \\\"single\\\",\\n    }\\n    if \\\"sequence_length\\\" in GPTDatasetConfig.__dataclass_fields__:\\n        kwargs[\\\"sequence_length\\\"] = seq_length\\n    else:\\n        kwargs[\\\"seq_length\\\"] = seq_length\\n    if \\\"num_dataset_builder_threads\\\" in GPTDatasetConfig.__dataclass_fields__:\\n        kwargs[\\\"num_dataset_builder_threads\\\"] = 1\\n    return GPTDatasetConfig(**kwargs)\\n\\n\\ndef _build_finetuning_dataset_config(\\n    FinetuningDatasetConfig,\\n    dataset_root: str,\\n    seq_length: int,\\n    seed: int,\\n    num_workers: int,\\n    do_validation: bool,\\n    dataset_kwargs: dict[str, Any],\\n    packed_sequence_specs,\\n    disable_shuffling: bool = False,\\n):\\n    kwargs: dict[str, Any] = {\\n        \\\"dataset_root\\\": dataset_root,\\n        \\\"seq_length\\\": seq_length,\\n        \\\"seed\\\": seed,\\n        \\\"num_workers\\\": num_workers,\\n        \\\"do_validation\\\": do_validation,\\n        \\\"do_test\\\": False,\\n        \\\"dataset_kwargs\\\": dataset_kwargs,\\n        \\\"packed_sequence_specs\\\": packed_sequence_specs,\\n    }\\n    if \\\"dataloader_type\\\" in FinetuningDatasetConfig.__dataclass_fields__:\\n        from .dataset_export import get_finetuning_dataloader_type\\n\\n        kwargs[\\\"dataloader_type\\\"] = get_finetuning_dataloader_type(disable_shuffling=disable_shuffling)\\n    return FinetuningDatasetConfig(**kwargs)\\n\\n\\ndef _has_megatron_checkpoint(output_dir: str) -> bool:\\n    r\\\"\\\"\\\"Return whether ``output_dir`` contains a resumable Megatron checkpoint.\\\"\\\"\\\"\\n    return any(\\n        os.path.isfile(os.path.join(output_dir, name))\\n        for name in (\\\"latest_checkpointed_iteration.txt\\\", \\\"latest_train_state.pt\\\")\\n    )\\n\\n\\ndef _should_resume_checkpoint(training_args: \\\"TrainingArguments\\\") -> bool:\\n    r\\\"\\\"\\\"Resume only when a tracker exists and ``overwrite_output_dir`` is false.\\\"\\\"\\\"\\n    if getattr(training_args, \\\"overwrite_output_dir\\\", False):\\n        return False\\n    return _has_megatron_checkpoint(training_args.output_dir)\\n\\n\\ndef _create_base_config(\\n    *,\\n    training_args: \\\"TrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    train_iters: int,\\n    micro_batch_size: int,\\n    global_batch_size: int,\\n    mb_args: \\\"MegatronBridgeArguments\\\",\\n    is_sft: bool,\\n):\\n    from megatron.core.distributed import DistributedDataParallelConfig\\n\\n    (\\n        CheckpointConfig,\\n        ConfigContainer,\\n        DistributedInitConfig,\\n        _FinetuningDatasetConfig,\\n        _GPTDatasetConfig,\\n        LoggerConfig,\\n        RNGConfig,\\n        TokenizerConfig,\\n        TrainingConfig,\\n        ValidationConfig,\\n    ) = _import_training_config()\\n\\n    warmup_steps = _resolve_warmup_steps(training_args, train_iters)\\n    opt_cfg, scheduler_cfg = _create_optimizer_scheduler(\\n        training_args=training_args,\\n        warmup_steps=warmup_steps,\\n        train_iters=train_iters,\\n        finetuning_args=finetuning_args,\\n        use_distributed_optimizer=mb_args.use_distributed_optimizer,\\n    )\\n\\n    train_kwargs: dict[str, Any] = {\\n        \\\"train_iters\\\": train_iters,\\n        \\\"global_batch_size\\\": global_batch_size,\\n        \\\"micro_batch_size\\\": micro_batch_size,\\n    }\\n    eval_steps = training_args.eval_steps\\n    if ValidationConfig is not None:\\n        validation = ValidationConfig(eval_interval=eval_steps or 100, eval_iters=32)\\n    else:\\n        train_kwargs[\\\"eval_interval\\\"] = eval_steps or 100\\n        train_kwargs[\\\"eval_iters\\\"] = 32\\n        validation = None\\n\\n    output_dir = training_args.output_dir\\n    resume_checkpoint = _should_resume_checkpoint(training_args)\\n    # mcore >= 0.14 removed ShardedTensor.flattened_range. The legacy default\\n    # sharding type ``fully_sharded_model_space`` still depends on it, so prefer\\n    # the fully_reshardable distributed-optimizer format when dist opt is on.\\n    dist_ckpt_optim_fully_reshardable = mb_args.use_distributed_optimizer\\n    dist_cfg = DistributedInitConfig() if DistributedInitConfig is not None else None\\n    container_kwargs: dict[str, Any] = {\\n        \\\"model\\\": None,\\n        \\\"train\\\": TrainingConfig(**train_kwargs),\\n        \\\"optimizer\\\": opt_cfg,\\n        \\\"scheduler\\\": scheduler_cfg,\\n        \\\"ddp\\\": DistributedDataParallelConfig(\\n            check_for_nan_in_grad=True,\\n            grad_reduce_in_fp32=True,\\n            overlap_grad_reduce=mb_args.overlap_grad_reduce,\\n            overlap_param_gather=mb_args.overlap_param_gather,\\n            use_distributed_optimizer=mb_args.use_distributed_optimizer,\\n        ),\\n        \\\"dataset\\\": None,\\n        \\\"logger\\\": LoggerConfig(\\n            log_interval=training_args.logging_steps,\\n            tensorboard_dir=os.path.join(output_dir, \\\"tb_logs\\\"),\\n        ),\\n        \\\"tokenizer\\\": TokenizerConfig(\\n            tokenizer_type=\\\"HuggingFaceTokenizer\\\",\\n            tokenizer_model=None,\\n        ),\\n        \\\"checkpoint\\\": CheckpointConfig(\\n            save_interval=training_args.save_steps,\\n            save=output_dir,\\n            load=output_dir if resume_checkpoint else None,\\n            # SFT from pretrained should not load optimizer/RNG from a partial ckpt.\\n            finetune=is_sft and not resume_checkpoint,\\n            ckpt_format=\\\"torch_dist\\\",\\n            fully_parallel_save=False,\\n            use_persistent_ckpt_worker=False,\\n            save_optim=True,\\n            dist_ckpt_optim_fully_reshardable=dist_ckpt_optim_fully_reshardable,\\n        ),\\n        \\\"rng\\\": RNGConfig(seed=training_args.seed),\\n        \\\"mixed_precision\\\": mb_args.mixed_precision,\\n        \\\"peft\\\": _create_peft_config(finetuning_args) if is_sft and finetuning_args.finetuning_type == \\\"lora\\\" else None,\\n    }\\n    if validation is not None:\\n        container_kwargs[\\\"validation\\\"] = validation\\n    if dist_cfg is not None:\\n        container_kwargs[\\\"dist\\\"] = dist_cfg\\n\\n    return ConfigContainer(**container_kwargs)\\n\\n\\ndef _compute_train_schedule(\\n    training_args: \\\"TrainingArguments\\\",\\n    mb_args: \\\"MegatronBridgeArguments\\\",\\n    num_train_samples: int,\\n) -> tuple[int, int, int]:\\n    micro_batch_size = training_args.per_device_train_batch_size\\n    global_batch_size = micro_batch_size * training_args.gradient_accumulation_steps * training_args.world_size\\n    parallel_size = (\\n        mb_args.tensor_model_parallel_size\\n        * mb_args.pipeline_model_parallel_size\\n        * mb_args.context_parallel_size\\n        * mb_args.expert_model_parallel_size\\n    )\\n    global_batch_size //= parallel_size\\n    global_batch_size = max(global_batch_size, micro_batch_size)\\n\\n    max_steps = getattr(training_args, \\\"max_steps\\\", -1)\\n    if max_steps is not None and max_steps > 0:\\n        train_iters = max_steps\\n    else:\\n        train_iters = max(1, math.ceil(num_train_samples / global_batch_size * training_args.num_train_epochs))\\n    return micro_batch_size, global_batch_size, train_iters\\n\\n\\ndef _is_apex_grad_accum_fusion_available() -> bool:\\n    try:\\n        import fused_weight_gradient_mlp_cuda  # noqa: F401\\n\\n        return True\\n    except ImportError:\\n        return False\\n\\n\\ndef _apply_fusion_safety(model_provider) -> None:\\n    r\\\"\\\"\\\"Disable gradient_accumulation_fusion when the APEX CUDA extension is missing.\\n\\n    Megatron Bridge enables this fusion when TransformerEngine is installed, but\\n    ColumnParallelLinear (e.g. the output layer) still requires the APEX\\n    fused_weight_gradient_mlp_cuda extension at model construction time.\\n    \\\"\\\"\\\"\\n    if getattr(model_provider, \\\"gradient_accumulation_fusion\\\", False) and not _is_apex_grad_accum_fusion_available():\\n        logger.warning_rank0(\\n            \\\"Disabling gradient_accumulation_fusion because the APEX CUDA extension \\\"\\n            \\\"fused_weight_gradient_mlp_cuda is not installed.\\\"\\n        )\\n        model_provider.gradient_accumulation_fusion = False\\n\\n\\ndef _apply_optional_provider_attr(model_provider, name: str, value) -> None:\\n    if value is None or not hasattr(model_provider, name):\\n        return\\n    setattr(model_provider, name, value)\\n\\n\\ndef _apply_model_parallelism(model_provider, mb_args: \\\"MegatronBridgeArguments\\\") -> None:\\n    model_provider.tensor_model_parallel_size = mb_args.tensor_model_parallel_size\\n    model_provider.pipeline_model_parallel_size = mb_args.pipeline_model_parallel_size\\n    if hasattr(model_provider, \\\"expert_model_parallel_size\\\"):\\n        model_provider.expert_model_parallel_size = mb_args.expert_model_parallel_size\\n    model_provider.context_parallel_size = mb_args.context_parallel_size\\n    model_provider.sequence_parallel = mb_args.sequence_parallel\\n    _apply_optional_provider_attr(\\n        model_provider, \\\"virtual_pipeline_model_parallel_size\\\", mb_args.virtual_pipeline_model_parallel_size\\n    )\\n    _apply_optional_provider_attr(model_provider, \\\"recompute_granularity\\\", mb_args.recompute_granularity)\\n    _apply_optional_provider_attr(model_provider, \\\"recompute_method\\\", mb_args.recompute_method)\\n    _apply_optional_provider_attr(model_provider, \\\"recompute_num_layers\\\", mb_args.recompute_num_layers)\\n    _apply_optional_provider_attr(\\n        model_provider, \\\"account_for_embedding_in_pipeline_split\\\", mb_args.account_for_embedding_in_pipeline_split\\n    )\\n    _apply_optional_provider_attr(\\n        model_provider, \\\"account_for_loss_in_pipeline_split\\\", mb_args.account_for_loss_in_pipeline_split\\n    )\\n    _apply_optional_provider_attr(model_provider, \\\"bias_activation_fusion\\\", mb_args.bias_activation_fusion)\\n    _apply_optional_provider_attr(model_provider, \\\"apply_rope_fusion\\\", mb_args.apply_rope_fusion)\\n    _apply_optional_provider_attr(model_provider, \\\"masked_softmax_fusion\\\", mb_args.masked_softmax_fusion)\\n    _apply_optional_provider_attr(model_provider, \\\"cross_entropy_loss_fusion\\\", mb_args.cross_entropy_loss_fusion)\\n    _apply_optional_provider_attr(model_provider, \\\"moe_grouped_gemm\\\", mb_args.moe_grouped_gemm)\\n    _apply_optional_provider_attr(model_provider, \\\"moe_token_dispatcher_type\\\", mb_args.moe_token_dispatcher_type)\\n    _apply_optional_provider_attr(model_provider, \\\"calculate_per_token_loss\\\", mb_args.calculate_per_token_loss)\\n\\n\\ndef _apply_context_parallel_finetuning_requirements(cfg, mb_args: \\\"MegatronBridgeArguments\\\") -> None:\\n    r\\\"\\\"\\\"Apply Megatron Bridge SFT requirements when context parallelism is enabled.\\\"\\\"\\\"\\n    if mb_args.context_parallel_size <= 1:\\n        return\\n    cfg.model.calculate_per_token_loss = True\\n    cfg.ddp.average_in_collective = False\\n\\n\\ndef _apply_extra_overrides(cfg, extra: dict) -> None:\\n    for key, value in extra.items():\\n        parts = key.split(\\\".\\\")\\n        obj = cfg\\n        for part in parts[:-1]:\\n            obj = getattr(obj, part)\\n        setattr(obj, parts[-1], value)\\n\\n\\ndef _reset_megatron_bridge_global_state_after_checkpoint_conversion() -> None:\\n    r\\\"\\\"\\\"Clear Megatron globals left over from HF-to-Megatron conversion.\\n\\n    save_megatron_model() can implicitly initialize the rerun state machine while\\n    writing checkpoints. provide_distributed_model() also initializes model parallel\\n    groups. Training later calls initialize_megatron(), which expects a fresh global\\n    state and fails with \\\"Rerun state machine is already initialized\\\" or keeps stale\\n    parallel groups that mismatch the configured tensor/pipeline/context parallel sizes.\\n    \\\"\\\"\\\"\\n    from megatron.core import parallel_state\\n    from megatron.core.rerun_state_machine import destroy_rerun_state_machine\\n\\n    destroy_rerun_state_machine()\\n    parallel_state.destroy_model_parallel()\\n\\n\\ndef ensure_megatron_pretrained_checkpoint(\\n    model_args: \\\"ModelArguments\\\",\\n    mb_args: \\\"MegatronBridgeArguments\\\",\\n    output_dir: str,\\n) -> str:\\n    r\\\"\\\"\\\"Convert Hugging Face weights to Megatron format when needed.\\\"\\\"\\\"\\n    from megatron.bridge import AutoBridge\\n\\n    if mb_args.megatron_pretrained_checkpoint and os.path.isdir(mb_args.megatron_pretrained_checkpoint):\\n        return mb_args.megatron_pretrained_checkpoint\\n\\n    ckpt_dir = os.path.join(output_dir, \\\"megatron_pretrained\\\")\\n    if os.path.isdir(ckpt_dir) and os.listdir(ckpt_dir):\\n        logger.info_rank0(f\\\"Reusing existing Megatron checkpoint at {ckpt_dir}.\\\")\\n        return ckpt_dir\\n\\n    os.makedirs(ckpt_dir, exist_ok=True)\\n    logger.info_rank0(f\\\"Converting Hugging Face weights to Megatron format at {ckpt_dir}...\\\")\\n    bridge = AutoBridge.from_hf_pretrained(\\n        model_args.model_name_or_path,\\n        trust_remote_code=model_args.trust_remote_code,\\n    )\\n    provider = bridge.to_megatron_provider()\\n    _apply_model_parallelism(provider, mb_args)\\n    _apply_fusion_safety(provider)\\n    if hasattr(provider, \\\"finalize\\\"):\\n        provider.finalize()\\n    # TP/PP/CP weight scatter uses NCCL, which cannot operate on CPU tensors.\\n    use_cpu_initialization = (\\n        mb_args.tensor_model_parallel_size == 1\\n        and mb_args.pipeline_model_parallel_size == 1\\n        and mb_args.context_parallel_size == 1\\n    )\\n    if not use_cpu_initialization:\\n        logger.info_rank0(\\n            \\\"Using GPU initialization for Megatron checkpoint conversion because model parallelism \\\"\\n            \\\"requires NCCL scatter/gather on CUDA tensors.\\\"\\n        )\\n    try:\\n        megatron_model = provider.provide_distributed_model(\\n            wrap_with_ddp=False,\\n            use_cpu_initialization=use_cpu_initialization,\\n        )\\n        hf_tokenizer_kwargs = {\\\"trust_remote_code\\\": True} if model_args.trust_remote_code else None\\n        bridge.save_megatron_model(\\n            megatron_model,\\n            ckpt_dir,\\n            hf_tokenizer_path=model_args.model_name_or_path,\\n            hf_tokenizer_kwargs=hf_tokenizer_kwargs,\\n            low_memory_save=True,\\n        )\\n    finally:\\n        _reset_megatron_bridge_global_state_after_checkpoint_conversion()\\n    return ckpt_dir\\n\\n\\ndef build_pretrain_config(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"TrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    mb_args: \\\"MegatronBridgeArguments\\\",\\n    dataset_path: str,\\n    num_train_samples: int,\\n):\\n    from megatron.bridge import AutoBridge\\n\\n    micro_batch_size, global_batch_size, train_iters = _compute_train_schedule(\\n        training_args, mb_args, num_train_samples\\n    )\\n    cfg = _create_base_config(\\n        training_args=training_args,\\n        finetuning_args=finetuning_args,\\n        train_iters=train_iters,\\n        micro_batch_size=micro_batch_size,\\n        global_batch_size=global_batch_size,\\n        mb_args=mb_args,\\n        is_sft=False,\\n    )\\n\\n    (\\n        _CheckpointConfig,\\n        _ConfigContainer,\\n        _DistributedInitConfig,\\n        _FinetuningDatasetConfig,\\n        GPTDatasetConfig,\\n        _LoggerConfig,\\n        _RNGConfig,\\n        _TokenizerConfig,\\n        _TrainingConfig,\\n        _ValidationConfig,\\n    ) = _import_training_config()\\n    bridge = AutoBridge.from_hf_pretrained(\\n        model_args.model_name_or_path,\\n        trust_remote_code=model_args.trust_remote_code,\\n    )\\n    cfg.model = bridge.to_megatron_provider(load_weights=False)\\n    _apply_model_parallelism(cfg.model, mb_args)\\n    _apply_fusion_safety(cfg.model)\\n    if hasattr(cfg.model, \\\"seq_length\\\"):\\n        cfg.model.seq_length = data_args.cutoff_len\\n\\n    cfg.tokenizer.tokenizer_model = model_args.model_name_or_path\\n    cfg.dataset = _build_gpt_dataset_config(\\n        GPTDatasetConfig,\\n        dataset_path=dataset_path,\\n        seq_length=data_args.cutoff_len,\\n        seed=training_args.seed,\\n        num_workers=data_args.preprocessing_num_workers,\\n    )\\n\\n    _apply_extra_overrides(cfg, mb_args.load_extra_config())\\n    return cfg\\n\\n\\ndef build_sft_config(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"TrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    mb_args: \\\"MegatronBridgeArguments\\\",\\n    dataset_root: str,\\n    pretrained_checkpoint: str,\\n    num_train_samples: int,\\n):\\n    from megatron.bridge import AutoBridge\\n    from megatron.bridge.data.datasets.packed_sequence import PackedSequenceSpecs\\n\\n    micro_batch_size, global_batch_size, train_iters = _compute_train_schedule(\\n        training_args, mb_args, num_train_samples\\n    )\\n    cfg = _create_base_config(\\n        training_args=training_args,\\n        finetuning_args=finetuning_args,\\n        train_iters=train_iters,\\n        micro_batch_size=micro_batch_size,\\n        global_batch_size=global_batch_size,\\n        mb_args=mb_args,\\n        is_sft=True,\\n    )\\n\\n    (\\n        _CheckpointConfig,\\n        _ConfigContainer,\\n        _DistributedInitConfig,\\n        FinetuningDatasetConfig,\\n        _GPTDatasetConfig,\\n        _LoggerConfig,\\n        _RNGConfig,\\n        _TokenizerConfig,\\n        _TrainingConfig,\\n        _ValidationConfig,\\n    ) = _import_training_config()\\n    bridge = AutoBridge.from_hf_pretrained(\\n        model_args.model_name_or_path,\\n        trust_remote_code=model_args.trust_remote_code,\\n    )\\n    cfg.model = bridge.to_megatron_provider(load_weights=False)\\n    _apply_model_parallelism(cfg.model, mb_args)\\n    _apply_fusion_safety(cfg.model)\\n    if hasattr(cfg.model, \\\"seq_length\\\"):\\n        cfg.model.seq_length = data_args.cutoff_len\\n\\n    cfg.tokenizer.tokenizer_model = model_args.model_name_or_path\\n\\n    from .dataset_export import get_sft_dataset_kwargs\\n\\n    ensure_create_sft_dataset_applies_chat_template()\\n    dataset_kwargs = get_sft_dataset_kwargs(\\n        tokenizer_path=model_args.model_name_or_path,\\n        trust_remote_code=model_args.trust_remote_code,\\n        template_name=data_args.template,\\n    )\\n    packed_sequence_specs = None\\n    if mb_args.use_packed_sequences:\\n        pad_seq_to_mult = mb_args.context_parallel_size * 2 if mb_args.context_parallel_size > 1 else 1\\n        packed_sequence_specs = PackedSequenceSpecs(\\n            packed_sequence_size=data_args.cutoff_len,\\n            pad_seq_to_mult=pad_seq_to_mult,\\n        )\\n        dataset_kwargs[\\\"pad_to_max_length\\\"] = True\\n\\n    cfg.dataset = _build_finetuning_dataset_config(\\n        FinetuningDatasetConfig,\\n        dataset_root=dataset_root,\\n        seq_length=data_args.cutoff_len,\\n        seed=training_args.seed,\\n        num_workers=data_args.preprocessing_num_workers,\\n        do_validation=data_args.val_size > 0 or data_args.eval_dataset is not None,\\n        dataset_kwargs=dataset_kwargs,\\n        packed_sequence_specs=packed_sequence_specs,\\n        disable_shuffling=getattr(finetuning_args, \\\"disable_shuffling\\\", False),\\n    )\\n    cfg.checkpoint.pretrained_checkpoint = pretrained_checkpoint\\n\\n    _apply_context_parallel_finetuning_requirements(cfg, mb_args)\\n    _apply_extra_overrides(cfg, mb_args.load_extra_config())\\n    return cfg\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/megatron_bridge/dataset_export.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7ad1a26162d834475e28d8c2b39abf79ad9b726986d153d591017185cbd5062d\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport inspect\\nimport json\\nimport os\\nimport re\\nimport typing\\nfrom typing import TYPE_CHECKING, Any, Optional\\n\\nfrom ...extras.logging import get_logger\\n\\n\\nif TYPE_CHECKING:\\n    from datasets import Dataset, IterableDataset\\n\\n\\nlogger = get_logger(__name__)\\n_GENERATION_REGEX = re.compile(r\\\"\\\\{%-?\\\\s+generation\\\\s+-?%\\\\}\\\")\\n_END_GENERATION_REGEX = re.compile(r\\\"\\\\{%-?\\\\s+endgeneration\\\\s+-?%\\\\}\\\")\\n_ASSISTANT_ELIF_REGEX = re.compile(\\n    r\\\"(\\\\{%\\\\s*elif\\\\s+message\\\\['role'\\\\]\\\\s*==\\\\s*'assistant'\\\\s*%\\\\})\\\"\\n    r\\\"(.*?)\\\"\\n    r\\\"(\\\\{%\\\\s*endif\\\\s*%\\\\})\\\",\\n    flags=re.DOTALL,\\n)\\n\\n\\ndef supports_hf_chat_template() -> bool:\\n    r\\\"\\\"\\\"Return whether the installed Megatron Bridge supports HF chat templates.\\\"\\\"\\\"\\n    try:\\n        from megatron.bridge.data.datasets.sft import GPTSFTChatDataset\\n\\n        return \\\"use_hf_tokenizer_chat_template\\\" in inspect.signature(GPTSFTChatDataset.__init__).parameters\\n    except Exception:\\n        return False\\n\\n\\ndef _inject_generation_block(chat_template: str) -> str:\\n    r\\\"\\\"\\\"Wrap assistant content with ``{% generation %}`` when missing.\\\"\\\"\\\"\\n    if _GENERATION_REGEX.search(chat_template):\\n        return chat_template\\n\\n    match = _ASSISTANT_ELIF_REGEX.search(chat_template)\\n    if match is None:\\n        raise ValueError(\\n            \\\"Cannot inject {% generation %} into chat template: \\\"\\n            \\\"no `{% elif message['role'] == 'assistant' %}` block found.\\\"\\n        )\\n\\n    body = match.group(2)\\n    if _END_GENERATION_REGEX.search(body):\\n        return chat_template\\n\\n    patched = (\\n        chat_template[: match.start()]\\n        + match.group(1)\\n        + \\\"{% generation %}\\\"\\n        + body\\n        + \\\"{% endgeneration %}\\\"\\n        + match.group(3)\\n        + chat_template[match.end() :]\\n    )\\n    if not _GENERATION_REGEX.search(patched):\\n        raise ValueError(\\\"Failed to inject {% generation %} into chat template.\\\")\\n    return patched\\n\\n\\ndef build_chat_template_with_generation(\\n    tokenizer_path: str | None,\\n    trust_remote_code: bool = False,\\n    template_name: str | None = None,\\n) -> str | None:\\n    r\\\"\\\"\\\"Build a chat template that supports assistant-only loss masks.\\n\\n    Prefers the LLaMA-Factory registered template (same formatting as HF Trainer),\\n    then falls back to patching the tokenizer's native chat template.\\n    \\\"\\\"\\\"\\n    if not tokenizer_path:\\n        return None\\n\\n    try:\\n        from transformers import AutoTokenizer\\n\\n        tokenizer = AutoTokenizer.from_pretrained(tokenizer_path, trust_remote_code=trust_remote_code)\\n    except Exception as exc:\\n        logger.warning_rank0(f\\\"Failed to load tokenizer for chat template patching: {exc}\\\")\\n        return None\\n\\n    if template_name:\\n        try:\\n            from ...data.template import TEMPLATES\\n\\n            template = TEMPLATES.get(template_name)\\n            if template is not None:\\n                return _inject_generation_block(template._get_jinja_template(tokenizer))\\n        except Exception as exc:\\n            logger.warning_rank0(f\\\"Failed to build LLaMA-Factory chat template '{template_name}': {exc}\\\")\\n\\n    native = tokenizer.chat_template\\n    if not isinstance(native, str) or not native:\\n        return None\\n\\n    try:\\n        return _inject_generation_block(native)\\n    except Exception as exc:\\n        logger.warning_rank0(f\\\"Failed to inject {{% generation %}} into native chat template: {exc}\\\")\\n        return None\\n\\n\\ndef tokenizer_supports_hf_chat_template(\\n    tokenizer_path: str | None,\\n    trust_remote_code: bool = False,\\n    template_name: str | None = None,\\n) -> bool:\\n    r\\\"\\\"\\\"Return whether Megatron Bridge can use HF chat templates for this tokenizer.\\\"\\\"\\\"\\n    if not supports_hf_chat_template() or not tokenizer_path:\\n        return False\\n\\n    try:\\n        from transformers import AutoTokenizer\\n\\n        tokenizer = AutoTokenizer.from_pretrained(tokenizer_path, trust_remote_code=trust_remote_code)\\n        if _GENERATION_REGEX.search(tokenizer.chat_template or \\\"\\\"):\\n            return True\\n    except Exception as exc:\\n        logger.warning_rank0(f\\\"Failed to inspect tokenizer chat template: {exc}\\\")\\n        return False\\n\\n    return build_chat_template_with_generation(tokenizer_path, trust_remote_code, template_name) is not None\\n\\n\\ndef get_sft_dataset_kwargs(\\n    tokenizer_path: str | None = None,\\n    trust_remote_code: bool = False,\\n    template_name: str | None = None,\\n) -> dict[str, Any]:\\n    r\\\"\\\"\\\"Return dataset kwargs compatible with the installed Megatron Bridge version.\\\"\\\"\\\"\\n    kwargs: dict[str, Any] = {\\\"chat\\\": True}\\n    if not tokenizer_supports_hf_chat_template(tokenizer_path, trust_remote_code, template_name):\\n        return kwargs\\n\\n    chat_template = build_chat_template_with_generation(tokenizer_path, trust_remote_code, template_name)\\n    if chat_template is None:\\n        return kwargs\\n\\n    kwargs[\\\"use_hf_tokenizer_chat_template\\\"] = True\\n    kwargs[\\\"chat_template\\\"] = chat_template\\n    # Chat templates already include BOS/EOS / turn markers.\\n    kwargs[\\\"add_bos\\\"] = False\\n    kwargs[\\\"add_eos\\\"] = False\\n    logger.info_rank0(\\n        \\\"Using HuggingFace chat template with {% generation %} for Megatron Bridge SFT \\\"\\n        f\\\"(template={template_name or 'native'}).\\\"\\n    )\\n    return kwargs\\n\\n\\ndef get_finetuning_dataloader_type(disable_shuffling: bool = False) -> str:\\n    r\\\"\\\"\\\"Return a finetuning dataloader type supported by the installed Megatron Bridge.\\n\\n    Prefer sequential ``batch``/``single`` samplers. When shuffling is disabled for\\n    HF loss comparison, avoid the random ``cyclic`` sampler.\\n    \\\"\\\"\\\"\\n    try:\\n        from megatron.bridge.training.config import FinetuningDatasetConfig\\n\\n        field = FinetuningDatasetConfig.__dataclass_fields__.get(\\\"dataloader_type\\\")\\n        if field is None:\\n            return \\\"single\\\"\\n\\n        choices: set[str] = set()\\n        for arg in typing.get_args(field.type):\\n            for choice in typing.get_args(arg):\\n                if isinstance(choice, str):\\n                    choices.add(choice)\\n\\n        if disable_shuffling:\\n            if \\\"batch\\\" in choices:\\n                return \\\"batch\\\"\\n            if \\\"single\\\" in choices:\\n                return \\\"single\\\"\\n            return next(iter(choices), \\\"single\\\")\\n\\n        if \\\"batch\\\" in choices:\\n            return \\\"batch\\\"\\n        if \\\"single\\\" in choices:\\n            return \\\"single\\\"\\n        return next(iter(choices), \\\"single\\\")\\n    except Exception:\\n        return \\\"single\\\"\\n\\n\\ndef _role_to_sharegpt(role: str) -> str:\\n    mapping = {\\\"user\\\": \\\"User\\\", \\\"assistant\\\": \\\"Assistant\\\", \\\"system\\\": \\\"System\\\"}\\n    return mapping.get(role, role.capitalize())\\n\\n\\ndef _example_to_record(\\n    example: dict[str, Any], stage: str = \\\"sft\\\", use_messages_format: bool = True\\n) -> dict[str, Any] | None:\\n    r\\\"\\\"\\\"Convert an aligned LLaMA-Factory example to Megatron Bridge JSONL format.\\\"\\\"\\\"\\n    if example.get(\\\"text\\\") is not None:\\n        return {\\\"text\\\": example[\\\"text\\\"]}\\n\\n    prompt = example.get(\\\"_prompt\\\")\\n    if stage == \\\"pt\\\":\\n        if not prompt:\\n            return None\\n        return {\\\"text\\\": prompt[0][\\\"content\\\"]}\\n\\n    response = example.get(\\\"_response\\\")\\n    if not prompt or not response:\\n        return None\\n\\n    if use_messages_format:\\n        messages = []\\n        system = example.get(\\\"_system\\\")\\n        if system:\\n            messages.append({\\\"role\\\": \\\"system\\\", \\\"content\\\": system})\\n        for message in prompt:\\n            messages.append({\\\"role\\\": message[\\\"role\\\"], \\\"content\\\": message[\\\"content\\\"]})\\n        for message in response:\\n            messages.append({\\\"role\\\": message[\\\"role\\\"], \\\"content\\\": message[\\\"content\\\"]})\\n        record: dict[str, Any] = {\\\"messages\\\": messages}\\n        tools = example.get(\\\"_tools\\\")\\n        if tools:\\n            record[\\\"tools\\\"] = tools\\n        return record\\n\\n    conversations = []\\n    for message in prompt:\\n        conversations.append({\\\"from\\\": _role_to_sharegpt(message[\\\"role\\\"]), \\\"value\\\": message[\\\"content\\\"]})\\n    for message in response:\\n        conversations.append({\\\"from\\\": _role_to_sharegpt(message[\\\"role\\\"]), \\\"value\\\": message[\\\"content\\\"]})\\n\\n    return {\\n        \\\"system\\\": example.get(\\\"_system\\\") or \\\"\\\",\\n        \\\"conversations\\\": conversations,\\n        \\\"mask\\\": \\\"User\\\",\\n    }\\n\\n\\ndef _remove_stale_memmap_index(path: str) -> None:\\n    r\\\"\\\"\\\"Remove cached memmap index files after rewriting a JSONL dataset.\\\"\\\"\\\"\\n    for suffix in (\\\".idx.npy\\\", \\\".idx.info\\\"):\\n        index_path = path + suffix\\n        if os.path.exists(index_path):\\n            os.remove(index_path)\\n            logger.info_rank0(f\\\"Removed stale Megatron dataset index: {index_path}\\\")\\n\\n\\ndef _write_jsonl(\\n    path: str,\\n    dataset: \\\"Dataset | IterableDataset\\\",\\n    stage: str = \\\"sft\\\",\\n    use_messages_format: bool = True,\\n) -> int:\\n    count = 0\\n    parent = os.path.dirname(path)\\n    if parent:\\n        os.makedirs(parent, exist_ok=True)\\n    with open(path, \\\"w\\\", encoding=\\\"utf-8\\\") as f:\\n        for example in dataset:\\n            record = _example_to_record(example, stage=stage, use_messages_format=use_messages_format)\\n            if record is None:\\n                continue\\n            f.write(json.dumps(record, ensure_ascii=False) + \\\"\\\\n\\\")\\n            count += 1\\n    _remove_stale_memmap_index(path)\\n    return count\\n\\n\\ndef export_dataset_for_megatron_bridge(\\n    train_dataset: \\\"Dataset | IterableDataset\\\",\\n    output_dir: str,\\n    eval_dataset: Optional[\\\"Dataset | IterableDataset | dict[str, Dataset]\\\"] = None,\\n    val_size: float = 0.0,\\n    seed: int = 42,\\n    stage: str = \\\"sft\\\",\\n    model_name_or_path: str | None = None,\\n    trust_remote_code: bool = False,\\n    template_name: str | None = None,\\n) -> str:\\n    r\\\"\\\"\\\"Export aligned LLaMA-Factory datasets to Megatron Bridge JSONL files.\\\"\\\"\\\"\\n    os.makedirs(output_dir, exist_ok=True)\\n    use_messages_format = stage != \\\"sft\\\" or tokenizer_supports_hf_chat_template(\\n        model_name_or_path,\\n        trust_remote_code=trust_remote_code,\\n        template_name=template_name,\\n    )\\n    if stage == \\\"sft\\\" and not use_messages_format:\\n        logger.info_rank0(\\n            \\\"Cannot enable HuggingFace chat template for Megatron Bridge; \\\"\\n            \\\"exporting ShareGPT conversations for legacy preprocessing.\\\"\\n        )\\n\\n    if val_size > 0 and eval_dataset is None:\\n        split = train_dataset.train_test_split(test_size=val_size, seed=seed)\\n        train_dataset = split[\\\"train\\\"]\\n        eval_dataset = split[\\\"test\\\"]\\n\\n    train_path = os.path.join(output_dir, \\\"training.jsonl\\\")\\n    train_count = _write_jsonl(\\n        train_path,\\n        train_dataset,\\n        stage=stage,\\n        use_messages_format=use_messages_format,\\n    )\\n    logger.info_rank0(f\\\"Exported {train_count} training samples to {train_path}.\\\")\\n\\n    if isinstance(eval_dataset, dict):\\n        for name, dataset in eval_dataset.items():\\n            split_name = \\\"validation\\\" if name == \\\"validation\\\" else name\\n            eval_path = os.path.join(output_dir, f\\\"{split_name}.jsonl\\\")\\n            eval_count = _write_jsonl(\\n                eval_path,\\n                dataset,\\n                stage=stage,\\n                use_messages_format=use_messages_format,\\n            )\\n            logger.info_rank0(f\\\"Exported {eval_count} {split_name} samples to {eval_path}.\\\")\\n    elif eval_dataset is not None:\\n        eval_path = os.path.join(output_dir, \\\"validation.jsonl\\\")\\n        eval_count = _write_jsonl(\\n            eval_path,\\n            eval_dataset,\\n            stage=stage,\\n            use_messages_format=use_messages_format,\\n        )\\n        logger.info_rank0(f\\\"Exported {eval_count} validation samples to {eval_path}.\\\")\\n\\n    return output_dir\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/megatron_bridge/workflow.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0572782764067269458b102c5ee2ecd34b8d09c97d93a29ec807423abe6f7520\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport os\\nimport time\\nfrom collections.abc import Callable\\nfrom typing import TYPE_CHECKING, Optional\\n\\nfrom transformers import AutoConfig as HfAutoConfig\\n\\nfrom ...data.data_utils import split_dataset\\nfrom ...data.loader import _get_merged_dataset\\nfrom ...extras.constants import MEGATRON_BRIDGE_SUPPORTED_MODELS\\nfrom ...extras.logging import get_logger\\nfrom ...extras.packages import is_megatron_bridge_available\\nfrom .config_builder import (\\n    _apply_fusion_safety,\\n    build_pretrain_config,\\n    build_sft_config,\\n    ensure_megatron_pretrained_checkpoint,\\n)\\nfrom .dataset_export import export_dataset_for_megatron_bridge\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import TrainerCallback\\n\\n    from ...hparams import (\\n        DataArguments,\\n        FinetuningArguments,\\n        MegatronBridgeArguments,\\n        ModelArguments,\\n        TrainingArguments,\\n    )\\n\\n\\nlogger = get_logger(__name__)\\n\\n\\ndef _check_model_support(model_args: \\\"ModelArguments\\\") -> None:\\n    r\\\"\\\"\\\"Ensure the HF ``model_type`` is covered by the Megatron Bridge PT/SFT path.\\\"\\\"\\\"\\n    config = HfAutoConfig.from_pretrained(\\n        model_args.model_name_or_path, trust_remote_code=model_args.trust_remote_code\\n    )\\n    model_type = getattr(config, \\\"model_type\\\", None)\\n    if model_type not in MEGATRON_BRIDGE_SUPPORTED_MODELS:\\n        raise ValueError(\\n            f\\\"Model type `{model_type}` is not supported by the Megatron Bridge PT/SFT path. \\\"\\n            f\\\"Supported model types: {sorted(MEGATRON_BRIDGE_SUPPORTED_MODELS)}. \\\"\\n            \\\"Multimodal / audio / omni models are not enabled in v0.\\\"\\n        )\\n\\n\\ndef _run_on_main_process(training_args: \\\"TrainingArguments\\\", work: Callable[[], None], sync_dir: str) -> None:\\n    r\\\"\\\"\\\"Run ``work`` only on global rank 0, then synchronize other ranks.\\n\\n    Prefer ``torch.distributed.barrier`` when the process group is already initialized;\\n    otherwise fall back to a file flag under ``sync_dir`` so non-main ranks wait for\\n    shared filesystem writes (e.g. dataset export) to finish.\\n    \\\"\\\"\\\"\\n    done_file = os.path.join(sync_dir, \\\".main_process_done\\\")\\n    is_main = getattr(training_args, \\\"process_index\\\", 0) == 0\\n    wait_start = time.time()\\n\\n    import torch.distributed as dist\\n\\n    dist_ready = dist.is_available() and dist.is_initialized()\\n    if is_main:\\n        os.makedirs(sync_dir, exist_ok=True)\\n        if os.path.isfile(done_file):\\n            os.remove(done_file)\\n        work()\\n        with open(done_file, \\\"w\\\", encoding=\\\"utf-8\\\") as f:\\n            f.write(\\\"done\\\")\\n\\n    if dist_ready:\\n        dist.barrier()\\n    elif not is_main:\\n        while True:\\n            if os.path.isfile(done_file) and os.path.getmtime(done_file) >= wait_start - 1.0:\\n                break\\n            time.sleep(0.5)\\n\\n\\ndef _check_backend_available() -> None:\\n    if not is_megatron_bridge_available():\\n        raise ImportError(\\n            \\\"megatron-bridge is not installed. \\\"\\n            \\\"Please install it with `pip install --no-build-isolation megatron-bridge` \\\"\\n            \\\"or use the NeMo Framework container.\\\"\\n        )\\n    _patch_dataset_helper_compilation()\\n    _patch_dist_checkpoint_preload()\\n\\n\\ndef _patch_dist_checkpoint_preload() -> None:\\n    r\\\"\\\"\\\"Use blocking GPU->CPU copies when saving distributed checkpoints.\\n\\n    Megatron's default ``non_blocking=True`` preload can raise ``cudaErrorInvalidValue``\\n    on some GPUs (e.g. V100) when saving distributed optimizer shards, because pinned\\n    host memory allocation or async D2H transfer may fail under memory pressure.\\n    \\\"\\\"\\\"\\n    from megatron.core.dist_checkpointing.strategies import filesystem_async\\n\\n    if getattr(filesystem_async.FileSystemWriterAsync.preload_tensors, \\\"_llamafactory_patched\\\", False):\\n        return\\n\\n    original_preload = filesystem_async.FileSystemWriterAsync.preload_tensors\\n\\n    @staticmethod\\n    def preload_tensors(write_buckets, non_blocking=True):\\n        return original_preload(write_buckets, non_blocking=False)\\n\\n    preload_tensors._llamafactory_patched = True\\n    filesystem_async.FileSystemWriterAsync.preload_tensors = preload_tensors\\n    logger.info_rank0(\\\"Patched Megatron dist checkpoint preload to use blocking GPU->CPU copies.\\\")\\n\\n\\ndef _patch_dataset_helper_compilation() -> None:\\n    r\\\"\\\"\\\"Skip make-based helper compilation when the pybind extension is prebuilt.\\n\\n    Pip-installed megatron-core already ships helpers_cpp, but compile_helpers()\\n    still invokes make and fails when no Makefile is present.\\n    \\\"\\\"\\\"\\n    from megatron.core.datasets import utils as dataset_utils\\n\\n    if getattr(dataset_utils.compile_helpers, \\\"_llamafactory_patched\\\", False):\\n        return\\n\\n    try:\\n        import megatron.core.datasets.helpers_cpp  # noqa: F401\\n    except ImportError:\\n        return\\n\\n    def compile_helpers():\\n        import megatron.core.datasets.helpers_cpp  # noqa: F401\\n\\n    compile_helpers._llamafactory_patched = True\\n    dataset_utils.compile_helpers = compile_helpers\\n    logger.info_rank0(\\\"Using prebuilt megatron.core.datasets.helpers_cpp; skipping make compilation.\\\")\\n\\n\\ndef _load_aligned_datasets(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"TrainingArguments\\\",\\n    stage: str,\\n):\\n    dataset = _get_merged_dataset(data_args.dataset, model_args, data_args, training_args, stage)\\n    eval_dataset = _get_merged_dataset(\\n        data_args.eval_dataset,\\n        model_args,\\n        data_args,\\n        training_args,\\n        stage,\\n        return_dict=data_args.eval_on_each_dataset,\\n    )\\n    train_dict, eval_dict = split_dataset(dataset, eval_dataset, data_args, seed=training_args.seed)\\n    return train_dict.get(\\\"train\\\"), eval_dict\\n\\n\\ndef _latest_iter_checkpoint_dir(output_dir: str) -> Optional[str]:\\n    r\\\"\\\"\\\"Return the latest ``iter_*`` directory under ``output_dir``, if any.\\n\\n    ``export_adapter_ckpt`` needs the iteration directory that holds the\\n    distributed checkpoint payload (``.distcp`` / ``run_config.yaml``), not the\\n    parent run directory.\\n    \\\"\\\"\\\"\\n    if not os.path.isdir(output_dir):\\n        return None\\n\\n    # Already pointing at an iteration directory.\\n    if os.path.isfile(os.path.join(output_dir, \\\"run_config.yaml\\\")) or os.path.exists(\\n        os.path.join(output_dir, \\\".metadata\\\")\\n    ):\\n        return output_dir\\n\\n    iter_dirs = [\\n        name\\n        for name in os.listdir(output_dir)\\n        if name.startswith(\\\"iter_\\\") and os.path.isdir(os.path.join(output_dir, name))\\n    ]\\n    if not iter_dirs:\\n        return None\\n\\n    def _iter_number(name: str) -> int:\\n        try:\\n            return int(name.replace(\\\"iter_\\\", \\\"\\\"))\\n        except ValueError:\\n            return -1\\n\\n    latest = max(iter_dirs, key=_iter_number)\\n    return os.path.join(output_dir, latest)\\n\\n\\ndef _checkpoint_uses_peft(checkpoint_dir: str) -> bool:\\n    r\\\"\\\"\\\"Whether the Megatron checkpoint was saved with a PEFT (e.g. LoRA) config.\\\"\\\"\\\"\\n    cfg_path = os.path.join(checkpoint_dir, \\\"run_config.yaml\\\")\\n    if not os.path.isfile(cfg_path):\\n        return False\\n\\n    try:\\n        import yaml\\n\\n        with open(cfg_path, encoding=\\\"utf-8\\\") as f:\\n            cfg = yaml.safe_load(f) or {}\\n        return isinstance(cfg, dict) and bool(cfg.get(\\\"peft\\\"))\\n    except Exception:\\n        return False\\n\\n\\ndef _with_fusion_safe_provider(bridge):\\n    r\\\"\\\"\\\"Wrap ``to_megatron_provider`` so export paths disable missing APEX fusion.\\n\\n    Training already applies ``_apply_fusion_safety``, but AutoBridge export helpers\\n    (e.g. ``export_adapter_ckpt``) rebuild a provider with the default\\n    ``gradient_accumulation_fusion=True`` whenever TransformerEngine is importable,\\n    even if ``fused_weight_gradient_mlp_cuda`` is absent.\\n    \\\"\\\"\\\"\\n    original = bridge.to_megatron_provider\\n\\n    def _to_megatron_provider(*args, **kwargs):\\n        provider = original(*args, **kwargs)\\n        _apply_fusion_safety(provider)\\n        return provider\\n\\n    bridge.to_megatron_provider = _to_megatron_provider  # type: ignore[method-assign]\\n    return bridge\\n\\n\\ndef _maybe_export_hf_checkpoint(\\n    model_args: \\\"ModelArguments\\\",\\n    mb_args: \\\"MegatronBridgeArguments\\\",\\n    output_dir: str,\\n) -> None:\\n    if not mb_args.export_hf_on_finish or not training_args_should_save(output_dir):\\n        return\\n\\n    import torch.distributed as dist\\n    from megatron.bridge import AutoBridge\\n\\n    checkpoint_dir = _latest_iter_checkpoint_dir(output_dir)\\n    if checkpoint_dir is None:\\n        logger.warning_rank0(f\\\"No Megatron iteration checkpoint found under {output_dir}; skip HF export.\\\")\\n        return\\n\\n    export_dir = os.path.join(output_dir, \\\"hf_export\\\")\\n    bridge = _with_fusion_safe_provider(\\n        AutoBridge.from_hf_pretrained(\\n            model_args.model_name_or_path,\\n            trust_remote_code=model_args.trust_remote_code,\\n        )\\n    )\\n\\n    # LoRA / PEFT checkpoints only store adapter weights. Loading them as a full\\n    # model raises KeyError for base tensors such as linear_proj.weight.\\n    if _checkpoint_uses_peft(checkpoint_dir):\\n        logger.info_rank0(f\\\"Exporting LoRA adapter to Hugging Face PEFT format at {export_dir}...\\\")\\n        bridge.export_adapter_ckpt(peft_checkpoint=checkpoint_dir, output_path=export_dir)\\n        return\\n\\n    logger.info_rank0(f\\\"Exporting Megatron checkpoint to Hugging Face format at {export_dir}...\\\")\\n    if dist.is_initialized():\\n        # export_ckpt() always creates a fresh single-process gloo group, which fails\\n        # when torchrun has already initialized NCCL for training.\\n        megatron_model = bridge.load_megatron_model(output_dir)\\n        bridge.save_hf_pretrained(megatron_model, export_dir)\\n    else:\\n        bridge.export_ckpt(megatron_path=output_dir, hf_path=export_dir)\\n\\n\\ndef training_args_should_save(output_dir: str) -> bool:\\n    return os.path.isdir(output_dir) and bool(os.listdir(output_dir))\\n\\n\\ndef run_pt(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"TrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    mb_args: \\\"MegatronBridgeArguments\\\",\\n    callbacks: Optional[list[\\\"TrainerCallback\\\"]] = None,\\n):\\n    if callbacks:\\n        logger.warning_rank0(\\\"Megatron Bridge does not support Trainer callbacks yet; ignoring provided callbacks.\\\")\\n    _check_backend_available()\\n    _check_model_support(model_args)\\n    from megatron.bridge.training.gpt_step import forward_step\\n    from megatron.bridge.training.pretrain import pretrain\\n\\n    train_dataset, eval_dict = _load_aligned_datasets(model_args, data_args, training_args, \\\"pt\\\")\\n    dataset_dir = os.path.join(training_args.output_dir, \\\"mb_dataset\\\")\\n\\n    def _export_pt_dataset() -> None:\\n        export_dataset_for_megatron_bridge(\\n            train_dataset=train_dataset,\\n            output_dir=dataset_dir,\\n            eval_dataset=eval_dict.get(\\\"validation\\\") if eval_dict else None,\\n            val_size=data_args.val_size,\\n            seed=training_args.seed,\\n            stage=\\\"pt\\\",\\n        )\\n\\n    _run_on_main_process(training_args, _export_pt_dataset, dataset_dir)\\n\\n    cfg = build_pretrain_config(\\n        model_args=model_args,\\n        data_args=data_args,\\n        training_args=training_args,\\n        finetuning_args=finetuning_args,\\n        mb_args=mb_args,\\n        dataset_path=os.path.join(dataset_dir, \\\"training.jsonl\\\"),\\n        num_train_samples=len(train_dataset),\\n    )\\n    pretrain(cfg, forward_step)\\n    _maybe_export_hf_checkpoint(model_args, mb_args, training_args.output_dir)\\n\\n\\ndef run_sft(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"TrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    mb_args: \\\"MegatronBridgeArguments\\\",\\n    callbacks: Optional[list[\\\"TrainerCallback\\\"]] = None,\\n):\\n    if callbacks:\\n        logger.warning_rank0(\\\"Megatron Bridge does not support Trainer callbacks yet; ignoring provided callbacks.\\\")\\n    _check_backend_available()\\n    _check_model_support(model_args)\\n    from megatron.bridge.training.finetune import finetune\\n    from megatron.bridge.training.gpt_step import forward_step\\n\\n    train_dataset, eval_dict = _load_aligned_datasets(model_args, data_args, training_args, \\\"sft\\\")\\n    dataset_dir = os.path.join(training_args.output_dir, \\\"mb_dataset\\\")\\n\\n    def _export_sft_dataset() -> None:\\n        export_dataset_for_megatron_bridge(\\n            train_dataset=train_dataset,\\n            output_dir=dataset_dir,\\n            eval_dataset=eval_dict or None,\\n            val_size=data_args.val_size if not eval_dict else 0.0,\\n            seed=training_args.seed,\\n            stage=\\\"sft\\\",\\n            model_name_or_path=model_args.model_name_or_path,\\n            trust_remote_code=model_args.trust_remote_code,\\n            template_name=data_args.template,\\n        )\\n\\n    _run_on_main_process(training_args, _export_sft_dataset, dataset_dir)\\n\\n    pretrained_checkpoint = ensure_megatron_pretrained_checkpoint(\\n        model_args=model_args,\\n        mb_args=mb_args,\\n        output_dir=training_args.output_dir,\\n    )\\n    cfg = build_sft_config(\\n        model_args=model_args,\\n        data_args=data_args,\\n        training_args=training_args,\\n        finetuning_args=finetuning_args,\\n        mb_args=mb_args,\\n        dataset_root=dataset_dir,\\n        pretrained_checkpoint=pretrained_checkpoint,\\n        num_train_samples=len(train_dataset),\\n    )\\n    finetune(cfg, forward_step_func=forward_step)\\n    _maybe_export_hf_checkpoint(model_args, mb_args, training_args.output_dir)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/ppo/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f418101b642522951b2b24a9076b07afb09f2a16d5877dd4a352ab3603c56f0f\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom .workflow import run_ppo\\n\\n\\n__all__ = [\\\"run_ppo\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/ppo/ppo_utils.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"776bdd79746ccfc86998dfa489b4339892d39d0101b896a1da93279f2dc86c59\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport json\\nfrom contextlib import nullcontext\\nfrom typing import TYPE_CHECKING, Literal, Optional\\n\\nimport torch\\nfrom transformers.integrations import is_deepspeed_zero3_enabled\\n\\nfrom ...extras.packages import is_requests_available\\n\\n\\nif is_requests_available():\\n    import requests\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import PreTrainedModel\\n    from trl import AutoModelForCausalLMWithValueHead\\n\\n\\ndef get_rewards_from_server(server_url: str, messages: list[str]) -> list[\\\"torch.Tensor\\\"]:\\n    r\\\"\\\"\\\"Get reward scores from the API server.\\\"\\\"\\\"\\n    headers = {\\\"Content-Type\\\": \\\"application/json\\\"}\\n    payload = {\\\"model\\\": \\\"model\\\", \\\"messages\\\": messages}\\n    response = requests.post(server_url, json=payload, headers=headers)\\n    rewards = json.loads(response.text)[\\\"scores\\\"]\\n    return torch.Tensor(rewards)\\n\\n\\ndef replace_model(model: \\\"AutoModelForCausalLMWithValueHead\\\", target: Literal[\\\"default\\\", \\\"reward\\\"]) -> None:\\n    r\\\"\\\"\\\"Replace the default/reward modules in the model. The model is already unwrapped.\\\"\\\"\\\"\\n    v_head_layer = model.v_head.summary\\n    if is_deepspeed_zero3_enabled():\\n        import deepspeed  # type: ignore\\n\\n        params = [v_head_layer.weight, v_head_layer.bias]\\n        context_maybe_zero3 = deepspeed.zero.GatheredParameters(params, modifier_rank=0)\\n    else:\\n        context_maybe_zero3 = nullcontext()\\n\\n    model.pretrained_model.set_adapter(target)  # set the LoRA adapter to be active\\n    with context_maybe_zero3:\\n        if target == \\\"reward\\\":  # save default head temporarily\\n            setattr(model, \\\"default_head_weight\\\", v_head_layer.weight.data.detach().clone())\\n            setattr(model, \\\"default_head_bias\\\", v_head_layer.bias.data.detach().clone())\\n\\n        device = v_head_layer.weight.device\\n        v_head_layer.weight.data = model.get_buffer(f\\\"{target}_head_weight\\\").detach().clone().to(device)\\n        v_head_layer.bias.data = model.get_buffer(f\\\"{target}_head_bias\\\").detach().clone().to(device)\\n\\n\\ndef dump_layernorm(model: \\\"PreTrainedModel\\\") -> dict[str, \\\"torch.Tensor\\\"]:\\n    r\\\"\\\"\\\"Dump the layernorm parameters in the model. The model is already unwrapped (and gathered).\\\"\\\"\\\"\\n    layer_norm_params = {}\\n    for name, param in model.named_parameters():\\n        if param.data.dtype == torch.float32:\\n            layer_norm_params[name] = param.data.detach().clone()\\n            param.data = param.data.to(model.config.torch_dtype)\\n\\n    return layer_norm_params\\n\\n\\ndef restore_layernorm(model: \\\"PreTrainedModel\\\", layernorm_params: Optional[dict[str, \\\"torch.Tensor\\\"]] = None) -> None:\\n    r\\\"\\\"\\\"Restore the layernorm parameters in the model. The model is already unwrapped (and gathered).\\\"\\\"\\\"\\n    for name, param in model.named_parameters():\\n        if name in layernorm_params:\\n            param.data = layernorm_params[name]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/ppo/trainer.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"09fe60d4215cf890aeefab4caa2eee11e106824620457c937dd0286057bc71b6\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's TRL library.\\n# https://github.com/huggingface/trl/blob/v0.8.0/trl/trainer/ppo_trainer.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport math\\nimport os\\nimport sys\\nimport warnings\\nfrom types import MethodType\\nfrom typing import TYPE_CHECKING, Any, Optional\\n\\nimport torch\\nfrom accelerate.utils import DistributedDataParallelKwargs\\nfrom tqdm import tqdm\\nfrom transformers import GenerationConfig, Trainer, TrainerControl, TrainerState\\nfrom transformers.optimization import get_scheduler\\nfrom transformers.trainer import DEFAULT_CALLBACKS\\nfrom transformers.trainer_callback import CallbackHandler\\nfrom transformers.trainer_pt_utils import remove_dummy_checkpoint\\nfrom transformers.trainer_utils import PREFIX_CHECKPOINT_DIR\\nfrom transformers.utils import SAFE_WEIGHTS_NAME, WEIGHTS_NAME\\nfrom trl import PPOConfig, PPOTrainer\\nfrom trl import __version__ as trl_version\\nfrom trl.models.utils import unwrap_model_for_generation\\nfrom typing_extensions import override\\n\\nfrom ...extras import logging\\nfrom ...extras.misc import AverageMeter, count_parameters, get_current_device, get_logits_processor, torch_gc\\nfrom ..callbacks import FixValueHeadModelCallback, SaveProcessorCallback\\nfrom ..trainer_utils import create_custom_optimizer, create_custom_scheduler\\nfrom .ppo_utils import dump_layernorm, get_rewards_from_server, replace_model, restore_layernorm\\n\\n\\nif TYPE_CHECKING:\\n    from datasets import Dataset\\n    from transformers import (\\n        DataCollatorWithPadding,\\n        PreTrainedTokenizer,\\n        ProcessorMixin,\\n        Seq2SeqTrainingArguments,\\n        TrainerCallback,\\n    )\\n    from trl import AutoModelForCausalLMWithValueHead\\n\\n    from ...hparams import FinetuningArguments, GeneratingArguments, ModelArguments\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\nclass CustomPPOTrainer(PPOTrainer, Trainer):\\n    r\\\"\\\"\\\"Inherit PPOTrainer.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        model_args: \\\"ModelArguments\\\",\\n        training_args: \\\"Seq2SeqTrainingArguments\\\",\\n        finetuning_args: \\\"FinetuningArguments\\\",\\n        generating_args: \\\"GeneratingArguments\\\",\\n        callbacks: Optional[list[\\\"TrainerCallback\\\"]],\\n        model: \\\"AutoModelForCausalLMWithValueHead\\\",\\n        reward_model: Optional[\\\"AutoModelForCausalLMWithValueHead\\\"],\\n        ref_model: Optional[\\\"AutoModelForCausalLMWithValueHead\\\"],\\n        tokenizer: \\\"PreTrainedTokenizer\\\",\\n        processor: Optional[\\\"ProcessorMixin\\\"],\\n        data_collator: \\\"DataCollatorWithPadding\\\",\\n        train_dataset: Optional[\\\"Dataset\\\"] = None,\\n        eval_dataset: Optional[\\\"Dataset\\\"] = None,\\n    ) -> None:\\n        if eval_dataset is not None:\\n            raise NotImplementedError(\\\"PPOTrainer does not support eval dataset yet.\\\")\\n\\n        # Check if TRL version is compatible (0.8.6 <= version <= 0.9.6)\\n        try:\\n            from transformers.utils.versions import require_version\\n\\n            require_version(\\n                \\\"trl>=0.8.6,<=0.9.6\\\",\\n                \\\"Incompatible TRL version detected. LLaMA-Factory ppo requires TRL version >=0.8.6,<=0.9.6. \\\"\\n                f\\\"Found version {trl_version}. Please install the correct version with: `pip install trl>=0.8.6,<=0.9.6`\\\\n\\\"\\n                \\\"To fix: run `DISABLE_VERSION_CHECK=1 llamafactory-cli train example_ppo.yaml`\\\\n\\\",\\n            )\\n        except ImportError as e:\\n            raise e\\n\\n        backward_batch_size = training_args.per_device_train_batch_size * training_args.gradient_accumulation_steps\\n        ppo_config = PPOConfig(\\n            model_name=model_args.model_name_or_path,\\n            learning_rate=training_args.learning_rate,\\n            mini_batch_size=training_args.per_device_train_batch_size,\\n            batch_size=backward_batch_size * finetuning_args.ppo_buffer_size,\\n            gradient_accumulation_steps=training_args.gradient_accumulation_steps,\\n            ppo_epochs=finetuning_args.ppo_epochs,\\n            max_grad_norm=training_args.max_grad_norm,\\n            seed=training_args.seed,\\n            optimize_device_cache=True,\\n            target=finetuning_args.ppo_target,\\n            use_score_scaling=finetuning_args.ppo_score_norm,\\n            use_score_norm=finetuning_args.ppo_score_norm,\\n            whiten_rewards=finetuning_args.ppo_whiten_rewards,\\n            accelerator_kwargs={\\\"step_scheduler_with_optimizer\\\": False},\\n            log_with=training_args.report_to[0] if training_args.report_to else None,\\n            project_kwargs={\\\"logging_dir\\\": training_args.logging_dir},\\n        )\\n\\n        # Add deepspeed config\\n        if training_args.deepspeed_plugin is not None:\\n            ppo_config.accelerator_kwargs[\\\"kwargs_handlers\\\"] = [\\n                DistributedDataParallelKwargs(find_unused_parameters=training_args.ddp_find_unused_parameters)\\n            ]\\n            ppo_config.accelerator_kwargs[\\\"deepspeed_plugin\\\"] = training_args.deepspeed_plugin\\n            if ppo_config.log_with is not None:\\n                logger.warning_rank0(\\\"PPOTrainer cannot use external logger when DeepSpeed is enabled.\\\")\\n                ppo_config.log_with = None\\n\\n        # Create optimizer and scheduler\\n        if training_args.max_steps > 0:\\n            num_training_steps = training_args.max_steps\\n        else:\\n            total_train_batch_size = backward_batch_size * finetuning_args.ppo_buffer_size * training_args.world_size\\n            num_training_steps = training_args.num_train_epochs * math.ceil(\\n                len(train_dataset) / total_train_batch_size\\n            )\\n\\n        optimizer = self.create_optimizer(model, training_args, finetuning_args)\\n        scheduler = self.create_scheduler(training_args, num_training_steps, optimizer)\\n\\n        PPOTrainer.__init__(\\n            self,\\n            config=ppo_config,\\n            model=model,\\n            ref_model=ref_model,\\n            tokenizer=tokenizer,\\n            dataset=train_dataset,\\n            optimizer=optimizer,\\n            data_collator=data_collator,\\n            lr_scheduler=scheduler,\\n        )\\n\\n        self.args = training_args\\n        self.model_args = model_args\\n        self.finetuning_args = finetuning_args\\n        self.reward_model = reward_model\\n        self.current_device = get_current_device()  # patch for deepspeed training\\n\\n        self.generation_config = GenerationConfig(\\n            pad_token_id=self.tokenizer.pad_token_id,\\n            eos_token_id=[self.tokenizer.eos_token_id] + self.tokenizer.additional_special_tokens_ids,\\n            **generating_args.to_dict(),\\n        )\\n\\n        self.state = TrainerState()\\n        self.control = TrainerControl()\\n        self.is_deepspeed_enabled = getattr(self.accelerator.state, \\\"deepspeed_plugin\\\", None) is not None\\n        self.is_fsdp_enabled = getattr(self.accelerator.state, \\\"fsdp_plugin\\\", None) is not None\\n        callbacks = DEFAULT_CALLBACKS if callbacks is None else DEFAULT_CALLBACKS + callbacks\\n        self.callback_handler = CallbackHandler(\\n            callbacks, self.accelerator.unwrap_model(self.model), self.tokenizer, self.optimizer, self.lr_scheduler\\n        )\\n        if self.args.max_steps > 0:\\n            logger.info_rank0(\\\"max_steps is given, it will override any value given in num_train_epochs\\\")\\n\\n        self.amp_context = torch.autocast(self.current_device.type)\\n        warnings.simplefilter(\\\"ignore\\\")  # remove gc warnings on ref model\\n\\n        if finetuning_args.reward_model_type == \\\"full\\\":\\n            if self.is_deepspeed_enabled:\\n                if not (\\n                    getattr(reward_model.pretrained_model, \\\"is_loaded_in_8bit\\\", False)\\n                    or getattr(reward_model.pretrained_model, \\\"is_loaded_in_4bit\\\", False)\\n                ):  # quantized models are already set on the correct device\\n                    self.reward_model = self._prepare_deepspeed(self.reward_model)\\n            else:\\n                self.reward_model = self.accelerator.prepare_model(self.reward_model, evaluation_mode=True)\\n\\n        self.add_callback(FixValueHeadModelCallback)\\n\\n        if processor is not None:\\n            self.add_callback(SaveProcessorCallback(processor))\\n\\n        if finetuning_args.use_badam:\\n            from badam import BAdamCallback, clip_grad_norm_old_version  # type: ignore\\n\\n            self.accelerator.clip_grad_norm_ = MethodType(clip_grad_norm_old_version, self.accelerator)\\n            self.add_callback(BAdamCallback)\\n\\n    def ppo_train(self, resume_from_checkpoint: Optional[str] = None) -> None:\\n        r\\\"\\\"\\\"Implement training loop for the PPO stage, like _inner_training_loop() in Huggingface's Trainer.\\\"\\\"\\\"\\n        if resume_from_checkpoint is not None:\\n            raise ValueError(\\\"`resume_from_checkpoint` will be supported in the future version.\\\")\\n\\n        total_train_batch_size = (\\n            self.args.per_device_train_batch_size\\n            * self.args.gradient_accumulation_steps\\n            * self.finetuning_args.ppo_buffer_size\\n            * self.args.world_size\\n        )\\n        if self.args.max_steps > 0:\\n            num_examples = total_train_batch_size * self.args.max_steps\\n            num_train_epochs = sys.maxsize\\n            max_steps = self.args.max_steps\\n            steps_in_epoch = self.args.max_steps\\n        else:\\n            len_dataloader = len(self.dataloader)\\n            num_examples = len(self.dataset)\\n            num_train_epochs = self.args.num_train_epochs\\n            max_steps = math.ceil(num_train_epochs * len_dataloader)\\n            steps_in_epoch = len_dataloader\\n\\n        self.state.max_steps = max_steps\\n        self.state.num_train_epochs = num_train_epochs\\n        self.state.is_local_process_zero = self.is_local_process_zero()\\n        self.state.is_world_process_zero = self.is_world_process_zero()\\n\\n        logger.info_rank0(\\\"***** Running training *****\\\")\\n        logger.info_rank0(f\\\"  Num examples = {num_examples:,}\\\")\\n        logger.info_rank0(f\\\"  Num Epochs = {num_train_epochs:,}\\\")\\n        logger.info_rank0(f\\\"  Instantaneous batch size per device = {self.args.per_device_train_batch_size:,}\\\")\\n        logger.info_rank0(\\n            f\\\"  Total train batch size (w. parallel, buffer, distributed & accumulation) = {total_train_batch_size:,}\\\"\\n        )\\n        logger.info_rank0(f\\\"  Gradient Accumulation steps = {self.args.gradient_accumulation_steps:,}\\\")\\n        logger.info_rank0(f\\\"  Num optimization epochs per batch = {self.finetuning_args.ppo_epochs:,}\\\")\\n        logger.info_rank0(f\\\"  Total training steps = {max_steps:,}\\\")\\n        logger.info_rank0(f\\\"  Number of trainable parameters = {count_parameters(self.model)[0]:,}\\\")\\n\\n        dataiter = iter(self.dataloader)\\n        loss_meter = AverageMeter()\\n        reward_meter = AverageMeter()\\n        self.callback_handler.on_train_begin(self.args, self.state, self.control)\\n\\n        for step in tqdm(range(max_steps), disable=not self.is_local_process_zero()):\\n            try:\\n                batch = next(dataiter)\\n            except StopIteration:\\n                dataiter = iter(self.dataloader)\\n                batch = next(dataiter)\\n\\n            # Get inputs\\n            self.model.eval()\\n            self.tokenizer.padding_side = \\\"right\\\"  # change padding side\\n            queries, responses, rewards = [], [], []\\n            for idx in range(0, self.config.batch_size, self.config.mini_batch_size):\\n                mini_batch = {\\n                    \\\"input_ids\\\": batch[\\\"input_ids\\\"][idx : idx + self.config.mini_batch_size],\\n                    \\\"attention_mask\\\": batch[\\\"attention_mask\\\"][idx : idx + self.config.mini_batch_size],\\n                }\\n                mini_batch_queries, mini_batch_responses = self.get_inputs(mini_batch)\\n                mini_batch_rewards = self.get_rewards(mini_batch_queries, mini_batch_responses)\\n                queries.extend(mini_batch_queries)\\n                responses.extend(mini_batch_responses)\\n                rewards.extend(mini_batch_rewards)\\n\\n            # Run PPO step\\n            self.model.train()\\n            stats = self.step(queries, responses, rewards)\\n            self.tokenizer.padding_side = \\\"left\\\"  # restore padding side\\n            loss_meter.update(float(stats[\\\"ppo/loss/total\\\"]), n=len(rewards))\\n            reward_meter.update(torch.stack(rewards).mean().item(), n=len(rewards))\\n\\n            if self.config.log_with is not None:\\n                try:\\n                    batch[\\\"query\\\"] = self.tokenizer.batch_decode(queries, skip_special_tokens=True)\\n                    batch[\\\"response\\\"] = self.tokenizer.batch_decode(responses, skip_special_tokens=True)\\n                    self.log_stats(stats, batch, rewards)\\n                except Exception:\\n                    logger.warning_rank0(\\\"Failed to save stats due to unknown errors.\\\")\\n\\n            self.state.global_step += 1\\n            self.callback_handler.on_step_end(self.args, self.state, self.control)\\n\\n            if self.is_local_process_zero() and (step + 1) % self.args.logging_steps == 0:\\n                logs = dict(\\n                    loss=round(loss_meter.avg, 4),\\n                    reward=round(reward_meter.avg, 4),\\n                    learning_rate=stats[\\\"ppo/learning_rate\\\"],\\n                    epoch=round(step / steps_in_epoch, 2),\\n                )\\n                tqdm.write(str(logs))\\n                logs[\\\"step\\\"] = step\\n                self.state.log_history.append(logs)\\n                self.callback_handler.on_log(self.args, self.state, self.control, logs)\\n                loss_meter.reset()\\n                reward_meter.reset()\\n\\n            if (step + 1) % self.args.save_steps == 0:  # save checkpoint\\n                self.save_model(\\n                    os.path.join(self.args.output_dir, f\\\"{PREFIX_CHECKPOINT_DIR}-{self.state.global_step}\\\")\\n                )\\n                self.callback_handler.on_save(self.args, self.state, self.control)\\n\\n            if self.control.should_epoch_stop or self.control.should_training_stop:\\n                break\\n\\n        self.callback_handler.on_train_end(self.args, self.state, self.control)\\n\\n    @override\\n    def create_optimizer(\\n        self,\\n        model: \\\"AutoModelForCausalLMWithValueHead\\\",\\n        training_args: \\\"Seq2SeqTrainingArguments\\\",\\n        finetuning_args: \\\"FinetuningArguments\\\",\\n    ) -> \\\"torch.optim.Optimizer\\\":\\n        optimizer = create_custom_optimizer(model, training_args, finetuning_args)\\n        if optimizer is None:\\n            decay_params, nodecay_params = [], []\\n            decay_param_names = self.get_decay_parameter_names(model)\\n            for name, param in model.named_parameters():\\n                if param.requires_grad:\\n                    if name in decay_param_names:\\n                        decay_params.append(param)\\n                    else:\\n                        nodecay_params.append(param)\\n\\n            optim_class, optim_kwargs = Trainer.get_optimizer_cls_and_kwargs(training_args)\\n            param_groups = [\\n                dict(params=nodecay_params),\\n                dict(params=decay_params, weight_decay=training_args.weight_decay),\\n            ]\\n            optimizer = optim_class(param_groups, **optim_kwargs)\\n\\n        return optimizer\\n\\n    @override\\n    def create_scheduler(\\n        self, training_args: \\\"Seq2SeqTrainingArguments\\\", num_training_steps: int, optimizer: \\\"torch.optim.Optimizer\\\"\\n    ) -> \\\"torch.optim.lr_scheduler.LRScheduler\\\":\\n        create_custom_scheduler(training_args, num_training_steps, optimizer)\\n        lr_scheduler = get_scheduler(\\n            training_args.lr_scheduler_type,\\n            optimizer=optimizer,\\n            num_warmup_steps=training_args.get_warmup_steps(num_training_steps),\\n            num_training_steps=num_training_steps,\\n        )\\n        return lr_scheduler\\n\\n    @torch.no_grad()\\n    def get_inputs(self, batch: dict[str, \\\"torch.Tensor\\\"]) -> tuple[list[\\\"torch.Tensor\\\"], list[\\\"torch.Tensor\\\"]]:\\n        r\\\"\\\"\\\"Generate model's responses given queries.\\\"\\\"\\\"\\n        if batch[\\\"input_ids\\\"].size(0) == 1:  # handle llama2 ppo with gradient accumulation > 1\\n            start_index = (batch[\\\"input_ids\\\"][0] != self.tokenizer.pad_token_id).nonzero()[0].item()\\n            for k, v in batch.items():\\n                batch[k] = v[:, start_index:]\\n\\n        with unwrap_model_for_generation(self.model, self.accelerator) as unwrapped_model:\\n            unwrapped_model: AutoModelForCausalLMWithValueHead = self.accelerator.unwrap_model(self.model)\\n            if self.model_args.upcast_layernorm:\\n                layernorm_params = dump_layernorm(unwrapped_model)\\n\\n            generate_output: torch.Tensor = unwrapped_model.generate(\\n                generation_config=self.generation_config, logits_processor=get_logits_processor(), **batch\\n            )\\n            if self.model_args.upcast_layernorm:\\n                restore_layernorm(unwrapped_model, layernorm_params)\\n\\n        query = batch[\\\"input_ids\\\"].detach().cpu()\\n        response = generate_output[:, batch[\\\"input_ids\\\"].size(-1) :].detach().cpu()\\n        queries, responses = [], []\\n        for i in range(len(query)):\\n            query_start_index = (query[i] != self.tokenizer.pad_token_id).nonzero()[0].item()\\n            response_indexes = (response[i] != self.tokenizer.pad_token_id).nonzero()\\n\\n            if len(response_indexes) == 0:  # allow empty response\\n                response_length = 1\\n            elif self.tokenizer.eos_token_id == self.tokenizer.pad_token_id:  # include eos token\\n                response_length = response_indexes[-1].item() + 2\\n            else:\\n                response_length = response_indexes[-1].item() + 1\\n\\n            queries.append(query[i, query_start_index:])  # remove padding from left\\n            responses.append(response[i, :response_length])  # remove padding from right\\n\\n        return queries, responses\\n\\n    @torch.no_grad()\\n    def get_rewards(\\n        self,\\n        queries: list[\\\"torch.Tensor\\\"],\\n        responses: list[\\\"torch.Tensor\\\"],\\n    ) -> list[\\\"torch.Tensor\\\"]:\\n        r\\\"\\\"\\\"Compute scores using given reward model.\\n\\n        Both inputs and outputs are put on CPU.\\n        \\\"\\\"\\\"\\n        if self.finetuning_args.reward_model_type == \\\"api\\\":\\n            token_ids = [torch.cat((q, r), dim=-1).tolist() for q, r in zip(queries, responses)]\\n            messages = self.tokenizer.batch_decode(token_ids, skip_special_tokens=False)\\n            return get_rewards_from_server(self.reward_model, messages)\\n\\n        batch: dict[str, torch.Tensor] = self.prepare_model_inputs(queries, responses)\\n        unwrapped_model: AutoModelForCausalLMWithValueHead = self.accelerator.unwrap_model(self.model)\\n\\n        if self.finetuning_args.reward_model_type in [\\\"lora\\\", \\\"oft\\\"]:\\n            replace_model(unwrapped_model, target=\\\"reward\\\")\\n            reward_model = self.model\\n        else:\\n            reward_model = self.reward_model\\n\\n        with unwrap_model_for_generation(reward_model, self.accelerator), self.amp_context:  # support bf16\\n            values: torch.Tensor = reward_model(**batch, return_dict=True, use_cache=False)[-1]\\n\\n        if self.finetuning_args.reward_model_type in [\\\"lora\\\", \\\"oft\\\"]:\\n            replace_model(unwrapped_model, target=\\\"default\\\")\\n\\n        rewards = values.gather(dim=-1, index=(batch[\\\"attention_mask\\\"].sum(dim=-1, keepdim=True) - 1))\\n        return rewards.float().detach()  # use fp32 type\\n\\n    @override\\n    def batched_forward_pass(\\n        self,\\n        model: \\\"AutoModelForCausalLMWithValueHead\\\",\\n        queries: \\\"torch.Tensor\\\",\\n        responses: \\\"torch.Tensor\\\",\\n        model_inputs: dict[str, Any],\\n        return_logits: bool = False,\\n        response_masks: Optional[\\\"torch.Tensor\\\"] = None,\\n    ) -> tuple[\\\"torch.Tensor\\\", Optional[\\\"torch.Tensor\\\"], \\\"torch.Tensor\\\", \\\"torch.Tensor\\\"]:\\n        r\\\"\\\"\\\"Calculate model outputs in multiple batches.\\n\\n        Subclass and override to inject custom behavior.\\n        \\\"\\\"\\\"\\n        from trl.core import logprobs_from_logits\\n\\n        torch_gc()\\n        bs = len(queries)\\n        fbs = self.config.mini_batch_size\\n        all_logprobs = []\\n        all_logits = []\\n        all_masks = []\\n        all_values = []\\n\\n        for i in range(math.ceil(bs / fbs)):\\n            input_kwargs = {key: value[i * fbs : (i + 1) * fbs] for key, value in model_inputs.items()}\\n            query_batch = queries[i * fbs : (i + 1) * fbs]\\n            response_batch = responses[i * fbs : (i + 1) * fbs]\\n            if response_masks is not None:\\n                response_masks_batch = response_masks[i * fbs : (i + 1) * fbs]\\n            input_ids = input_kwargs[\\\"input_ids\\\"]\\n            attention_mask = input_kwargs[\\\"attention_mask\\\"]\\n\\n            with self.amp_context:  # support bf16\\n                logits, _, values = model(**input_kwargs, return_dict=True, use_cache=False)\\n\\n            logprobs = logprobs_from_logits(logits[:, :-1, :], input_ids[:, 1:])\\n            masks = torch.zeros_like(attention_mask)\\n            masks[:, :-1] = attention_mask[:, 1:]\\n\\n            for j in range(len(query_batch)):\\n                start = len(query_batch[j]) - 1\\n                if attention_mask[j, 0] == 0:  # offset left padding\\n                    start += attention_mask[j, :].nonzero()[0].item()\\n                end = start + len(response_batch[j])\\n\\n                if response_masks is not None:\\n                    response_masks_batch = torch.cat((torch.zeros_like(query_batch[j]), response_masks_batch[j]))[1:]\\n\\n                masks[j, :start] = 0\\n                masks[j, end:] = 0\\n                if response_masks is not None:\\n                    masks[j, start:end] = masks[j, start:end] * response_masks_batch[j][start:end]\\n\\n            if return_logits:\\n                all_logits.append(logits)\\n            else:\\n                del logits\\n\\n            all_values.append(values)\\n            all_logprobs.append(logprobs)\\n            all_masks.append(masks)\\n\\n        return (\\n            torch.cat(all_logprobs),\\n            torch.cat(all_logits)[:, :-1] if return_logits else None,\\n            torch.cat(all_values)[:, :-1],\\n            torch.cat(all_masks)[:, :-1],\\n        )\\n\\n    @override\\n    def save_model(self, output_dir: Optional[str] = None) -> None:\\n        r\\\"\\\"\\\"Save model checkpoint.\\n\\n        Subclass and override to inject custom behavior.\\n        \\\"\\\"\\\"\\n        if output_dir is None:\\n            output_dir = self.args.output_dir\\n\\n        if self.is_fsdp_enabled or self.is_deepspeed_enabled:\\n            try:\\n                state_dict = self.accelerator.get_state_dict(self.model)  # must be called at all ranks\\n                if self.args.should_save:\\n                    self._save(output_dir, state_dict=state_dict)\\n            except ValueError:\\n                logger.warning_rank0(\\n                    \\\" stage3_gather_16bit_weights_on_model_save=false. Saving the full checkpoint instead,\\\"\\n                    \\\" use zero_to_fp32.py to recover weights\\\"\\n                )\\n                if self.args.should_save:\\n                    self._save(output_dir, state_dict={})\\n                # remove the dummy state_dict\\n                remove_dummy_checkpoint(self.args.should_save, output_dir, [WEIGHTS_NAME, SAFE_WEIGHTS_NAME])\\n                self.model.save_checkpoint(output_dir)\\n\\n        elif self.args.should_save:\\n            unwrapped_model: AutoModelForCausalLMWithValueHead = self.accelerator.unwrap_model(self.model)\\n            self._save(output_dir, state_dict=unwrapped_model.state_dict())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/ppo/workflow.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"48f0037a8f8bf86ba85519c827db79428072a8b7f040964aa0f54ace7bde3ce2\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's TRL library.\\n# https://github.com/huggingface/trl/blob/v0.8.0/examples/scripts/ppo.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import TYPE_CHECKING, Optional\\n\\nfrom ...data import MultiModalDataCollatorForSeq2Seq, get_dataset, get_template_and_fix_tokenizer\\nfrom ...extras.ploting import plot_loss\\nfrom ...model import load_model, load_tokenizer\\nfrom ..callbacks import fix_valuehead_checkpoint\\nfrom ..trainer_utils import create_ref_model, create_reward_model\\nfrom .trainer import CustomPPOTrainer\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import Seq2SeqTrainingArguments, TrainerCallback\\n\\n    from ...hparams import DataArguments, FinetuningArguments, GeneratingArguments, ModelArguments\\n\\n\\ndef run_ppo(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"Seq2SeqTrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    generating_args: \\\"GeneratingArguments\\\",\\n    callbacks: Optional[list[\\\"TrainerCallback\\\"]] = None,\\n):\\n    tokenizer_module = load_tokenizer(model_args)\\n    tokenizer = tokenizer_module[\\\"tokenizer\\\"]\\n    template = get_template_and_fix_tokenizer(tokenizer, data_args)\\n    dataset_module = get_dataset(template, model_args, data_args, training_args, stage=\\\"ppo\\\", **tokenizer_module)\\n    model = load_model(tokenizer, model_args, finetuning_args, training_args.do_train, add_valuehead=True)\\n\\n    tokenizer.padding_side = \\\"left\\\"  # use left-padding in generation while using right-padding in training\\n    data_collator = MultiModalDataCollatorForSeq2Seq(template=template, model=model, **tokenizer_module)\\n\\n    # Create reference model and reward model\\n    ref_model = create_ref_model(model_args, finetuning_args, add_valuehead=True)\\n    reward_model = create_reward_model(model, model_args, finetuning_args)\\n\\n    # Initialize our Trainer\\n    ppo_trainer: CustomPPOTrainer = CustomPPOTrainer(\\n        model_args=model_args,\\n        training_args=training_args,\\n        finetuning_args=finetuning_args,\\n        generating_args=generating_args,\\n        callbacks=callbacks,\\n        model=model,\\n        reward_model=reward_model,\\n        ref_model=ref_model,\\n        data_collator=data_collator,\\n        **dataset_module,\\n        **tokenizer_module,\\n    )\\n\\n    # Training\\n    if training_args.do_train:\\n        ppo_trainer.ppo_train(resume_from_checkpoint=training_args.resume_from_checkpoint)\\n        ppo_trainer.save_model()\\n        if training_args.should_save:\\n            fix_valuehead_checkpoint(model, training_args.output_dir, getattr(training_args, \\\"save_safetensors\\\", True))\\n\\n        ppo_trainer.save_state()  # must be called after save_model to have a folder\\n        if ppo_trainer.is_world_process_zero() and finetuning_args.plot_loss:\\n            plot_loss(training_args.output_dir, keys=[\\\"loss\\\", \\\"reward\\\"])\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/pt/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bcb16c0d3e8aece0a6e5392ce746640ea9a23e3cfc26f89b979ce7d8bf8a37f3\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom .workflow import run_pt\\n\\n\\n__all__ = [\\\"run_pt\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/pt/trainer.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"550e498e6adf20efb121097d5b484ae3ffc03c9b0995c00cbed7bb8f52100a18\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom types import MethodType\\nfrom typing import TYPE_CHECKING, Optional\\n\\nimport torch\\nfrom transformers import Trainer\\nfrom typing_extensions import override\\n\\nfrom ..callbacks import SaveProcessorCallback\\nfrom ..fp8_utils import configure_fp8_environment, patch_accelerator_for_fp8, verify_fp8_status\\nfrom ..trainer_utils import create_custom_optimizer, create_custom_scheduler\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import ProcessorMixin\\n\\n    from ...hparams import FinetuningArguments, ModelArguments, TrainingArguments\\n\\n\\nclass CustomTrainer(Trainer):\\n    r\\\"\\\"\\\"Inherit Trainer for custom optimizer.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        finetuning_args: \\\"FinetuningArguments\\\",\\n        processor: Optional[\\\"ProcessorMixin\\\"],\\n        model_args: Optional[\\\"ModelArguments\\\"] = None,\\n        **kwargs,\\n    ) -> None:\\n        kwargs[\\\"processing_class\\\"] = kwargs.pop(\\\"tokenizer\\\")\\n        # Configure FP8 environment if enabled\\n        training_args: TrainingArguments = kwargs.get(\\\"args\\\")\\n        if training_args.fp8:\\n            configure_fp8_environment(training_args)\\n            if getattr(training_args, \\\"fp8_backend\\\", \\\"auto\\\") == \\\"te\\\":\\n                patch_accelerator_for_fp8()\\n\\n        super().__init__(**kwargs)\\n        if processor is not None:\\n            # avoid wrong loss under gradient accumulation\\n            # https://github.com/huggingface/transformers/pull/36044#issuecomment-2746657112\\n            self.model_accepts_loss_kwargs = False\\n\\n        self.finetuning_args = finetuning_args\\n\\n        if processor is not None:\\n            self.add_callback(SaveProcessorCallback(processor))\\n\\n        if finetuning_args.use_badam:\\n            from badam import BAdamCallback, clip_grad_norm_old_version  # type: ignore\\n\\n            self.accelerator.clip_grad_norm_ = MethodType(clip_grad_norm_old_version, self.accelerator)\\n            self.add_callback(BAdamCallback)\\n\\n        if training_args.fp8 and hasattr(self, \\\"accelerator\\\"):  # verify FP8 status after trainer initialization\\n            verify_fp8_status(self.accelerator, training_args)\\n\\n    @override\\n    def create_optimizer(self, *args, **kwargs) -> \\\"torch.optim.Optimizer\\\":\\n        if self.optimizer is None:\\n            self.optimizer = create_custom_optimizer(self.model, self.args, self.finetuning_args)\\n        return super().create_optimizer(*args, **kwargs)\\n\\n    @override\\n    def create_scheduler(\\n        self, num_training_steps: int, optimizer: Optional[\\\"torch.optim.Optimizer\\\"] = None\\n    ) -> \\\"torch.optim.lr_scheduler.LRScheduler\\\":\\n        create_custom_scheduler(self.args, num_training_steps, optimizer)\\n        return super().create_scheduler(num_training_steps, optimizer)\\n\\n    @override\\n    def _get_train_sampler(self, *args, **kwargs) -> Optional[\\\"torch.utils.data.Sampler\\\"]:\\n        if self.finetuning_args.disable_shuffling:\\n            return torch.utils.data.SequentialSampler(self.train_dataset)\\n\\n        return super()._get_train_sampler(*args, **kwargs)\\n\\n    @override\\n    def compute_loss(self, model, inputs, *args, **kwargs):\\n        return super().compute_loss(model, inputs, *args, **kwargs)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/pt/workflow.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"760130406928e26b464ed891ce793bc1b007f2166e47d8e80d76a7d0e07cb158\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's transformers library.\\n# https://github.com/huggingface/transformers/blob/v4.40.0/examples/pytorch/language-modeling/run_clm.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport math\\nfrom typing import TYPE_CHECKING, Optional\\n\\nfrom transformers import DataCollatorForLanguageModeling\\n\\nfrom ...data import get_dataset, get_template_and_fix_tokenizer\\nfrom ...extras.ploting import plot_loss\\nfrom ...model import load_model, load_tokenizer\\nfrom ..trainer_utils import create_modelcard_and_push\\nfrom .trainer import CustomTrainer\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import Seq2SeqTrainingArguments, TrainerCallback\\n\\n    from ...hparams import DataArguments, FinetuningArguments, ModelArguments\\n\\n\\ndef run_pt(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"Seq2SeqTrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    callbacks: Optional[list[\\\"TrainerCallback\\\"]] = None,\\n):\\n    tokenizer_module = load_tokenizer(model_args)\\n    tokenizer = tokenizer_module[\\\"tokenizer\\\"]\\n    template = get_template_and_fix_tokenizer(tokenizer, data_args)\\n    dataset_module = get_dataset(template, model_args, data_args, training_args, stage=\\\"pt\\\", **tokenizer_module)\\n    model = load_model(tokenizer, model_args, finetuning_args, training_args.do_train)\\n    data_collator = DataCollatorForLanguageModeling(tokenizer=tokenizer, mlm=False)\\n\\n    # Initialize our Trainer\\n    trainer = CustomTrainer(\\n        model=model,\\n        args=training_args,\\n        finetuning_args=finetuning_args,\\n        data_collator=data_collator,\\n        callbacks=callbacks,\\n        **dataset_module,\\n        **tokenizer_module,\\n    )\\n\\n    # Training\\n    if training_args.do_train:\\n        train_result = trainer.train(resume_from_checkpoint=training_args.resume_from_checkpoint)\\n        trainer.save_model()\\n        trainer.log_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_state()\\n        if trainer.is_world_process_zero() and finetuning_args.plot_loss:\\n            keys = [\\\"loss\\\"]\\n            if isinstance(dataset_module.get(\\\"eval_dataset\\\"), dict):\\n                keys += [f\\\"eval_{key}_loss\\\" for key in dataset_module[\\\"eval_dataset\\\"].keys()]\\n            else:\\n                keys += [\\\"eval_loss\\\"]\\n\\n            plot_loss(training_args.output_dir, keys=keys)\\n\\n    # Evaluation\\n    if training_args.do_eval:\\n        metrics = trainer.evaluate(metric_key_prefix=\\\"eval\\\")\\n\\n        if isinstance(dataset_module.get(\\\"eval_dataset\\\"), dict):\\n            for key in dataset_module[\\\"eval_dataset\\\"].keys():\\n                try:\\n                    perplexity = math.exp(metrics[f\\\"eval_{key}_loss\\\"])\\n                except OverflowError:\\n                    perplexity = float(\\\"inf\\\")\\n\\n                metrics[f\\\"eval_{key}_perplexity\\\"] = perplexity\\n        else:\\n            try:\\n                perplexity = math.exp(metrics[\\\"eval_loss\\\"])\\n            except OverflowError:\\n                perplexity = float(\\\"inf\\\")\\n\\n            metrics[\\\"eval_perplexity\\\"] = perplexity\\n\\n        trainer.log_metrics(\\\"eval\\\", metrics)\\n        trainer.save_metrics(\\\"eval\\\", metrics)\\n\\n    # Create model card\\n    create_modelcard_and_push(trainer, model_args, data_args, training_args, finetuning_args)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/rm/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"926652616e721319140a27d3aad3012a4ff5f1a55a61d77e042f815ae42c8488\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom .workflow import run_rm\\n\\n\\n__all__ = [\\\"run_rm\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/rm/metric.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a58f18701ea9b084d620a2d574e14bf7ba916a10025e144060b1ab18e4e33836\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom dataclasses import dataclass\\nfrom typing import TYPE_CHECKING\\n\\nimport numpy as np\\n\\nfrom ...extras.misc import numpify\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import EvalPrediction\\n\\n\\n@dataclass\\nclass ComputeAccuracy:\\n    r\\\"\\\"\\\"Compute reward accuracy and support `batch_eval_metrics`.\\\"\\\"\\\"\\n\\n    def _dump(self) -> dict[str, float] | None:\\n        result = None\\n        if hasattr(self, \\\"score_dict\\\"):\\n            result = {k: float(np.mean(v)) for k, v in self.score_dict.items()}\\n\\n        self.score_dict = {\\\"accuracy\\\": []}\\n        return result\\n\\n    def __post_init__(self):\\n        self._dump()\\n\\n    def __call__(self, eval_preds: \\\"EvalPrediction\\\", compute_result: bool = True) -> dict[str, float] | None:\\n        chosen_scores, rejected_scores = numpify(eval_preds.predictions[0]), numpify(eval_preds.predictions[1])\\n        if not chosen_scores.shape:\\n            self.score_dict[\\\"accuracy\\\"].append(chosen_scores > rejected_scores)\\n        else:\\n            for i in range(len(chosen_scores)):\\n                self.score_dict[\\\"accuracy\\\"].append(chosen_scores[i] > rejected_scores[i])\\n\\n        if compute_result:\\n            return self._dump()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/rm/trainer.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0cb91bd0d025ed7f134c21bdb7b0d542c892424db3b950d41641b8a505fd290f\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's transformers library.\\n# https://github.com/huggingface/transformers/blob/v4.40.0/src/transformers/trainer.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport json\\nimport os\\nfrom types import MethodType\\nfrom typing import TYPE_CHECKING, Optional, Union\\n\\nimport torch\\nfrom transformers import Trainer\\nfrom typing_extensions import override\\n\\nfrom ...extras import logging\\nfrom ...extras.packages import is_transformers_version_greater_than\\nfrom ..callbacks import FixValueHeadModelCallback, SaveProcessorCallback\\nfrom ..trainer_utils import create_custom_optimizer, create_custom_scheduler\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import PreTrainedModel, ProcessorMixin\\n    from transformers.trainer import PredictionOutput\\n\\n    from ...hparams import FinetuningArguments\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\nclass PairwiseTrainer(Trainer):\\n    r\\\"\\\"\\\"Inherits Trainer to compute pairwise loss.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self, finetuning_args: \\\"FinetuningArguments\\\", processor: Optional[\\\"ProcessorMixin\\\"], **kwargs\\n    ) -> None:\\n        if is_transformers_version_greater_than(\\\"4.46\\\"):\\n            kwargs[\\\"processing_class\\\"] = kwargs.pop(\\\"tokenizer\\\")\\n\\n        super().__init__(**kwargs)\\n        self.model_accepts_loss_kwargs = False  # overwrite trainer's default behavior\\n        self.finetuning_args = finetuning_args\\n        self.can_return_loss = True  # override property to return eval_loss\\n        self.add_callback(FixValueHeadModelCallback)\\n\\n        if processor is not None:\\n            self.add_callback(SaveProcessorCallback(processor))\\n\\n        if finetuning_args.use_badam:\\n            from badam import BAdamCallback, clip_grad_norm_old_version  # type: ignore\\n\\n            self.accelerator.clip_grad_norm_ = MethodType(clip_grad_norm_old_version, self.accelerator)\\n            self.add_callback(BAdamCallback)\\n\\n    @override\\n    def create_optimizer(self, *args, **kwargs) -> \\\"torch.optim.Optimizer\\\":\\n        if self.optimizer is None:\\n            self.optimizer = create_custom_optimizer(self.model, self.args, self.finetuning_args)\\n        return super().create_optimizer(*args, **kwargs)\\n\\n    @override\\n    def create_scheduler(\\n        self, num_training_steps: int, optimizer: Optional[\\\"torch.optim.Optimizer\\\"] = None\\n    ) -> \\\"torch.optim.lr_scheduler.LRScheduler\\\":\\n        create_custom_scheduler(self.args, num_training_steps, optimizer)\\n        return super().create_scheduler(num_training_steps, optimizer)\\n\\n    @override\\n    def _get_train_sampler(self, *args, **kwargs) -> Optional[\\\"torch.utils.data.Sampler\\\"]:\\n        if self.finetuning_args.disable_shuffling:\\n            return torch.utils.data.SequentialSampler(self.train_dataset)\\n\\n        return super()._get_train_sampler(*args, **kwargs)\\n\\n    @override\\n    def compute_loss(\\n        self, model: \\\"PreTrainedModel\\\", inputs: dict[str, \\\"torch.Tensor\\\"], return_outputs: bool = False, **kwargs\\n    ) -> Union[\\\"torch.Tensor\\\", tuple[\\\"torch.Tensor\\\", list[\\\"torch.Tensor\\\"]]]:\\n        r\\\"\\\"\\\"Compute pairwise loss. The first n examples are chosen and the last n examples are rejected.\\n\\n        Subclass and override to inject custom behavior.\\n\\n        Note that the first element will be removed from the output tuple.\\n        See: https://github.com/huggingface/transformers/blob/v4.40.0/src/transformers/trainer.py#L3842\\n        \\\"\\\"\\\"\\n        _, _, values = model(**inputs, output_hidden_states=True, return_dict=True, use_cache=False)\\n        batch_size = inputs[\\\"input_ids\\\"].size(0) // 2\\n        chosen_masks, rejected_masks = torch.split(inputs[\\\"attention_mask\\\"], batch_size, dim=0)\\n        chosen_rewards, rejected_rewards = torch.split(values, batch_size, dim=0)\\n        chosen_scores = chosen_rewards.gather(dim=-1, index=(chosen_masks.sum(dim=-1, keepdim=True) - 1))\\n        rejected_scores = rejected_rewards.gather(dim=-1, index=(rejected_masks.sum(dim=-1, keepdim=True) - 1))\\n        chosen_scores, rejected_scores = chosen_scores.squeeze(), rejected_scores.squeeze()\\n\\n        loss = -torch.nn.functional.logsigmoid(chosen_scores.float() - rejected_scores.float()).mean()\\n        if return_outputs:\\n            return loss, (loss, chosen_scores, rejected_scores)\\n        else:\\n            return loss\\n\\n    @override\\n    def _save(self, output_dir: Optional[str] = None, state_dict=None):\\n        if state_dict is None:\\n            state_dict = self.model.state_dict()\\n\\n        if getattr(self.args, \\\"save_safetensors\\\", True):\\n            from collections import defaultdict\\n\\n            ptrs = defaultdict(list)\\n            for name, tensor in state_dict.items():\\n                if isinstance(tensor, torch.Tensor):\\n                    ptrs[id(tensor)].append(name)\\n\\n            for names in ptrs.values():\\n                if len(names) > 1:\\n                    names.sort()\\n                    for name in names[1:]:\\n                        state_dict.pop(name, None)\\n\\n        super()._save(output_dir, state_dict)\\n\\n    def save_predictions(self, predict_results: \\\"PredictionOutput\\\") -> None:\\n        r\\\"\\\"\\\"Save model predictions to `output_dir`.\\n\\n        A custom behavior that not contained in Seq2SeqTrainer.\\n        \\\"\\\"\\\"\\n        if not self.is_world_process_zero():\\n            return\\n\\n        output_prediction_file = os.path.join(self.args.output_dir, \\\"generated_predictions.jsonl\\\")\\n        logger.info_rank0(f\\\"Saving prediction results to {output_prediction_file}\\\")\\n        chosen_scores, rejected_scores = predict_results.predictions\\n\\n        with open(output_prediction_file, \\\"w\\\", encoding=\\\"utf-8\\\") as writer:\\n            res: list[str] = []\\n            for c_score, r_score in zip(chosen_scores, rejected_scores):\\n                res.append(json.dumps({\\\"chosen\\\": round(float(c_score), 2), \\\"rejected\\\": round(float(r_score), 2)}))\\n\\n            writer.write(\\\"\\\\n\\\".join(res))\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/rm/workflow.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b0d261c40f1a02360f7b65c6a02fa05f2736809ca4dcb89287deddd26ddc35b4\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's transformers library.\\n# https://github.com/huggingface/transformers/blob/v4.40.0/examples/pytorch/summarization/run_summarization.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import TYPE_CHECKING, Optional\\n\\nfrom ...data import PairwiseDataCollatorWithPadding, get_dataset, get_template_and_fix_tokenizer\\nfrom ...extras.ploting import plot_loss\\nfrom ...model import load_model, load_tokenizer\\nfrom ..callbacks import fix_valuehead_checkpoint\\nfrom ..trainer_utils import create_modelcard_and_push\\nfrom .metric import ComputeAccuracy\\nfrom .trainer import PairwiseTrainer\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import Seq2SeqTrainingArguments, TrainerCallback\\n\\n    from ...hparams import DataArguments, FinetuningArguments, ModelArguments\\n\\n\\ndef run_rm(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"Seq2SeqTrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    callbacks: Optional[list[\\\"TrainerCallback\\\"]] = None,\\n):\\n    tokenizer_module = load_tokenizer(model_args)\\n    tokenizer = tokenizer_module[\\\"tokenizer\\\"]\\n    template = get_template_and_fix_tokenizer(tokenizer, data_args)\\n    dataset_module = get_dataset(template, model_args, data_args, training_args, stage=\\\"rm\\\", **tokenizer_module)\\n    model = load_model(tokenizer, model_args, finetuning_args, training_args.do_train, add_valuehead=True)\\n    data_collator = PairwiseDataCollatorWithPadding(\\n        template=template, model=model, pad_to_multiple_of=8, **tokenizer_module\\n    )\\n\\n    # Initialize our Trainer\\n    trainer = PairwiseTrainer(\\n        model=model,\\n        args=training_args,\\n        finetuning_args=finetuning_args,\\n        data_collator=data_collator,\\n        callbacks=callbacks,\\n        compute_metrics=ComputeAccuracy(),\\n        **dataset_module,\\n        **tokenizer_module,\\n    )\\n\\n    # Training\\n    if training_args.do_train:\\n        train_result = trainer.train(resume_from_checkpoint=training_args.resume_from_checkpoint)\\n        trainer.save_model()\\n        if training_args.should_save:\\n            fix_valuehead_checkpoint(model, training_args.output_dir, getattr(training_args, \\\"save_safetensors\\\", True))\\n\\n        trainer.log_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_state()\\n        if trainer.is_world_process_zero() and finetuning_args.plot_loss:\\n            keys = [\\\"loss\\\"]\\n            if isinstance(dataset_module.get(\\\"eval_dataset\\\"), dict):\\n                keys += sum(\\n                    [[f\\\"eval_{key}_loss\\\", f\\\"eval_{key}_accuracy\\\"] for key in dataset_module[\\\"eval_dataset\\\"].keys()], []\\n                )\\n            else:\\n                keys += [\\\"eval_loss\\\", \\\"eval_accuracy\\\"]\\n\\n            plot_loss(training_args.output_dir, keys=keys)\\n\\n    # Evaluation\\n    if training_args.do_eval:\\n        metrics = trainer.evaluate(metric_key_prefix=\\\"eval\\\")\\n        trainer.log_metrics(\\\"eval\\\", metrics)\\n        trainer.save_metrics(\\\"eval\\\", metrics)\\n\\n    # Predict\\n    if training_args.do_predict:\\n        predict_results = trainer.predict(dataset_module[\\\"eval_dataset\\\"], metric_key_prefix=\\\"predict\\\")\\n        trainer.log_metrics(\\\"predict\\\", predict_results.metrics)\\n        trainer.save_metrics(\\\"predict\\\", predict_results.metrics)\\n        trainer.save_predictions(predict_results)\\n\\n    # Create model card\\n    create_modelcard_and_push(trainer, model_args, data_args, training_args, finetuning_args)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/sft/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"27f7d9876d56309efd2bff46b8c10bbc034f37f8b1d9ddd2f1cd6b4a25cd88e5\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom .workflow import run_sft\\n\\n\\n__all__ = [\\\"run_sft\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/sft/metric.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ed8807eaca1637edb2144b1e190a1cb84e5644400e21a16745477b49a132cab6\",\"content\":\"# Copyright 2025 HuggingFace Inc., THUDM, and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's transformers library and the THUDM's ChatGLM implementation.\\n# https://github.com/huggingface/transformers/blob/v4.40.0/examples/pytorch/summarization/run_summarization.py\\n# https://github.com/THUDM/ChatGLM-6B/blob/main/ptuning/main.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom dataclasses import dataclass\\nfrom typing import TYPE_CHECKING, Optional\\n\\nimport numpy as np\\nimport torch\\nfrom transformers.utils import is_nltk_available\\n\\nfrom ...extras.constants import IGNORE_INDEX\\nfrom ...extras.misc import numpify\\nfrom ...extras.packages import is_jieba_available, is_rouge_available\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import EvalPrediction, PreTrainedTokenizer\\n\\n\\nif is_jieba_available():\\n    import jieba  # type: ignore\\n\\n\\nif is_nltk_available():\\n    from nltk.translate.bleu_score import SmoothingFunction, sentence_bleu  # type: ignore\\n\\n\\nif is_rouge_available():\\n    from rouge_chinese import Rouge  # type: ignore\\n\\n\\ndef eval_logit_processor(logits: \\\"torch.Tensor\\\", labels: \\\"torch.Tensor\\\") -> \\\"torch.Tensor\\\":\\n    r\\\"\\\"\\\"Compute the token with the largest likelihood to reduce memory footprint.\\\"\\\"\\\"\\n    if isinstance(logits, (list, tuple)):\\n        if logits[0].dim() == 3:  # (batch_size, seq_len, vocab_size)\\n            logits = logits[0]\\n        else:  # moe models have aux loss\\n            logits = logits[1]\\n\\n    if logits.dim() != 3:\\n        raise ValueError(\\\"Cannot process the logits.\\\")\\n\\n    return torch.argmax(logits, dim=-1)\\n\\n\\n@dataclass\\nclass ComputeAccuracy:\\n    r\\\"\\\"\\\"Compute accuracy and support `batch_eval_metrics`.\\\"\\\"\\\"\\n\\n    def _dump(self) -> Optional[dict[str, float]]:\\n        result = None\\n        if hasattr(self, \\\"score_dict\\\"):\\n            result = {k: float(np.mean(v)) for k, v in self.score_dict.items()}\\n\\n        self.score_dict = {\\\"accuracy\\\": []}\\n        return result\\n\\n    def __post_init__(self):\\n        self._dump()\\n\\n    def __call__(self, eval_preds: \\\"EvalPrediction\\\", compute_result: bool = True) -> Optional[dict[str, float]]:\\n        preds, labels = numpify(eval_preds.predictions), numpify(eval_preds.label_ids)\\n        for i in range(len(preds)):\\n            pred, label = preds[i, :-1], labels[i, 1:]\\n            label_mask = label != IGNORE_INDEX\\n            self.score_dict[\\\"accuracy\\\"].append(np.mean(pred[label_mask] == label[label_mask]))\\n\\n        if compute_result:\\n            return self._dump()\\n\\n\\n@dataclass\\nclass ComputeSimilarity:\\n    r\\\"\\\"\\\"Compute text similarity scores and support `batch_eval_metrics`.\\n\\n    Wraps the tokenizer into metric functions, used in CustomSeq2SeqTrainer.\\n    \\\"\\\"\\\"\\n\\n    tokenizer: \\\"PreTrainedTokenizer\\\"\\n\\n    def _dump(self) -> Optional[dict[str, float]]:\\n        result = None\\n        if hasattr(self, \\\"score_dict\\\"):\\n            result = {k: float(np.mean(v)) for k, v in self.score_dict.items()}\\n\\n        self.score_dict = {\\\"rouge-1\\\": [], \\\"rouge-2\\\": [], \\\"rouge-l\\\": [], \\\"bleu-4\\\": []}\\n        return result\\n\\n    def __post_init__(self):\\n        self._dump()\\n\\n    def __call__(self, eval_preds: \\\"EvalPrediction\\\", compute_result: bool = True) -> Optional[dict[str, float]]:\\n        preds, labels = numpify(eval_preds.predictions), numpify(eval_preds.label_ids)\\n\\n        preds = np.where(preds != IGNORE_INDEX, preds, self.tokenizer.pad_token_id)\\n        labels = np.where(labels != IGNORE_INDEX, labels, self.tokenizer.pad_token_id)\\n\\n        decoded_preds = self.tokenizer.batch_decode(preds, skip_special_tokens=True)\\n        decoded_labels = self.tokenizer.batch_decode(labels, skip_special_tokens=True)\\n\\n        for pred, label in zip(decoded_preds, decoded_labels):\\n            hypothesis = list(jieba.cut(pred))\\n            reference = list(jieba.cut(label))\\n\\n            if len(\\\" \\\".join(hypothesis).split()) == 0 or len(\\\" \\\".join(reference).split()) == 0:\\n                result = {\\\"rouge-1\\\": {\\\"f\\\": 0.0}, \\\"rouge-2\\\": {\\\"f\\\": 0.0}, \\\"rouge-l\\\": {\\\"f\\\": 0.0}}\\n            else:\\n                rouge = Rouge()\\n                scores = rouge.get_scores(\\\" \\\".join(hypothesis), \\\" \\\".join(reference))\\n                result = scores[0]\\n\\n            for k, v in result.items():\\n                self.score_dict[k].append(round(v[\\\"f\\\"] * 100, 4))\\n\\n            bleu_score = sentence_bleu([list(label)], list(pred), smoothing_function=SmoothingFunction().method3)\\n            self.score_dict[\\\"bleu-4\\\"].append(round(bleu_score * 100, 4))\\n\\n        if compute_result:\\n            return self._dump()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/sft/trainer.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"4016aa09576891d53f2f3ee8f0cd21cd0f5c80c8ee1f45ab964a00750253d7c9\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's transformers library.\\n# https://github.com/huggingface/transformers/blob/v4.40.0/src/transformers/trainer_seq2seq.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport json\\nimport os\\nfrom functools import partial\\nfrom types import MethodType\\nfrom typing import TYPE_CHECKING, Any, Optional, Union\\n\\nimport numpy as np\\nimport torch\\nfrom transformers import Seq2SeqTrainer\\nfrom typing_extensions import override\\n\\nfrom ...extras import logging\\nfrom ...extras.constants import IGNORE_INDEX\\nfrom ..callbacks import SaveProcessorCallback\\nfrom ..fp8_utils import configure_fp8_environment, patch_accelerator_for_fp8, verify_fp8_status\\nfrom ..trainer_utils import create_custom_optimizer, create_custom_scheduler\\n\\n\\nif TYPE_CHECKING:\\n    from torch.utils.data import Dataset\\n    from transformers import ProcessorMixin\\n    from transformers.trainer import PredictionOutput\\n\\n    from ...hparams import FinetuningArguments, ModelArguments, TrainingArguments\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\nclass CustomSeq2SeqTrainer(Seq2SeqTrainer):\\n    r\\\"\\\"\\\"Inherits Seq2SeqTrainer to compute generative metrics such as BLEU and ROUGE.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        finetuning_args: \\\"FinetuningArguments\\\",\\n        processor: Optional[\\\"ProcessorMixin\\\"],\\n        model_args: Optional[\\\"ModelArguments\\\"] = None,\\n        gen_kwargs: Optional[dict[str, Any]] = None,\\n        ref_model: Optional[\\\"torch.nn.Module\\\"] = None,\\n        **kwargs,\\n    ) -> None:\\n        kwargs[\\\"processing_class\\\"] = kwargs.pop(\\\"tokenizer\\\")\\n        # Configure FP8 environment if enabled\\n        training_args: TrainingArguments = kwargs.get(\\\"args\\\")\\n        if training_args.fp8:\\n            configure_fp8_environment(training_args)\\n            if getattr(training_args, \\\"fp8_backend\\\", \\\"auto\\\") == \\\"te\\\":\\n                patch_accelerator_for_fp8()\\n\\n        super().__init__(**kwargs)\\n        if processor is not None:\\n            # avoid wrong loss under gradient accumulation\\n            # https://github.com/huggingface/transformers/pull/36044#issuecomment-2746657112\\n            self.model_accepts_loss_kwargs = False\\n\\n        self.finetuning_args = finetuning_args\\n        if gen_kwargs is not None:\\n            # https://github.com/huggingface/transformers/blob/v4.45.0/src/transformers/trainer_seq2seq.py#L287\\n            self._gen_kwargs = gen_kwargs\\n\\n        if processor is not None:\\n            self.add_callback(SaveProcessorCallback(processor))\\n\\n        if finetuning_args.use_badam:\\n            from badam import BAdamCallback, clip_grad_norm_old_version  # type: ignore\\n\\n            self.accelerator.clip_grad_norm_ = MethodType(clip_grad_norm_old_version, self.accelerator)\\n            self.add_callback(BAdamCallback)\\n\\n        self.ref_model = ref_model\\n\\n        if ref_model is not None:\\n            from trl.models.utils import prepare_deepspeed, prepare_fsdp\\n\\n            if getattr(self.accelerator.state, \\\"deepspeed_plugin\\\", None) is not None:\\n                if not (\\n                    getattr(ref_model, \\\"is_loaded_in_8bit\\\", False) or getattr(ref_model, \\\"is_loaded_in_4bit\\\", False)\\n                ):  # quantized models are already set on the correct device\\n                    self.ref_model = prepare_deepspeed(self.ref_model, self.accelerator)\\n            elif getattr(self.accelerator.state, \\\"fsdp_plugin\\\", None) is not None:\\n                if self.accelerator.is_fsdp2:\\n                    from accelerate.utils.fsdp_utils import fsdp2_prepare_model\\n\\n                    self.ref_model = fsdp2_prepare_model(self.accelerator, self.ref_model)\\n                else:\\n                    self.ref_model = prepare_fsdp(self.ref_model, self.accelerator)\\n            else:\\n                self.ref_model = self.accelerator.prepare_model(self.ref_model, evaluation_mode=True)\\n                self.ref_model.eval()\\n\\n        if finetuning_args.use_dft_loss:\\n            from ..trainer_utils import dft_loss_func\\n\\n            self.compute_loss_func = dft_loss_func\\n\\n        elif finetuning_args.use_eaft_loss:\\n            from ..trainer_utils import eaft_loss_func\\n\\n            self.compute_loss_func = lambda outputs, labels, num_items_in_batch=None: eaft_loss_func(\\n                outputs, labels, num_items_in_batch, finetuning_args.eaft_alpha\\n            )\\n        elif finetuning_args.use_asft_loss:\\n            from ..trainer_utils import asft_loss_func\\n\\n            self.compute_loss_func = partial(\\n                asft_loss_func,\\n                asft_alpha=finetuning_args.asft_alpha,\\n            )\\n\\n        if training_args.fp8 and hasattr(self, \\\"accelerator\\\"):  # verify FP8 status after trainer initialization\\n            verify_fp8_status(self.accelerator, training_args)\\n\\n    @override\\n    def create_optimizer(self, *args, **kwargs) -> \\\"torch.optim.Optimizer\\\":\\n        if self.optimizer is None:\\n            self.optimizer = create_custom_optimizer(self.model, self.args, self.finetuning_args)\\n        return super().create_optimizer(*args, **kwargs)\\n\\n    @override\\n    def create_scheduler(\\n        self, num_training_steps: int, optimizer: Optional[\\\"torch.optim.Optimizer\\\"] = None\\n    ) -> \\\"torch.optim.lr_scheduler.LRScheduler\\\":\\n        create_custom_scheduler(self.args, num_training_steps, optimizer)\\n        return super().create_scheduler(num_training_steps, optimizer)\\n\\n    @override\\n    def _get_train_sampler(self, *args, **kwargs) -> Optional[\\\"torch.utils.data.Sampler\\\"]:\\n        if self.finetuning_args.disable_shuffling:\\n            return torch.utils.data.SequentialSampler(self.train_dataset)\\n\\n        return super()._get_train_sampler(*args, **kwargs)\\n\\n    @override\\n    def compute_loss(self, model, inputs, *args, **kwargs):\\n        if self.finetuning_args.use_asft_loss:\\n            with torch.no_grad():\\n                ref_outputs = self.ref_model(\\n                    input_ids=inputs[\\\"input_ids\\\"],\\n                    attention_mask=inputs.get(\\\"attention_mask\\\", None),\\n                )\\n                ref_logits = ref_outputs.logits\\n            outputs = model(**inputs)\\n            return self.compute_loss_func(outputs, inputs[\\\"labels\\\"], ref_logits)\\n        else:\\n            return super().compute_loss(model, inputs, *args, **kwargs)\\n\\n    @override\\n    def prediction_step(\\n        self,\\n        model: \\\"torch.nn.Module\\\",\\n        inputs: dict[str, Union[\\\"torch.Tensor\\\", Any]],\\n        prediction_loss_only: bool,\\n        ignore_keys: Optional[list[str]] = None,\\n        **gen_kwargs,\\n    ) -> tuple[Optional[float], Optional[\\\"torch.Tensor\\\"], Optional[\\\"torch.Tensor\\\"]]:\\n        r\\\"\\\"\\\"Remove the prompt part in the generated tokens.\\n\\n        Subclass and override to inject custom behavior.\\n        \\\"\\\"\\\"\\n        if self.args.predict_with_generate:  # do not pass labels to model when generate\\n            labels = inputs.pop(\\\"labels\\\", None)\\n        else:\\n            labels = inputs.get(\\\"labels\\\")\\n\\n        loss, generated_tokens, _ = super().prediction_step(\\n            model, inputs, prediction_loss_only=prediction_loss_only, ignore_keys=ignore_keys, **gen_kwargs\\n        )\\n        if generated_tokens is not None and self.args.predict_with_generate:\\n            generated_tokens[:, : inputs[\\\"input_ids\\\"].size(-1)] = self.processing_class.pad_token_id\\n            generated_tokens = generated_tokens.contiguous()\\n\\n        return loss, generated_tokens, labels\\n\\n    def save_predictions(\\n        self, dataset: \\\"Dataset\\\", predict_results: \\\"PredictionOutput\\\", skip_special_tokens: bool = True\\n    ) -> None:\\n        r\\\"\\\"\\\"Save model predictions to `output_dir`.\\n\\n        A custom behavior that not contained in Seq2SeqTrainer.\\n        \\\"\\\"\\\"\\n        if not self.is_world_process_zero():\\n            return\\n\\n        output_prediction_file = os.path.join(self.args.output_dir, \\\"generated_predictions.jsonl\\\")\\n        logger.info_rank0(f\\\"Saving prediction results to {output_prediction_file}\\\")\\n\\n        labels = np.where(\\n            predict_results.label_ids != IGNORE_INDEX, predict_results.label_ids, self.processing_class.pad_token_id\\n        )\\n        preds = np.where(\\n            predict_results.predictions != IGNORE_INDEX,\\n            predict_results.predictions,\\n            self.processing_class.pad_token_id,\\n        )\\n\\n        for i in range(len(preds)):\\n            pad_len = np.nonzero(preds[i] != self.processing_class.pad_token_id)[0]\\n            if len(pad_len):  # move pad token to last\\n                preds[i] = np.concatenate((preds[i][pad_len[0] :], preds[i][: pad_len[0]]), axis=-1)\\n\\n        input_ids_column = dataset[\\\"input_ids\\\"]\\n        try:\\n            input_ids_list = input_ids_column.to_pylist()\\n        except AttributeError:\\n            input_ids_list = list(input_ids_column)\\n\\n        decoded_inputs = self.processing_class.batch_decode(input_ids_list, skip_special_tokens=False)\\n        decoded_preds = self.processing_class.batch_decode(preds, skip_special_tokens=skip_special_tokens)\\n        decoded_labels = self.processing_class.batch_decode(labels, skip_special_tokens=skip_special_tokens)\\n\\n        with open(output_prediction_file, \\\"w\\\", encoding=\\\"utf-8\\\") as f:\\n            for text, pred, label in zip(decoded_inputs, decoded_preds, decoded_labels):\\n                f.write(json.dumps({\\\"prompt\\\": text, \\\"predict\\\": pred, \\\"label\\\": label}, ensure_ascii=False) + \\\"\\\\n\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/sft/workflow.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"aaa1f92b66c4985fe1c1d47a6c28831a1cd0b107d77e3819c2ea174e37a1384b\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's transformers library.\\n# https://github.com/huggingface/transformers/blob/v4.40.0/examples/pytorch/summarization/run_summarization.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import TYPE_CHECKING, Optional\\n\\nfrom ...data import SFTDataCollatorWith4DAttentionMask, get_dataset, get_template_and_fix_tokenizer\\nfrom ...extras.constants import IGNORE_INDEX\\nfrom ...extras.logging import get_logger\\nfrom ...extras.misc import calculate_tps\\nfrom ...extras.packages import is_transformers_version_greater_than\\nfrom ...extras.ploting import plot_loss\\nfrom ...model import load_model, load_tokenizer\\nfrom ..trainer_utils import create_modelcard_and_push, create_ref_model\\nfrom .metric import ComputeAccuracy, ComputeSimilarity, eval_logit_processor\\nfrom .trainer import CustomSeq2SeqTrainer\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import Seq2SeqTrainingArguments, TrainerCallback\\n\\n    from ...hparams import DataArguments, FinetuningArguments, GeneratingArguments, ModelArguments\\n\\n\\nlogger = get_logger(__name__)\\n\\n\\ndef run_sft(\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"Seq2SeqTrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n    generating_args: \\\"GeneratingArguments\\\",\\n    callbacks: Optional[list[\\\"TrainerCallback\\\"]] = None,\\n):\\n    tokenizer_module = load_tokenizer(model_args)\\n    tokenizer = tokenizer_module[\\\"tokenizer\\\"]\\n    template = get_template_and_fix_tokenizer(tokenizer, data_args)\\n    dataset_module = get_dataset(template, model_args, data_args, training_args, stage=\\\"sft\\\", **tokenizer_module)\\n    model = load_model(tokenizer, model_args, finetuning_args, training_args.do_train)\\n\\n    ref_model = None\\n    if finetuning_args.use_asft_loss:\\n        ref_model = create_ref_model(model_args, finetuning_args)\\n\\n    if getattr(model, \\\"is_quantized\\\", False) and not training_args.do_train:\\n        setattr(model, \\\"_hf_peft_config_loaded\\\", True)  # hack here: make model compatible with prediction\\n\\n    data_collator = SFTDataCollatorWith4DAttentionMask(\\n        template=template,\\n        model=model if not training_args.predict_with_generate else None,\\n        pad_to_multiple_of=8 if training_args.do_train else None,  # for shift short attention\\n        label_pad_token_id=IGNORE_INDEX if data_args.ignore_pad_token_for_loss else tokenizer.pad_token_id,\\n        block_diag_attn=model_args.block_diag_attn,\\n        neat_packing=data_args.neat_packing,\\n        attn_implementation=getattr(model.config, \\\"_attn_implementation\\\", None),\\n        compute_dtype=model_args.compute_dtype,\\n        **tokenizer_module,\\n    )\\n\\n    # Metric utils\\n    metric_module = {}\\n    if model_args.use_kt:\\n        if training_args.predict_with_generate:\\n            raise NotImplementedError(\\\"`predict_with_generate` is not supported in KTransformers SFT yet.\\\")\\n        elif finetuning_args.compute_accuracy:\\n            raise NotImplementedError(\\\"`compute_accuracy` is not supported in KTransformers SFT yet.\\\")\\n\\n    if training_args.predict_with_generate:\\n        metric_module[\\\"compute_metrics\\\"] = ComputeSimilarity(tokenizer=tokenizer)\\n    elif finetuning_args.compute_accuracy:\\n        metric_module[\\\"compute_metrics\\\"] = ComputeAccuracy()\\n        metric_module[\\\"preprocess_logits_for_metrics\\\"] = eval_logit_processor\\n\\n    # Keyword arguments for `model.generate`\\n    gen_kwargs = generating_args.to_dict(obey_generation_config=True)\\n\\n    # Compatible with Transformers v4 and Transformers v5\\n    if is_transformers_version_greater_than(\\\"4.58.0\\\"):\\n        extra_ids = getattr(tokenizer, \\\"additional_special_tokens_ids\\\", None)\\n        if not isinstance(extra_ids, list):\\n            extra_special_tokens = getattr(tokenizer, \\\"_extra_special_tokens\\\", [])\\n            string_tokens = [str(t) for t in extra_special_tokens]\\n            extra_ids = tokenizer.convert_tokens_to_ids(string_tokens)\\n        all_eos_ids = [tokenizer.eos_token_id] + [i for i in extra_ids if i != -1]\\n        unique_eos_ids = list(dict.fromkeys(all_eos_ids))\\n        gen_kwargs[\\\"eos_token_id\\\"] = unique_eos_ids\\n    else:\\n        gen_kwargs[\\\"eos_token_id\\\"] = [tokenizer.eos_token_id] + tokenizer.additional_special_tokens_ids\\n    gen_kwargs[\\\"pad_token_id\\\"] = tokenizer.pad_token_id\\n\\n    # Initialize our Trainer\\n    trainer = CustomSeq2SeqTrainer(\\n        model=model,\\n        args=training_args,\\n        finetuning_args=finetuning_args,\\n        data_collator=data_collator,\\n        callbacks=callbacks,\\n        gen_kwargs=gen_kwargs,\\n        ref_model=ref_model,\\n        **dataset_module,\\n        **tokenizer_module,\\n        **metric_module,\\n    )\\n\\n    # Training\\n    if training_args.do_train:\\n        train_result = trainer.train(resume_from_checkpoint=training_args.resume_from_checkpoint)\\n        trainer.save_model()\\n        if finetuning_args.include_effective_tokens_per_second:\\n            train_result.metrics[\\\"effective_tokens_per_sec\\\"] = calculate_tps(\\n                dataset_module[\\\"train_dataset\\\"], train_result.metrics, stage=\\\"sft\\\"\\n            )\\n\\n        trainer.log_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_metrics(\\\"train\\\", train_result.metrics)\\n        trainer.save_state()\\n        if trainer.is_world_process_zero() and finetuning_args.plot_loss:\\n            keys = [\\\"loss\\\"]\\n            if isinstance(dataset_module.get(\\\"eval_dataset\\\"), dict):\\n                keys += sum(\\n                    [[f\\\"eval_{key}_loss\\\", f\\\"eval_{key}_accuracy\\\"] for key in dataset_module[\\\"eval_dataset\\\"].keys()], []\\n                )\\n            else:\\n                keys += [\\\"eval_loss\\\", \\\"eval_accuracy\\\"]\\n\\n            plot_loss(training_args.output_dir, keys=keys)\\n\\n    if training_args.predict_with_generate:\\n        tokenizer.padding_side = \\\"left\\\"  # use left-padding in generation\\n\\n    # Evaluation\\n    if training_args.do_eval:\\n        metrics = trainer.evaluate(metric_key_prefix=\\\"eval\\\", **gen_kwargs)\\n        trainer.log_metrics(\\\"eval\\\", metrics)\\n        trainer.save_metrics(\\\"eval\\\", metrics)\\n\\n    # Predict\\n    if training_args.do_predict:\\n        logger.warning_rank0_once(\\\"Batch generation can be very slow. Consider using `scripts/vllm_infer.py` instead.\\\")\\n        predict_results = trainer.predict(dataset_module[\\\"eval_dataset\\\"], metric_key_prefix=\\\"predict\\\", **gen_kwargs)\\n        trainer.log_metrics(\\\"predict\\\", predict_results.metrics)\\n        trainer.save_metrics(\\\"predict\\\", predict_results.metrics)\\n        trainer.save_predictions(dataset_module[\\\"eval_dataset\\\"], predict_results, generating_args.skip_special_tokens)\\n\\n    # Create model card\\n    create_modelcard_and_push(trainer, model_args, data_args, training_args, finetuning_args)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/test_utils.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"95c0e3aece396a6400f6aae27603d945dade75ea18117a6bb7025397b57381ba\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom typing import TYPE_CHECKING, Optional, Union\\n\\nimport torch\\nfrom peft import PeftModel\\nfrom transformers import AutoModelForCausalLM\\nfrom trl import AutoModelForCausalLMWithValueHead\\n\\nfrom ..data import get_dataset, get_template_and_fix_tokenizer\\nfrom ..hparams import get_infer_args, get_train_args\\nfrom ..model import load_model, load_tokenizer\\n\\n\\nif TYPE_CHECKING:\\n    from peft import LoraModel\\n    from transformers import PreTrainedModel\\n\\n    from ..data.data_utils import DatasetModule\\n\\n\\ndef compare_model(model_a: \\\"torch.nn.Module\\\", model_b: \\\"torch.nn.Module\\\", diff_keys: list[str] = []) -> None:\\n    state_dict_a = model_a.state_dict()\\n    state_dict_b = model_b.state_dict()\\n    assert set(state_dict_a.keys()) == set(state_dict_b.keys())\\n    for name in state_dict_a.keys():\\n        if any(key in name for key in diff_keys):\\n            assert torch.allclose(state_dict_a[name], state_dict_b[name], rtol=1e-4, atol=1e-5) is False\\n        else:\\n            assert torch.allclose(state_dict_a[name], state_dict_b[name], rtol=1e-4, atol=1e-5) is True\\n\\n\\ndef check_lora_model(model: \\\"LoraModel\\\") -> tuple[set[str], set[str]]:\\n    linear_modules, extra_modules = set(), set()\\n    for name, param in model.named_parameters():\\n        if any(module in name for module in [\\\"lora_A\\\", \\\"lora_B\\\"]):\\n            linear_modules.add(name.split(\\\".lora_\\\", maxsplit=1)[0].split(\\\".\\\")[-1])\\n            assert param.requires_grad is True\\n            assert param.dtype == torch.float32\\n        elif \\\"modules_to_save\\\" in name:\\n            extra_modules.add(name.split(\\\".modules_to_save\\\", maxsplit=1)[0].split(\\\".\\\")[-1])\\n            assert param.requires_grad is True\\n            assert param.dtype == torch.float32\\n        else:\\n            assert param.requires_grad is False\\n            assert param.dtype == torch.float16\\n\\n    return linear_modules, extra_modules\\n\\n\\ndef load_train_model(add_valuehead: bool = False, **kwargs) -> \\\"PreTrainedModel\\\":\\n    model_args, _, _, finetuning_args, _ = get_train_args(kwargs)\\n    tokenizer = load_tokenizer(model_args)[\\\"tokenizer\\\"]\\n    return load_model(tokenizer, model_args, finetuning_args, is_trainable=True, add_valuehead=add_valuehead)\\n\\n\\ndef load_infer_model(add_valuehead: bool = False, **kwargs) -> \\\"PreTrainedModel\\\":\\n    model_args, _, finetuning_args, _ = get_infer_args(kwargs)\\n    tokenizer = load_tokenizer(model_args)[\\\"tokenizer\\\"]\\n    return load_model(tokenizer, model_args, finetuning_args, is_trainable=False, add_valuehead=add_valuehead)\\n\\n\\ndef load_reference_model(\\n    model_path: str,\\n    lora_path: Optional[str] = None,\\n    use_lora: bool = False,\\n    use_pissa: bool = False,\\n    is_trainable: bool = False,\\n    add_valuehead: bool = False,\\n) -> Union[\\\"PreTrainedModel\\\", \\\"LoraModel\\\"]:\\n    if add_valuehead:\\n        model: AutoModelForCausalLMWithValueHead = AutoModelForCausalLMWithValueHead.from_pretrained(\\n            model_path, torch_dtype=torch.float16, device_map=\\\"auto\\\"\\n        )\\n\\n        return model\\n\\n    model = AutoModelForCausalLM.from_pretrained(model_path, torch_dtype=torch.float16, device_map=\\\"auto\\\")\\n    if use_lora or use_pissa:\\n        model = PeftModel.from_pretrained(\\n            model, lora_path, subfolder=\\\"pissa_init\\\" if use_pissa else None, is_trainable=is_trainable\\n        )\\n        for param in filter(lambda p: p.requires_grad, model.parameters()):\\n            param.data = param.data.to(torch.float32)\\n\\n    return model\\n\\n\\ndef load_dataset_module(**kwargs) -> \\\"DatasetModule\\\":\\n    model_args, data_args, training_args, _, _ = get_train_args(kwargs)\\n    tokenizer_module = load_tokenizer(model_args)\\n    template = get_template_and_fix_tokenizer(tokenizer_module[\\\"tokenizer\\\"], data_args)\\n    dataset_module = get_dataset(template, model_args, data_args, training_args, kwargs[\\\"stage\\\"], **tokenizer_module)\\n    return dataset_module\\n\\n\\ndef patch_valuehead_model() -> None:\\n    def post_init(self: \\\"AutoModelForCausalLMWithValueHead\\\", state_dict: dict[str, \\\"torch.Tensor\\\"]) -> None:\\n        state_dict = {k[7:]: state_dict[k] for k in state_dict.keys() if k.startswith(\\\"v_head.\\\")}\\n        self.v_head.load_state_dict(state_dict, strict=False)\\n        del state_dict\\n\\n    AutoModelForCausalLMWithValueHead.post_init = post_init\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/trainer_utils.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"ff726b2be4a7c24e4c09eb22b0336481dea3a35631076e35bb63a571bf3c9111\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the original GaLore's implementation: https://github.com/jiaweizzhao/GaLore\\n# and the original LoRA+'s implementation: https://github.com/nikhil-ghosh-berkeley/loraplus\\n# and the original BAdam's implementation: https://github.com/Ledzy/BAdam\\n# and the HuggingFace's TRL library: https://github.com/huggingface/trl\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport json\\nimport os\\nfrom collections.abc import Callable, Mapping\\nfrom typing import TYPE_CHECKING, Any, Optional, Union\\n\\nimport torch\\nimport torch.nn.functional as F\\nfrom transformers import Trainer\\nfrom transformers.integrations import is_deepspeed_zero3_enabled\\nfrom transformers.modeling_utils import is_fsdp_enabled\\nfrom transformers.optimization import get_scheduler\\nfrom transformers.pytorch_utils import ALL_LAYERNORM_LAYERS\\nfrom transformers.trainer_pt_utils import get_parameter_names\\nfrom typing_extensions import override\\n\\nfrom ..extras import logging\\nfrom ..extras.constants import IGNORE_INDEX, SWANLAB_CONFIG\\nfrom ..extras.misc import get_device_name\\nfrom ..extras.packages import is_apollo_available, is_galore_available, is_ray_available\\nfrom ..hparams import FinetuningArguments, ModelArguments\\nfrom ..model import find_all_linear_modules, load_model, load_tokenizer, load_valuehead_params\\n\\n\\nif is_galore_available():\\n    from galore_torch import GaLoreAdafactor, GaLoreAdamW, GaLoreAdamW8bit  # type: ignore\\n\\n\\nif is_apollo_available():\\n    from apollo_torch import APOLLOAdamW  # type: ignore\\n\\n\\nif is_ray_available():\\n    import ray\\n    from ray.util.placement_group import PlacementGroup, placement_group\\n    from ray.util.scheduling_strategies import PlacementGroupSchedulingStrategy\\n    from ray.util.state import list_nodes\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import PreTrainedModel, TrainerCallback, TrainerState\\n    from trl import AutoModelForCausalLMWithValueHead\\n\\n    from ..hparams import DataArguments, TrainingArguments\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\nclass DummyOptimizer(torch.optim.Optimizer):\\n    r\\\"\\\"\\\"A dummy optimizer used for the GaLore or APOLLO algorithm.\\\"\\\"\\\"\\n\\n    def __init__(\\n        self, lr: float = 1e-3, optimizer_dict: Optional[dict[\\\"torch.nn.Parameter\\\", \\\"torch.optim.Optimizer\\\"]] = None\\n    ) -> None:\\n        dummy_tensor = torch.randn(1, 1)\\n        self.optimizer_dict = optimizer_dict\\n        super().__init__([dummy_tensor], {\\\"lr\\\": lr})\\n\\n    @override\\n    def zero_grad(self, set_to_none: bool = True) -> None:\\n        pass\\n\\n    @override\\n    def step(self, closure: Optional[Callable[[], float]] = None) -> Optional[float]:\\n        pass\\n\\n\\ndef create_modelcard_and_push(\\n    trainer: \\\"Trainer\\\",\\n    model_args: \\\"ModelArguments\\\",\\n    data_args: \\\"DataArguments\\\",\\n    training_args: \\\"TrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n) -> None:\\n    kwargs = {\\n        \\\"tasks\\\": \\\"text-generation\\\",\\n        \\\"finetuned_from\\\": model_args.model_name_or_path,\\n        \\\"tags\\\": [\\\"llama-factory\\\", finetuning_args.finetuning_type],\\n    }\\n    if data_args.dataset is not None:\\n        kwargs[\\\"dataset\\\"] = data_args.dataset\\n\\n    if model_args.use_unsloth:\\n        kwargs[\\\"tags\\\"] = kwargs[\\\"tags\\\"] + [\\\"unsloth\\\"]\\n\\n    if model_args.use_kt:\\n        kwargs[\\\"tags\\\"] = kwargs[\\\"tags\\\"] + [\\\"kt-kernel\\\"]\\n\\n    if not training_args.do_train:\\n        pass\\n    elif training_args.push_to_hub:\\n        trainer.push_to_hub(**kwargs)\\n    else:\\n        Trainer.create_model_card(trainer, license=\\\"other\\\", **kwargs)  # prevent from connecting to hub\\n\\n\\ndef create_ref_model(\\n    model_args: \\\"ModelArguments\\\", finetuning_args: \\\"FinetuningArguments\\\", add_valuehead: bool = False\\n) -> Optional[Union[\\\"PreTrainedModel\\\", \\\"AutoModelForCausalLMWithValueHead\\\"]]:\\n    r\\\"\\\"\\\"Create reference model for PPO/DPO training. Evaluation mode is not supported.\\n\\n    The valuehead parameter is randomly initialized since it is useless for PPO training.\\n    \\\"\\\"\\\"\\n    if finetuning_args.ref_model is not None:\\n        ref_model_args = ModelArguments.copyfrom(\\n            model_args,\\n            model_name_or_path=finetuning_args.ref_model,\\n            adapter_name_or_path=finetuning_args.ref_model_adapters,\\n            quantization_bit=finetuning_args.ref_model_quantization_bit,\\n        )\\n        ref_finetuning_args = FinetuningArguments()\\n        tokenizer = load_tokenizer(ref_model_args)[\\\"tokenizer\\\"]\\n        ref_model = load_model(\\n            tokenizer, ref_model_args, ref_finetuning_args, is_trainable=False, add_valuehead=add_valuehead\\n        )\\n        logger.info_rank0(f\\\"Created reference model from {finetuning_args.ref_model}\\\")\\n    else:\\n        if finetuning_args.finetuning_type == \\\"lora\\\":\\n            ref_model = None\\n        else:\\n            ref_model_args = ModelArguments.copyfrom(model_args)\\n            ref_finetuning_args = FinetuningArguments()\\n            tokenizer = load_tokenizer(ref_model_args)[\\\"tokenizer\\\"]\\n            ref_model = load_model(\\n                tokenizer, ref_model_args, ref_finetuning_args, is_trainable=False, add_valuehead=add_valuehead\\n            )\\n            logger.info_rank0(\\\"Created reference model from the model itself.\\\")\\n\\n    return ref_model\\n\\n\\ndef create_reward_model(\\n    model: \\\"AutoModelForCausalLMWithValueHead\\\", model_args: \\\"ModelArguments\\\", finetuning_args: \\\"FinetuningArguments\\\"\\n) -> Optional[\\\"AutoModelForCausalLMWithValueHead\\\"]:\\n    r\\\"\\\"\\\"Create reward model for PPO training.\\\"\\\"\\\"\\n    if finetuning_args.reward_model_type == \\\"api\\\":\\n        assert finetuning_args.reward_model.startswith(\\\"http\\\"), \\\"Please provide full url.\\\"\\n        logger.info_rank0(f\\\"Use reward server {finetuning_args.reward_model}\\\")\\n        return finetuning_args.reward_model\\n    elif finetuning_args.reward_model_type == \\\"lora\\\":\\n        model.pretrained_model.load_adapter(finetuning_args.reward_model, \\\"reward\\\")\\n        for name, param in model.named_parameters():  # https://github.com/huggingface/peft/issues/1090\\n            if \\\"default\\\" in name:\\n                param.data = param.data.to(torch.float32)  # trainable params should in fp32\\n        vhead_params = load_valuehead_params(finetuning_args.reward_model, model_args)\\n        assert vhead_params is not None, \\\"Reward model is not correctly loaded.\\\"\\n        model.register_buffer(\\\"reward_head_weight\\\", vhead_params[\\\"v_head.summary.weight\\\"], persistent=False)\\n        model.register_buffer(\\\"reward_head_bias\\\", vhead_params[\\\"v_head.summary.bias\\\"], persistent=False)\\n        model.register_buffer(\\n            \\\"default_head_weight\\\", torch.zeros_like(vhead_params[\\\"v_head.summary.weight\\\"]), persistent=False\\n        )\\n        model.register_buffer(\\n            \\\"default_head_bias\\\", torch.zeros_like(vhead_params[\\\"v_head.summary.bias\\\"]), persistent=False\\n        )\\n        logger.info_rank0(f\\\"Loaded adapter weights of reward model from {finetuning_args.reward_model}\\\")\\n        return None\\n    else:\\n        reward_model_args = ModelArguments.copyfrom(\\n            model_args,\\n            model_name_or_path=finetuning_args.reward_model,\\n            adapter_name_or_path=finetuning_args.reward_model_adapters,\\n            quantization_bit=finetuning_args.reward_model_quantization_bit,\\n        )\\n        reward_finetuning_args = FinetuningArguments()\\n        tokenizer = load_tokenizer(reward_model_args)[\\\"tokenizer\\\"]\\n        reward_model = load_model(\\n            tokenizer, reward_model_args, reward_finetuning_args, is_trainable=False, add_valuehead=True\\n        )\\n        logger.info_rank0(f\\\"Loaded full weights of reward model from {finetuning_args.reward_model}\\\")\\n        logger.warning_rank0(\\\"Please ensure the ppo model and reward model share SAME tokenizer and vocabulary.\\\")\\n        return reward_model\\n\\n\\ndef _get_decay_parameter_names(model: \\\"PreTrainedModel\\\") -> list[str]:\\n    r\\\"\\\"\\\"Return a list of names of parameters with weight decay. (weights in non-layernorm layers).\\\"\\\"\\\"\\n    decay_parameters = get_parameter_names(model, ALL_LAYERNORM_LAYERS)\\n    decay_parameters = [name for name in decay_parameters if \\\"bias\\\" not in name]\\n    return decay_parameters\\n\\n\\ndef _create_galore_optimizer(\\n    model: \\\"PreTrainedModel\\\",\\n    training_args: \\\"TrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n) -> \\\"torch.optim.Optimizer\\\":\\n    if len(finetuning_args.galore_target) == 1 and finetuning_args.galore_target[0] == \\\"all\\\":\\n        galore_targets = find_all_linear_modules(model, finetuning_args.freeze_vision_tower)\\n    else:\\n        galore_targets = finetuning_args.galore_target\\n\\n    galore_params: list[torch.nn.Parameter] = []\\n    for name, module in model.named_modules():\\n        if isinstance(module, torch.nn.Linear) and any(target in name for target in galore_targets):\\n            for param in module.parameters():\\n                if param.requires_grad and len(param.shape) > 1:\\n                    galore_params.append(param)\\n\\n    galore_kwargs = {\\n        \\\"rank\\\": finetuning_args.galore_rank,\\n        \\\"update_proj_gap\\\": finetuning_args.galore_update_interval,\\n        \\\"scale\\\": finetuning_args.galore_scale,\\n        \\\"proj_type\\\": finetuning_args.galore_proj_type,\\n    }\\n\\n    id_galore_params = {id(param) for param in galore_params}\\n    decay_params, nodecay_params = [], []  # they are non-galore parameters\\n    trainable_params: list[torch.nn.Parameter] = []  # galore_params + decay_params + nodecay_params\\n    decay_param_names = _get_decay_parameter_names(model)\\n    for name, param in model.named_parameters():\\n        if param.requires_grad:\\n            trainable_params.append(param)\\n            if id(param) not in id_galore_params:\\n                if name in decay_param_names:\\n                    decay_params.append(param)\\n                else:\\n                    nodecay_params.append(param)\\n\\n    _, optim_kwargs = Trainer.get_optimizer_cls_and_kwargs(training_args)\\n\\n    if training_args.optim == \\\"adamw_torch\\\":\\n        optim_class = GaLoreAdamW\\n    elif training_args.optim in [\\\"adamw_bnb_8bit\\\", \\\"adamw_8bit\\\", \\\"paged_adamw_8bit\\\"]:\\n        optim_class = GaLoreAdamW8bit\\n    elif training_args.optim == \\\"adafactor\\\":\\n        optim_class = GaLoreAdafactor\\n    else:\\n        raise NotImplementedError(f\\\"Unknown optim: {training_args.optim}.\\\")\\n\\n    if finetuning_args.galore_layerwise:\\n        logger.warning_rank0(\\\"The displayed gradient norm will be all zeros in layerwise GaLore.\\\")\\n        if training_args.gradient_accumulation_steps != 1:\\n            raise ValueError(\\\"Per-layer GaLore does not support gradient accumulation.\\\")\\n\\n        optimizer_dict: dict[torch.Tensor, torch.optim.Optimizer] = {}\\n        for param in nodecay_params:\\n            param_groups = [dict(params=[param], weight_decay=0.0)]\\n            optimizer_dict[param] = optim_class(param_groups, **optim_kwargs)\\n        for param in decay_params:\\n            param_groups = [dict(params=[param], weight_decay=training_args.weight_decay)]\\n            optimizer_dict[param] = optim_class(param_groups, **optim_kwargs)\\n        for param in galore_params:  # galore params have weight decay\\n            param_groups = [dict(params=[param], weight_decay=training_args.weight_decay, **galore_kwargs)]\\n            optimizer_dict[param] = optim_class(param_groups, **optim_kwargs)\\n\\n        def optimizer_hook(param: \\\"torch.nn.Parameter\\\"):\\n            if param.grad is not None:\\n                optimizer_dict[param].step()\\n                optimizer_dict[param].zero_grad()\\n\\n        for param in trainable_params:\\n            param.register_post_accumulate_grad_hook(optimizer_hook)\\n\\n        optimizer = DummyOptimizer(lr=training_args.learning_rate, optimizer_dict=optimizer_dict)\\n    else:\\n        param_groups = [\\n            dict(params=nodecay_params, weight_decay=0.0),\\n            dict(params=decay_params, weight_decay=training_args.weight_decay),\\n            dict(params=galore_params, weight_decay=training_args.weight_decay, **galore_kwargs),\\n        ]\\n        optimizer = optim_class(param_groups, **optim_kwargs)\\n\\n    logger.info_rank0(\\n        f\\\"Using GaLore optimizer with args: {galore_kwargs}. \\\"\\n        \\\"It may cause hanging at the start of training, wait patiently.\\\"\\n    )\\n    return optimizer\\n\\n\\ndef _create_apollo_optimizer(\\n    model: \\\"PreTrainedModel\\\",\\n    training_args: \\\"TrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n) -> \\\"torch.optim.Optimizer\\\":\\n    if len(finetuning_args.apollo_target) == 1 and finetuning_args.apollo_target[0] == \\\"all\\\":\\n        apollo_targets = find_all_linear_modules(model, finetuning_args.freeze_vision_tower)\\n    else:\\n        apollo_targets = finetuning_args.apollo_target\\n\\n    apollo_params: list[torch.nn.Parameter] = []\\n    for name, module in model.named_modules():\\n        if isinstance(module, torch.nn.Linear) and any(target in name for target in apollo_targets):\\n            for param in module.parameters():\\n                if param.requires_grad and len(param.shape) > 1:\\n                    apollo_params.append(param)\\n\\n    apollo_kwargs = {\\n        \\\"rank\\\": finetuning_args.apollo_rank,\\n        \\\"proj\\\": finetuning_args.apollo_proj,\\n        \\\"proj_type\\\": finetuning_args.apollo_proj_type,\\n        \\\"update_proj_gap\\\": finetuning_args.apollo_update_interval,\\n        \\\"scale\\\": finetuning_args.apollo_scale,\\n        \\\"scale_type\\\": finetuning_args.apollo_scale_type,\\n        \\\"scale_front\\\": finetuning_args.apollo_scale_front,\\n    }\\n\\n    id_apollo_params = {id(param) for param in apollo_params}\\n    decay_params, nodecay_params = [], []  # they are non-apollo parameters\\n    trainable_params: list[torch.nn.Parameter] = []  # apollo_params + decay_params + nodecay_params\\n    decay_param_names = _get_decay_parameter_names(model)\\n    for name, param in model.named_parameters():\\n        if param.requires_grad:\\n            trainable_params.append(param)\\n            if id(param) not in id_apollo_params:\\n                if name in decay_param_names:\\n                    decay_params.append(param)\\n                else:\\n                    nodecay_params.append(param)\\n\\n    _, optim_kwargs = Trainer.get_optimizer_cls_and_kwargs(training_args)\\n\\n    if training_args.optim == \\\"adamw_torch\\\":\\n        optim_class = APOLLOAdamW\\n    else:\\n        raise NotImplementedError(f\\\"Unknown optim: {training_args.optim}.\\\")\\n\\n    if finetuning_args.apollo_layerwise:\\n        logger.warning_rank0(\\\"The displayed gradient norm will be all zeros in layerwise APOLLO.\\\")\\n        if training_args.gradient_accumulation_steps != 1:\\n            raise ValueError(\\\"Per-layer APOLLO does not support gradient accumulation.\\\")\\n\\n        optimizer_dict: dict[torch.Tensor, torch.optim.Optimizer] = {}\\n        for param in nodecay_params:\\n            param_groups = [dict(params=[param], weight_decay=0.0)]\\n            optimizer_dict[param] = optim_class(param_groups, **optim_kwargs)\\n        for param in decay_params:\\n            param_groups = [dict(params=[param], weight_decay=training_args.weight_decay)]\\n            optimizer_dict[param] = optim_class(param_groups, **optim_kwargs)\\n        for param in apollo_params:  # apollo params have weight decay\\n            param_groups = [dict(params=[param], weight_decay=training_args.weight_decay, **apollo_kwargs)]\\n            optimizer_dict[param] = optim_class(param_groups, **optim_kwargs)\\n\\n        def optimizer_hook(param: \\\"torch.nn.Parameter\\\"):\\n            if param.grad is not None:\\n                optimizer_dict[param].step()\\n                optimizer_dict[param].zero_grad()\\n\\n        for param in trainable_params:\\n            param.register_post_accumulate_grad_hook(optimizer_hook)\\n\\n        optimizer = DummyOptimizer(lr=training_args.learning_rate, optimizer_dict=optimizer_dict)\\n    else:\\n        param_groups = [\\n            dict(params=nodecay_params, weight_decay=0.0),\\n            dict(params=decay_params, weight_decay=training_args.weight_decay),\\n            dict(params=apollo_params, weight_decay=training_args.weight_decay, **apollo_kwargs),\\n        ]\\n        optimizer = optim_class(param_groups, **optim_kwargs)\\n\\n    logger.info_rank0(f\\\"Using APOLLO optimizer with args: {apollo_kwargs}.\\\")\\n    return optimizer\\n\\n\\ndef _create_loraplus_optimizer(\\n    model: \\\"PreTrainedModel\\\",\\n    training_args: \\\"TrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n) -> \\\"torch.optim.Optimizer\\\":\\n    default_lr = training_args.learning_rate\\n    loraplus_lr = training_args.learning_rate * finetuning_args.loraplus_lr_ratio\\n    embedding_lr = finetuning_args.loraplus_lr_embedding\\n\\n    decay_param_names = _get_decay_parameter_names(model)\\n    param_dict: dict[str, list[torch.nn.Parameter]] = {\\n        \\\"lora_a\\\": [],\\n        \\\"lora_b\\\": [],\\n        \\\"lora_b_nodecay\\\": [],\\n        \\\"embedding\\\": [],\\n    }\\n    for name, param in model.named_parameters():\\n        if param.requires_grad:\\n            if \\\"lora_embedding_B\\\" in name:\\n                param_dict[\\\"embedding\\\"].append(param)\\n            elif \\\"lora_B\\\" in name or param.ndim == 1:\\n                if name in decay_param_names:\\n                    param_dict[\\\"lora_b\\\"].append(param)\\n                else:\\n                    param_dict[\\\"lora_b_nodecay\\\"].append(param)\\n            else:\\n                param_dict[\\\"lora_a\\\"].append(param)\\n\\n    optim_class, optim_kwargs = Trainer.get_optimizer_cls_and_kwargs(training_args)\\n    param_groups = [\\n        dict(params=param_dict[\\\"lora_a\\\"], lr=default_lr, weight_decay=training_args.weight_decay),\\n        dict(params=param_dict[\\\"lora_b\\\"], lr=loraplus_lr, weight_decay=training_args.weight_decay),\\n        dict(params=param_dict[\\\"lora_b_nodecay\\\"], lr=loraplus_lr, weight_decay=0.0),\\n        dict(params=param_dict[\\\"embedding\\\"], lr=embedding_lr, weight_decay=training_args.weight_decay),\\n    ]\\n    optimizer = optim_class(param_groups, **optim_kwargs)\\n    logger.info_rank0(f\\\"Using LoRA+ optimizer with loraplus lr ratio {finetuning_args.loraplus_lr_ratio:.2f}.\\\")\\n    return optimizer\\n\\n\\ndef _create_badam_optimizer(\\n    model: \\\"PreTrainedModel\\\",\\n    training_args: \\\"TrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n) -> \\\"torch.optim.Optimizer\\\":\\n    decay_params, nodecay_params = [], []\\n    decay_param_names = _get_decay_parameter_names(model)\\n    for name, param in model.named_parameters():\\n        if param.requires_grad:\\n            if name in decay_param_names:\\n                decay_params.append(param)\\n            else:\\n                nodecay_params.append(param)\\n\\n    optim_class, optim_kwargs = Trainer.get_optimizer_cls_and_kwargs(training_args)\\n    param_groups = [\\n        dict(params=nodecay_params, weight_decay=0.0),\\n        dict(params=decay_params, weight_decay=training_args.weight_decay),\\n    ]\\n\\n    if finetuning_args.badam_mode == \\\"layer\\\":\\n        from badam import BlockOptimizer  # type: ignore\\n\\n        base_optimizer = optim_class(param_groups, **optim_kwargs)\\n        optimizer = BlockOptimizer(\\n            base_optimizer=base_optimizer,\\n            named_parameters_list=list(model.named_parameters()),\\n            block_prefix_list=None,\\n            switch_block_every=finetuning_args.badam_switch_interval,\\n            start_block=finetuning_args.badam_start_block,\\n            switch_mode=finetuning_args.badam_switch_mode,\\n            verbose=finetuning_args.badam_verbose,\\n            ds_zero3_enabled=is_deepspeed_zero3_enabled(),\\n        )\\n        logger.info_rank0(\\n            f\\\"Using BAdam optimizer with layer-wise update, switch mode is {finetuning_args.badam_switch_mode}, \\\"\\n            f\\\"switch block every {finetuning_args.badam_switch_interval} steps, \\\"\\n            f\\\"default start block is {finetuning_args.badam_start_block}\\\"\\n        )\\n\\n    elif finetuning_args.badam_mode == \\\"ratio\\\":\\n        from badam import BlockOptimizerRatio  # type: ignore\\n\\n        assert finetuning_args.badam_update_ratio > 1e-6\\n        optimizer = BlockOptimizerRatio(\\n            param_groups=param_groups,\\n            named_parameters_list=list(model.named_parameters()),\\n            update_ratio=finetuning_args.badam_update_ratio,\\n            mask_mode=finetuning_args.badam_mask_mode,\\n            verbose=finetuning_args.badam_verbose,\\n            include_embedding=False,\\n            **optim_kwargs,\\n        )\\n        logger.info_rank0(\\n            f\\\"Using BAdam optimizer with ratio-based update, update ratio is {finetuning_args.badam_update_ratio}, \\\"\\n            f\\\"mask mode is {finetuning_args.badam_mask_mode}\\\"\\n        )\\n\\n    return optimizer\\n\\n\\ndef _create_adam_mini_optimizer(\\n    model: \\\"PreTrainedModel\\\",\\n    training_args: \\\"TrainingArguments\\\",\\n) -> \\\"torch.optim.Optimizer\\\":\\n    from adam_mini import Adam_mini  # type: ignore\\n\\n    hidden_size = getattr(model.config, \\\"hidden_size\\\", None)\\n    num_q_head = getattr(model.config, \\\"num_attention_heads\\\", None)\\n    num_kv_head = getattr(model.config, \\\"num_key_value_heads\\\", None)\\n\\n    optimizer = Adam_mini(\\n        named_parameters=model.named_parameters(),\\n        lr=training_args.learning_rate,\\n        betas=(training_args.adam_beta1, training_args.adam_beta2),\\n        eps=training_args.adam_epsilon,\\n        weight_decay=training_args.weight_decay,\\n        model_sharding=is_fsdp_enabled() or is_deepspeed_zero3_enabled(),\\n        dim=hidden_size,\\n        n_heads=num_q_head,\\n        n_kv_heads=num_kv_head,\\n    )\\n    logger.info_rank0(\\\"Using Adam-mini optimizer.\\\")\\n    return optimizer\\n\\n\\ndef _create_muon_optimizer(\\n    model: \\\"PreTrainedModel\\\",\\n    training_args: \\\"TrainingArguments\\\",\\n) -> \\\"torch.optim.Optimizer\\\":\\n    from ..third_party.muon import Muon\\n\\n    muon_params, adamw_params = [], []\\n    for name, param in model.named_parameters():\\n        if param.requires_grad:\\n            # Use Muon for 2D parameters that aren't embeddings or heads\\n            if param.ndim == 2 and \\\"embed\\\" not in name and \\\"lm_head\\\" not in name:\\n                muon_params.append(param)\\n            else:\\n                adamw_params.append(param)\\n\\n    optimizer = Muon(\\n        lr=training_args.learning_rate,\\n        wd=training_args.weight_decay,\\n        muon_params=muon_params,\\n        adamw_params=adamw_params,\\n        adamw_betas=(training_args.adam_beta1, training_args.adam_beta2),\\n        adamw_eps=training_args.adam_epsilon,\\n    )\\n    logger.info_rank0(\\n        f\\\"Using Muon optimizer with {len(muon_params)} Muon params and {len(adamw_params)} AdamW params.\\\"\\n    )\\n    return optimizer\\n\\n\\ndef create_custom_optimizer(\\n    model: \\\"PreTrainedModel\\\",\\n    training_args: \\\"TrainingArguments\\\",\\n    finetuning_args: \\\"FinetuningArguments\\\",\\n) -> Optional[\\\"torch.optim.Optimizer\\\"]:\\n    if finetuning_args.use_galore:\\n        return _create_galore_optimizer(model, training_args, finetuning_args)\\n\\n    if finetuning_args.use_apollo:\\n        return _create_apollo_optimizer(model, training_args, finetuning_args)\\n\\n    if finetuning_args.loraplus_lr_ratio is not None:\\n        return _create_loraplus_optimizer(model, training_args, finetuning_args)\\n\\n    if finetuning_args.use_badam:\\n        return _create_badam_optimizer(model, training_args, finetuning_args)\\n\\n    if finetuning_args.use_adam_mini:\\n        return _create_adam_mini_optimizer(model, training_args)\\n\\n    if finetuning_args.use_muon:\\n        return _create_muon_optimizer(model, training_args)\\n\\n\\ndef create_custom_scheduler(\\n    training_args: \\\"TrainingArguments\\\",\\n    num_training_steps: int,\\n    optimizer: Optional[\\\"torch.optim.Optimizer\\\"] = None,\\n) -> None:\\n    if training_args.lr_scheduler_type == \\\"warmup_stable_decay\\\":\\n        num_warmup_steps = training_args.get_warmup_steps(num_training_steps)\\n        remaining_steps = num_training_steps - num_warmup_steps\\n        num_stable_steps = remaining_steps // 3  # use 1/3 for stable by default\\n        num_decay_steps = remaining_steps - num_stable_steps\\n        scheduler_kwargs = training_args.lr_scheduler_kwargs or {}\\n        default_kwargs = {\\n            \\\"num_stable_steps\\\": num_stable_steps,\\n            \\\"num_decay_steps\\\": num_decay_steps,\\n        }\\n        for key, value in default_kwargs.items():\\n            if key not in scheduler_kwargs:\\n                scheduler_kwargs[key] = value\\n\\n        training_args.lr_scheduler_kwargs = scheduler_kwargs\\n\\n    if optimizer is not None and isinstance(optimizer, DummyOptimizer):\\n        optimizer_dict = optimizer.optimizer_dict\\n        scheduler_dict: dict[torch.nn.Parameter, torch.optim.lr_scheduler.LRScheduler] = {}\\n\\n        for param in optimizer_dict.keys():\\n            scheduler_dict[param] = get_scheduler(\\n                training_args.lr_scheduler_type,\\n                optimizer=optimizer_dict[param],\\n                num_warmup_steps=training_args.get_warmup_steps(num_training_steps),\\n                num_training_steps=num_training_steps,\\n                scheduler_specific_kwargs=training_args.lr_scheduler_kwargs,\\n            )\\n\\n        def scheduler_hook(param: \\\"torch.nn.Parameter\\\"):\\n            scheduler_dict[param].step()\\n\\n        for param in optimizer_dict.keys():\\n            param.register_post_accumulate_grad_hook(scheduler_hook)\\n\\n\\ndef get_batch_logps(\\n    logits: \\\"torch.Tensor\\\",\\n    labels: \\\"torch.Tensor\\\",\\n    label_pad_token_id: int = IGNORE_INDEX,\\n    ld_alpha: Optional[float] = None,\\n) -> tuple[\\\"torch.Tensor\\\", \\\"torch.Tensor\\\"]:\\n    r\\\"\\\"\\\"Compute the log probabilities of the given labels under the given logits.\\n\\n    Returns:\\n        logps: A tensor of shape (batch_size,) containing the sum of log probabilities.\\n        valid_length: A tensor of shape (batch_size,) containing the number of non-masked tokens.\\n\\n    \\\"\\\"\\\"\\n    if logits.shape[:-1] != labels.shape:\\n        raise ValueError(\\\"Logits (batchsize x seqlen) and labels must have the same shape.\\\")\\n\\n    labels = labels[:, 1:].clone()\\n    logits = logits[:, :-1, :]\\n    loss_mask = labels != label_pad_token_id\\n    labels[labels == label_pad_token_id] = 0  # dummy token\\n    per_token_logps = torch.gather(logits.log_softmax(-1), dim=2, index=labels.unsqueeze(2)).squeeze(2)\\n\\n    valid_length = loss_mask.sum(-1)\\n    if ld_alpha is not None:\\n        num_examples = labels.shape[0] // 2\\n        chosen_lengths = valid_length[:num_examples]\\n        rejected_lengths = valid_length[num_examples:]\\n        min_lengths = torch.min(chosen_lengths, rejected_lengths)\\n        start_positions = torch.argmax(loss_mask.int(), dim=1)\\n        public_lengths = start_positions + torch.cat([min_lengths, min_lengths], dim=0)\\n\\n        seq_len = labels.shape[-1]\\n        position_ids = torch.arange(seq_len, device=per_token_logps.device).expand_as(per_token_logps)\\n\\n        ld_mask = position_ids < public_lengths.unsqueeze(1)\\n        front_mask = (ld_mask * loss_mask).float()\\n        rear_mask = (~ld_mask * loss_mask).float()\\n\\n        front_logps = (per_token_logps * front_mask).sum(-1)\\n        rear_logps = (per_token_logps * rear_mask).sum(-1)\\n        logps = front_logps + ld_alpha * rear_logps\\n    else:\\n        logps = (per_token_logps * loss_mask).sum(-1)\\n\\n    return logps, valid_length\\n\\n\\ndef dft_loss_func(\\n    outputs: \\\"torch.Tensor\\\", labels: \\\"torch.Tensor\\\", num_items_in_batch: Optional[\\\"torch.Tensor\\\"] = None\\n):\\n    logits = outputs.get(\\\"logits\\\")\\n    if logits is None:\\n        return outputs.get(\\\"loss\\\", torch.tensor(0.0))\\n\\n    logits = logits.float()\\n    vocab_size = logits.size(-1)\\n    labels = torch.nn.functional.pad(labels, (0, 1), value=-100)\\n    shift_labels = labels[..., 1:].contiguous()\\n    logits = logits.view(-1, vocab_size)\\n    shift_labels = shift_labels.view(-1)\\n    shift_labels = shift_labels.to(logits.device)\\n\\n    loss = _dft_cross_entropy(logits, shift_labels, num_items_in_batch)\\n    return loss\\n\\n\\ndef _dft_cross_entropy(\\n    source: \\\"torch.Tensor\\\",\\n    target: \\\"torch.Tensor\\\",\\n    num_items_in_batch: Optional[\\\"torch.Tensor\\\"] = None,\\n    ignore_index: int = -100,\\n) -> \\\"torch.Tensor\\\":\\n    per_token_loss = torch.nn.functional.cross_entropy(source, target, ignore_index=ignore_index, reduction=\\\"none\\\")\\n    valid_mask = target != ignore_index\\n    if not valid_mask.any():\\n        return torch.tensor(0.0, device=source.device, dtype=source.dtype)\\n\\n    valid_losses = per_token_loss[valid_mask]\\n\\n    with torch.no_grad():\\n        target_probs = torch.exp(-valid_losses)\\n\\n    weighted_losses = valid_losses * target_probs\\n\\n    if num_items_in_batch is not None:\\n        total_loss = weighted_losses.sum()\\n        if torch.is_tensor(num_items_in_batch):\\n            num_items_in_batch = num_items_in_batch.to(total_loss.device)\\n        loss = total_loss / num_items_in_batch\\n    else:\\n        loss = weighted_losses.mean()\\n    return loss\\n\\n\\ndef asft_loss_func(\\n    outputs,\\n    labels: torch.Tensor,\\n    ref_logits: torch.Tensor,\\n    asft_alpha: float = 0.1,\\n    ignore_index: int = -100,\\n) -> torch.Tensor:\\n    logits = outputs.get(\\\"logits\\\")\\n    if logits is None:\\n        return outputs.get(\\\"loss\\\", torch.tensor(0.0))\\n\\n    logits = logits.float()\\n\\n    # shift for causal LM\\n    shift_logits = logits[..., :-1, :].contiguous()\\n    shift_labels = labels[..., 1:].contiguous()\\n    shift_ref_logits = ref_logits[..., :-1, :].contiguous()\\n\\n    vocab_size = shift_logits.size(-1)\\n\\n    # flatten\\n    shift_logits = shift_logits.view(-1, vocab_size)\\n    shift_ref_logits = shift_ref_logits.view(-1, vocab_size)\\n    shift_labels = shift_labels.view(-1).to(shift_logits.device)\\n\\n    return _asft_cross_entropy(\\n        policy_logits=shift_logits,\\n        policy_labels=shift_labels,\\n        ref_logits=shift_ref_logits,\\n        asft_alpha=asft_alpha,\\n        ignore_index=ignore_index,\\n    )\\n\\n\\ndef _asft_cross_entropy(\\n    policy_logits: torch.Tensor,\\n    policy_labels: torch.Tensor,\\n    ref_logits: torch.Tensor,\\n    asft_alpha: float = 0.1,\\n    ignore_index: int = -100,\\n) -> torch.Tensor:\\n    dft_loss = _dft_cross_entropy(\\n        policy_logits,\\n        policy_labels,\\n        ignore_index=ignore_index,\\n    )\\n\\n    kl_loss = _kl_divergence(\\n        policy_logits,\\n        ref_logits,\\n        policy_labels,\\n        ignore_index=ignore_index,\\n    )\\n\\n    return dft_loss + asft_alpha * kl_loss\\n\\n\\ndef _kl_divergence(\\n    policy_logits: torch.Tensor,\\n    ref_logits: torch.Tensor,\\n    labels: torch.Tensor,\\n    ignore_index: int = -100,\\n) -> torch.Tensor:\\n    # log p(y|x)\\n    log_p = F.log_softmax(policy_logits, dim=-1)\\n\\n    # q(y|x)\\n    q = F.softmax(ref_logits, dim=-1)\\n\\n    # token-wise KL\\n    kl = F.kl_div(\\n        log_p,\\n        q,\\n        reduction=\\\"none\\\",\\n    ).sum(dim=-1)  # [N]\\n\\n    # mask padding tokens\\n    mask = (labels != ignore_index).float()\\n\\n    return (kl * mask).sum() / mask.sum()\\n\\n\\ndef eaft_loss_func(\\n    outputs: \\\"torch.Tensor\\\",\\n    labels: \\\"torch.Tensor\\\",\\n    num_items_in_batch: Optional[\\\"torch.Tensor\\\"] = None,\\n    alpha: float = 1.0,\\n) -> \\\"torch.Tensor\\\":\\n    logits = outputs.get(\\\"logits\\\")\\n    if logits is None:\\n        return outputs.get(\\\"loss\\\", torch.tensor(0.0))\\n\\n    logits = logits.float()\\n    vocab_size = logits.size(-1)\\n    labels = torch.nn.functional.pad(labels, (0, 1), value=-100)\\n    shift_labels = labels[..., 1:].contiguous()\\n    logits = logits.view(-1, vocab_size)\\n    shift_labels = shift_labels.view(-1)\\n    shift_labels = shift_labels.to(logits.device)\\n\\n    loss = _eaft_cross_entropy(logits, shift_labels, num_items_in_batch, alpha)\\n    return loss\\n\\n\\ndef _eaft_cross_entropy(\\n    source: \\\"torch.Tensor\\\",\\n    target: \\\"torch.Tensor\\\",\\n    num_items_in_batch: Optional[\\\"torch.Tensor\\\"] = None,\\n    alpha: float = 1.0,\\n    ignore_index: int = -100,\\n) -> \\\"torch.Tensor\\\":\\n    per_token_loss = torch.nn.functional.cross_entropy(source, target, ignore_index=ignore_index, reduction=\\\"none\\\")\\n    valid_mask = target != ignore_index\\n    if not valid_mask.any():\\n        return torch.tensor(0.0, device=source.device, dtype=source.dtype)\\n\\n    valid_losses = per_token_loss[valid_mask]\\n\\n    with torch.no_grad():\\n        source_detached = source[valid_mask].detach()\\n\\n        topk_val, _ = torch.topk(source_detached, k=20, dim=-1)\\n        logsumexp_topk = torch.logsumexp(topk_val, dim=-1, keepdim=True)\\n        log_probs_topk = topk_val - logsumexp_topk\\n        probs_topk = torch.exp(log_probs_topk)\\n        entropy_approx = -(probs_topk * log_probs_topk).sum(dim=-1)\\n\\n        entropy_term = entropy_approx / 3.0\\n        adaptive_weight = torch.pow(entropy_term, alpha)\\n\\n    weighted_losses = valid_losses * adaptive_weight\\n\\n    if num_items_in_batch is not None:\\n        total_loss = weighted_losses.sum()\\n        if torch.is_tensor(num_items_in_batch):\\n            num_items_in_batch = num_items_in_batch.to(total_loss.device)\\n        loss = total_loss / num_items_in_batch\\n    else:\\n        loss = weighted_losses.mean()\\n\\n    return loss\\n\\n\\ndef nested_detach(\\n    tensors: Union[\\\"torch.Tensor\\\", list[\\\"torch.Tensor\\\"], tuple[\\\"torch.Tensor\\\"], dict[str, \\\"torch.Tensor\\\"]],\\n    clone: bool = False,\\n):\\n    r\\\"\\\"\\\"Detach `tensors` (even if it's a nested list/tuple/dict of tensors).\\\"\\\"\\\"\\n    if isinstance(tensors, (list, tuple)):\\n        return type(tensors)(nested_detach(t, clone=clone) for t in tensors)\\n    elif isinstance(tensors, Mapping):\\n        return type(tensors)({k: nested_detach(t, clone=clone) for k, t in tensors.items()})\\n\\n    if isinstance(tensors, torch.Tensor):\\n        if clone:\\n            return tensors.detach().clone()\\n        else:\\n            return tensors.detach()\\n    else:\\n        return tensors\\n\\n\\ndef get_swanlab_callback(finetuning_args: \\\"FinetuningArguments\\\") -> \\\"TrainerCallback\\\":\\n    r\\\"\\\"\\\"Get the callback for logging to SwanLab.\\\"\\\"\\\"\\n    import swanlab  # type: ignore\\n    from swanlab.integration.transformers import SwanLabCallback  # type: ignore\\n\\n    if finetuning_args.swanlab_api_key is not None:\\n        swanlab.login(api_key=finetuning_args.swanlab_api_key)\\n\\n    if finetuning_args.swanlab_lark_webhook_url is not None:\\n        from swanlab.plugin.notification import LarkCallback  # type: ignore\\n\\n        lark_callback = LarkCallback(\\n            webhook_url=finetuning_args.swanlab_lark_webhook_url,\\n            secret=finetuning_args.swanlab_lark_secret,\\n        )\\n        swanlab.register_callbacks([lark_callback])\\n\\n    class SwanLabCallbackExtension(SwanLabCallback):\\n        def setup(self, args: \\\"TrainingArguments\\\", state: \\\"TrainerState\\\", model: \\\"PreTrainedModel\\\", **kwargs):\\n            if not state.is_world_process_zero:\\n                return\\n\\n            super().setup(args, state, model, **kwargs)\\n            try:\\n                if hasattr(self, \\\"_swanlab\\\"):\\n                    swanlab_public_config = self._swanlab.get_run().public.json()\\n                else:  # swanlab <= 0.4.9\\n                    swanlab_public_config = self._experiment.get_run().public.json()\\n            except Exception:\\n                swanlab_public_config = {}\\n\\n            with open(os.path.join(args.output_dir, SWANLAB_CONFIG), \\\"w\\\") as f:\\n                f.write(json.dumps(swanlab_public_config, indent=2))\\n\\n    swanlab_callback = SwanLabCallbackExtension(\\n        project=finetuning_args.swanlab_project,\\n        workspace=finetuning_args.swanlab_workspace,\\n        experiment_name=finetuning_args.swanlab_run_name,\\n        mode=finetuning_args.swanlab_mode,\\n        config={\\\"Framework\\\": \\\"\ud83e\udd99LlamaFactory\\\"},\\n        logdir=finetuning_args.swanlab_logdir,\\n        tags=[\\\"\ud83e\udd99LlamaFactory\\\"],\\n    )\\n    return swanlab_callback\\n\\n\\ndef get_placement_group(num_workers: int) -> tuple[\\\"PlacementGroup\\\", dict[str, int]]:\\n    r\\\"\\\"\\\"Get the Ray placement group for distributed training.\\\"\\\"\\\"\\n    bundle = {\\\"CPU\\\": 10}\\n    device_name = get_device_name().upper()\\n    if device_name != \\\"CPU\\\":\\n        bundle[device_name] = 1\\n    bundles = [bundle for _ in range(num_workers)]\\n    pg = placement_group(bundles, strategy=\\\"PACK\\\")\\n\\n    return pg, bundle\\n\\n\\ndef get_ray_remote_config_for_worker(\\n    placement_group: \\\"PlacementGroup\\\",\\n    bundle_idx: int,\\n    rank: int,\\n    world_size: int,\\n    master_addr: str,\\n    master_port: str,\\n    env: dict[str, str] = None,\\n) -> dict[str, Any]:\\n    r\\\"\\\"\\\"Get the remote config for a Ray worker.\\\"\\\"\\\"\\n    env_vars = {\\n        \\\"RANK\\\": str(rank),\\n        \\\"WORLD_SIZE\\\": str(world_size),\\n        \\\"MASTER_ADDR\\\": master_addr,\\n        \\\"MASTER_PORT\\\": master_port,\\n        \\\"TORCHELASTIC_USE_AGENT_STORE\\\": \\\"False\\\",\\n    }\\n    env.update(env_vars)\\n\\n    remote_config = {\\n        \\\"scheduling_strategy\\\": PlacementGroupSchedulingStrategy(\\n            placement_group=placement_group,\\n            placement_group_bundle_index=bundle_idx,\\n        ),\\n        \\\"runtime_env\\\": {\\\"env_vars\\\": env},\\n        \\\"num_cpus\\\": 10,\\n    }\\n\\n    device_name = get_device_name()\\n    if device_name == \\\"gpu\\\":\\n        remote_config[\\\"num_gpus\\\"] = 1\\n    elif device_name == \\\"npu\\\":\\n        remote_config[\\\"resources\\\"] = {\\\"NPU\\\": 1}\\n\\n    return remote_config\\n\\n\\ndef get_ray_head_node_ip() -> str:\\n    r\\\"\\\"\\\"Get the IP address of the Ray head node.\\\"\\\"\\\"\\n    head_ip = next(node[\\\"node_ip\\\"] for node in list_nodes() if node.get(\\\"is_head_node\\\", False))\\n    return head_ip\\n\\n\\ndef sort_placement_group_by_node_ip(placement_group: \\\"PlacementGroup\\\", master_addr: str = None) -> list[int]:\\n    r\\\"\\\"\\\"Sort the placement group bundles by their node IP addresses.\\\"\\\"\\\"\\n\\n    @ray.remote\\n    def _get_node_ip():\\n        return ray.util.get_node_ip_address().strip(\\\"[]\\\")\\n\\n    tasks = []\\n    for bundle_idx in range(placement_group.bundle_count):\\n        task = _get_node_ip.options(\\n            scheduling_strategy=PlacementGroupSchedulingStrategy(\\n                placement_group=placement_group,\\n                placement_group_bundle_index=bundle_idx,\\n            ),\\n        ).remote()\\n        tasks.append(task)\\n\\n    bundle_ips = ray.get(tasks)\\n    bundle_node_ip_list = list(enumerate(bundle_ips))\\n\\n    sorted_bundle_node_ip_list = sorted(bundle_node_ip_list, key=lambda x: x[1])\\n    sorted_bundle_indices = [item[0] for item in sorted_bundle_node_ip_list]\\n\\n    if master_addr is not None:\\n        preferred_indices = [idx for idx, ip in bundle_node_ip_list if ip == master_addr]\\n        if preferred_indices:\\n            remaining = [i for i in sorted_bundle_indices if i not in preferred_indices]\\n            sorted_bundle_indices = preferred_indices + remaining\\n\\n    return sorted_bundle_indices\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/train/tuner.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"192ba6c81096ac5fcd075d44ef9e79296558fc935cd941fc38c038432fe00711\",\"content\":\"# Copyright 2025 the KVCache.AI team, Approaching AI, and the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport os\\nimport shutil\\nfrom typing import TYPE_CHECKING, Any, Optional\\n\\nimport torch\\nimport torch.distributed as dist\\nfrom transformers import EarlyStoppingCallback, PreTrainedModel\\n\\nfrom ..data import get_template_and_fix_tokenizer\\nfrom ..extras import logging\\nfrom ..extras.constants import V_HEAD_SAFE_WEIGHTS_NAME, V_HEAD_WEIGHTS_NAME\\nfrom ..extras.misc import find_available_port, get_device_name, get_torch_device, infer_optim_dtype\\nfrom ..extras.packages import (\\n    is_hyper_parallel_available,\\n    is_mcore_adapter_available,\\n    is_megatron_bridge_available,\\n    is_ray_available,\\n    is_transformers_version_greater_than,\\n)\\nfrom ..hparams import RayArguments, get_infer_args, get_ray_args, get_train_args, read_args\\nfrom ..model import load_model, load_tokenizer\\nfrom .callbacks import (\\n    LogCallback,\\n    ModuleProfilerCallback,\\n    PissaConvertCallback,\\n    ReporterCallback,\\n    TorchProfilerCallback,\\n)\\nfrom .dpo import run_dpo\\nfrom .kto import run_kto\\nfrom .ppo import run_ppo\\nfrom .pt import run_pt\\nfrom .rm import run_rm\\nfrom .sft import run_sft\\nfrom .trainer_utils import (\\n    get_placement_group,\\n    get_ray_head_node_ip,\\n    get_ray_remote_config_for_worker,\\n    get_swanlab_callback,\\n    sort_placement_group_by_node_ip,\\n)\\n\\n\\nif is_ray_available():\\n    import ray\\n\\n\\nif TYPE_CHECKING:\\n    from transformers import TrainerCallback\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\ndef _training_function(config: dict[str, Any]) -> None:\\n    args = config.get(\\\"args\\\")\\n    callbacks: list[Any] = config.get(\\\"callbacks\\\")\\n    model_args, data_args, training_args, finetuning_args, generating_args = get_train_args(args)\\n\\n    callbacks.append(LogCallback())\\n    if finetuning_args.pissa_convert:\\n        callbacks.append(PissaConvertCallback())\\n\\n    if finetuning_args.use_swanlab:\\n        callbacks.append(get_swanlab_callback(finetuning_args))\\n\\n    if finetuning_args.early_stopping_steps is not None:\\n        callbacks.append(EarlyStoppingCallback(early_stopping_patience=finetuning_args.early_stopping_steps))\\n\\n    if getattr(training_args, \\\"enable_torch_profiler\\\", False):\\n        callbacks.append(TorchProfilerCallback(training_args))\\n\\n    if getattr(training_args, \\\"profile_modules\\\", None):\\n        callbacks.append(ModuleProfilerCallback(training_args.profile_modules))\\n\\n    callbacks.append(ReporterCallback(model_args, data_args, finetuning_args, generating_args))  # add to last\\n\\n    if finetuning_args.stage in [\\\"pt\\\", \\\"sft\\\"] and finetuning_args.use_hyper_parallel:\\n        if not is_hyper_parallel_available():\\n            raise ImportError(\\\"hyper_parallel is not installed. Please install it with `pip install hyper_parallel`.\\\")\\n        if finetuning_args.stage == \\\"pt\\\":\\n            from .hyper_parallel import run_pt as run_pt_hp\\n\\n            run_pt_hp(model_args, data_args, training_args, finetuning_args, callbacks)\\n        else:\\n            from .hyper_parallel import run_sft as run_sft_hp\\n\\n            run_sft_hp(model_args, data_args, training_args, finetuning_args, generating_args, callbacks)\\n\\n    elif finetuning_args.stage in [\\\"pt\\\", \\\"sft\\\"] and finetuning_args.use_megatron_bridge:\\n        if not is_megatron_bridge_available():\\n            raise ImportError(\\n                \\\"megatron-bridge is not installed. \\\"\\n                \\\"Please install it with `pip install --no-build-isolation megatron-bridge`.\\\"\\n            )\\n        mb_args = finetuning_args.megatron_bridge_args\\n        if mb_args is None:\\n            raise ValueError(\\\"Megatron Bridge arguments are missing. Please set USE_MEGATRON_BRIDGE=1.\\\")\\n        if finetuning_args.stage == \\\"pt\\\":\\n            from .megatron_bridge import run_pt as run_pt_mb\\n\\n            run_pt_mb(model_args, data_args, training_args, finetuning_args, mb_args, callbacks)\\n        else:\\n            from .megatron_bridge import run_sft as run_sft_mb\\n\\n            run_sft_mb(model_args, data_args, training_args, finetuning_args, mb_args, callbacks)\\n\\n    elif finetuning_args.stage in [\\\"pt\\\", \\\"sft\\\", \\\"dpo\\\"] and finetuning_args.use_mca:\\n        if not is_mcore_adapter_available():\\n            raise ImportError(\\\"mcore_adapter is not installed. Please install it with `pip install mcore-adapter`.\\\")\\n        if finetuning_args.stage == \\\"pt\\\":\\n            from .mca import run_pt as run_pt_mca\\n\\n            run_pt_mca(model_args, data_args, training_args, finetuning_args, callbacks)\\n        elif finetuning_args.stage == \\\"sft\\\":\\n            from .mca import run_sft as run_sft_mca\\n\\n            run_sft_mca(model_args, data_args, training_args, finetuning_args, callbacks)\\n        elif finetuning_args.stage == \\\"dpo\\\":\\n            from .mca import run_dpo as run_dpo_mca\\n\\n            run_dpo_mca(model_args, data_args, training_args, finetuning_args, callbacks)\\n\\n    elif finetuning_args.stage == \\\"pt\\\":\\n        run_pt(model_args, data_args, training_args, finetuning_args, callbacks)\\n    elif finetuning_args.stage == \\\"sft\\\":\\n        run_sft(model_args, data_args, training_args, finetuning_args, generating_args, callbacks)\\n    elif finetuning_args.stage == \\\"rm\\\":\\n        run_rm(model_args, data_args, training_args, finetuning_args, callbacks)\\n    elif finetuning_args.stage == \\\"ppo\\\":\\n        run_ppo(model_args, data_args, training_args, finetuning_args, generating_args, callbacks)\\n    elif finetuning_args.stage == \\\"dpo\\\":\\n        run_dpo(model_args, data_args, training_args, finetuning_args, callbacks)\\n    elif finetuning_args.stage == \\\"kto\\\":\\n        run_kto(model_args, data_args, training_args, finetuning_args, callbacks)\\n    else:\\n        raise ValueError(f\\\"Unknown task: {finetuning_args.stage}.\\\")\\n\\n    if is_ray_available() and ray.is_initialized():\\n        return  # if ray is initialized it will destroy the process group on return\\n\\n    try:\\n        if dist.is_initialized():\\n            dist.destroy_process_group()\\n    except Exception as e:\\n        logger.warning(f\\\"Failed to destroy process group: {e}.\\\")\\n\\n\\ndef run_exp(args: Optional[dict[str, Any]] = None, callbacks: Optional[list[\\\"TrainerCallback\\\"]] = None) -> None:\\n    args = read_args(args)\\n    if \\\"-h\\\" in args or \\\"--help\\\" in args:\\n        get_train_args(args)\\n\\n    ray_args = get_ray_args(args)\\n    callbacks = callbacks or []\\n    if ray_args.use_ray:\\n        _ray_training_function(ray_args, config={\\\"args\\\": args, \\\"callbacks\\\": callbacks})\\n    else:\\n        _training_function(config={\\\"args\\\": args, \\\"callbacks\\\": callbacks})\\n\\n\\ndef export_model(args: Optional[dict[str, Any]] = None) -> None:\\n    model_args, data_args, finetuning_args, _ = get_infer_args(args)\\n\\n    if model_args.export_dir is None:\\n        raise ValueError(\\\"Please specify `export_dir` to save model.\\\")\\n\\n    if model_args.adapter_name_or_path is not None and model_args.export_quantization_bit is not None:\\n        raise ValueError(\\\"Please merge adapters before quantizing the model.\\\")\\n\\n    tokenizer_module = load_tokenizer(model_args)\\n    tokenizer = tokenizer_module[\\\"tokenizer\\\"]\\n    processor = tokenizer_module[\\\"processor\\\"]\\n    template = get_template_and_fix_tokenizer(tokenizer, data_args)\\n    model = load_model(tokenizer, model_args, finetuning_args)  # must after fixing tokenizer to resize vocab\\n\\n    if getattr(model, \\\"quantization_method\\\", None) is not None and model_args.adapter_name_or_path is not None:\\n        raise ValueError(\\\"Cannot merge adapters to a quantized model.\\\")\\n\\n    if not isinstance(model, PreTrainedModel):\\n        raise ValueError(\\\"The model is not a `PreTrainedModel`, export aborted.\\\")\\n\\n    if getattr(model, \\\"quantization_method\\\", None) is not None:  # quantized model adopts float16 type\\n        setattr(model.config, \\\"torch_dtype\\\", torch.float16)\\n    else:\\n        if model_args.infer_dtype == \\\"auto\\\":\\n            output_dtype = getattr(model.config, \\\"torch_dtype\\\", torch.float32)\\n            if output_dtype == torch.float32:  # if infer_dtype is auto, try using half precision first\\n                output_dtype = infer_optim_dtype(torch.bfloat16)\\n        else:\\n            output_dtype = getattr(torch, model_args.infer_dtype)\\n\\n        setattr(model.config, \\\"torch_dtype\\\", output_dtype)\\n        model = model.to(output_dtype)\\n        logger.info_rank0(f\\\"Convert model dtype to: {output_dtype}.\\\")\\n\\n    # Prepare save arguments (safe_serialization removed in transformers v5.0.0)\\n    save_kwargs = {\\n        \\\"save_directory\\\": model_args.export_dir,\\n        \\\"max_shard_size\\\": f\\\"{model_args.export_size}GB\\\",\\n    }\\n    if not is_transformers_version_greater_than(\\\"5.0.0\\\"):\\n        save_kwargs[\\\"safe_serialization\\\"] = not model_args.export_legacy_format\\n\\n    try:\\n        model.save_pretrained(**save_kwargs)\\n    except NotImplementedError as err:\\n        raise RuntimeError(\\n            \\\"Failed to export model: weight conversion reversal is not supported for this model architecture \\\"\\n            \\\"(NotImplementedError in transformers.core_model_loading.reverse_op). \\\"\\n            \\\"This is a known issue with transformers>=5.0 for certain model types (e.g. Mistral/Ministral). \\\"\\n            \\\"Workarounds: (1) use transformers<5.0, or (2) report the issue to the transformers repository.\\\"\\n        ) from err\\n\\n    if model_args.export_hub_model_id is not None:\\n        # Prepare push arguments (safe_serialization removed in transformers v5.0.0)\\n        push_kwargs = {\\n            \\\"max_shard_size\\\": f\\\"{model_args.export_size}GB\\\",\\n        }\\n        if not is_transformers_version_greater_than(\\\"5.0.0\\\"):\\n            push_kwargs[\\\"safe_serialization\\\"] = not model_args.export_legacy_format\\n\\n        model.push_to_hub(\\n            model_args.export_hub_model_id,\\n            token=model_args.hf_hub_token,\\n            **push_kwargs,\\n        )\\n\\n    if finetuning_args.stage == \\\"rm\\\":\\n        if model_args.adapter_name_or_path is not None:\\n            vhead_path = model_args.adapter_name_or_path[-1]\\n        else:\\n            vhead_path = model_args.model_name_or_path\\n\\n        if os.path.exists(os.path.join(vhead_path, V_HEAD_SAFE_WEIGHTS_NAME)):\\n            shutil.copy(\\n                os.path.join(vhead_path, V_HEAD_SAFE_WEIGHTS_NAME),\\n                os.path.join(model_args.export_dir, V_HEAD_SAFE_WEIGHTS_NAME),\\n            )\\n            logger.info_rank0(f\\\"Copied valuehead to {model_args.export_dir}.\\\")\\n        elif os.path.exists(os.path.join(vhead_path, V_HEAD_WEIGHTS_NAME)):\\n            shutil.copy(\\n                os.path.join(vhead_path, V_HEAD_WEIGHTS_NAME),\\n                os.path.join(model_args.export_dir, V_HEAD_WEIGHTS_NAME),\\n            )\\n            logger.info_rank0(f\\\"Copied valuehead to {model_args.export_dir}.\\\")\\n\\n    try:\\n        tokenizer.padding_side = \\\"left\\\"  # restore padding side\\n        tokenizer.init_kwargs[\\\"padding_side\\\"] = \\\"left\\\"\\n        tokenizer.save_pretrained(model_args.export_dir)\\n        if model_args.export_hub_model_id is not None:\\n            tokenizer.push_to_hub(model_args.export_hub_model_id, token=model_args.hf_hub_token)\\n\\n        if processor is not None:\\n            processor.save_pretrained(model_args.export_dir)\\n            if model_args.export_hub_model_id is not None:\\n                processor.push_to_hub(model_args.export_hub_model_id, token=model_args.hf_hub_token)\\n\\n    except Exception as e:\\n        logger.warning_rank0(f\\\"Cannot save tokenizer, please copy the files manually: {e}.\\\")\\n\\n    ollama_modelfile = os.path.join(model_args.export_dir, \\\"Modelfile\\\")\\n    with open(ollama_modelfile, \\\"w\\\", encoding=\\\"utf-8\\\") as f:\\n        f.write(template.get_ollama_modelfile(tokenizer))\\n        logger.info_rank0(f\\\"Ollama modelfile saved in {ollama_modelfile}\\\")\\n\\n\\nclass Worker:\\n    def __init__(self):\\n        self._setup_env_visible_devices()\\n\\n        local_rank = os.environ.get(\\\"LOCAL_RANK\\\", \\\"0\\\")\\n        get_torch_device().set_device(int(local_rank))\\n\\n    def _setup_env_visible_devices(self) -> None:\\n        RAY_NOSET_VISIBLE_DEVICES_LIST = [\\n            \\\"RAY_EXPERIMENTAL_NOSET_CUDA_VISIBLE_DEVICES\\\",\\n            \\\"RAY_EXPERIMENTAL_NOSET_ASCEND_RT_VISIBLE_DEVICES\\\",\\n        ]\\n        is_ray_noset_visible_devices = any(os.environ.get(env_var, None) for env_var in RAY_NOSET_VISIBLE_DEVICES_LIST)\\n        if is_ray_noset_visible_devices:\\n            device_name = get_device_name().upper()\\n            local_rank = ray.get_runtime_context().get_accelerator_ids()[device_name][0]\\n            os.environ[\\\"LOCAL_RANK\\\"] = local_rank\\n        else:\\n            os.environ[\\\"LOCAL_RANK\\\"] = \\\"0\\\"\\n\\n    def _training_function(self, config: dict[str, Any]) -> None:\\n        _training_function(config)\\n\\n\\ndef _ray_training_function(ray_args: \\\"RayArguments\\\", config: dict[str, Any]) -> None:\\n    num_workers = ray_args.ray_num_workers\\n    master_addr = ray_args.master_addr\\n    master_port = ray_args.master_port\\n    logger.info(f\\\"Using ray.remote mode with {num_workers} workers for distributed training.\\\")\\n\\n    # initialize ray\\n    if not ray.is_initialized():\\n        if ray_args.ray_init_kwargs is not None:\\n            ray.init(**ray_args.ray_init_kwargs)\\n        else:\\n            ray.init()\\n\\n    # verify resources\\n    device_name = get_device_name().upper()\\n    total_devices = int(ray.cluster_resources().get(device_name, 0))\\n    if num_workers > total_devices:\\n        raise ValueError(\\n            f\\\"The number of devices in the Ray cluster ({total_devices}) should be greater than num_workers ({num_workers}).\\\"\\n        )\\n\\n    # verify master_addr\\n    if master_addr is None:\\n        master_addr = get_ray_head_node_ip()\\n        logger.info(f\\\"`master_addr` is not specified, using head node ip: {master_addr}.\\\")\\n    else:\\n        nodes = [node[\\\"NodeManagerAddress\\\"] for node in ray.nodes() if node[\\\"Alive\\\"]]\\n        if master_addr not in nodes:\\n            raise ValueError(f\\\"The `master_addr` ({master_addr}) is not in Ray cluster or not alive \\\")\\n\\n    # create placementgroup for resource management\\n    pg, bundle = get_placement_group(total_devices)\\n    ray.get(pg.ready())\\n    logger.info(f\\\"Create placement group with {num_workers} bundles: {bundle}\\\")\\n\\n    # get sorted_bundle_indices\\n    sorted_bundle_indices = sort_placement_group_by_node_ip(pg, master_addr)\\n\\n    # get master port\\n    if master_port is None:\\n        master_port = find_available_port()\\n        logger.info(f\\\"`master_port` is not specified, using available port: {master_port}.\\\")\\n    master_port = str(master_port)\\n\\n    # backing up environment variables\\n    current_env = dict(os.environ.items())\\n\\n    # launch workers\\n    RayWorker = ray.remote(Worker)\\n    workers = []\\n    for rank in range(num_workers):\\n        remote_config = get_ray_remote_config_for_worker(\\n            placement_group=pg,\\n            bundle_idx=sorted_bundle_indices[rank],\\n            rank=rank,\\n            world_size=num_workers,\\n            master_addr=master_addr,\\n            master_port=master_port,\\n            env=current_env,\\n        )\\n        worker = RayWorker.options(**remote_config).remote()\\n        workers.append(worker)\\n\\n    ray.get([worker._training_function.remote(config=config) for worker in workers])\\n    ray.shutdown()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/accelerator/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/accelerator/helper.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c01cfeecab553878f4530381f8c792eda858efe7e2dd1e565b75a58ba102e464\",\"content\":\"# Copyright 2025 Bytedance Ltd. and the LlamaFactory team.\\n#\\n# This code is inspired by the Bytedance's VeOmni library.\\n# https://github.com/ByteDance-Seed/VeOmni/blob/v0.1.4/veomni/utils/dist_utils.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"Utility functions used by the distributed interface.\\n\\nIncluding:\\n- Environment info (rank, world_size, local_rank, etc.)\\n- Accelerator info (device type, device count, etc.)\\n- Collective communication operations (all_gather, all_reduce, broadcast)\\n- Synchronize processes and ensure main-process-first execution order\\n\\\"\\\"\\\"\\n\\nimport os\\nfrom collections.abc import Callable\\nfrom contextlib import contextmanager\\nfrom enum import StrEnum, unique\\nfrom functools import lru_cache, wraps\\nfrom typing import Optional\\n\\nimport numpy as np\\nimport torch\\nimport torch.distributed as dist\\n\\nfrom ..utils.types import ProcessGroup, Tensor, TensorLike\\n\\n\\n@unique\\nclass DeviceType(StrEnum):\\n    CPU = \\\"cpu\\\"\\n    CUDA = \\\"cuda\\\"\\n    META = \\\"meta\\\"\\n    MPS = \\\"mps\\\"\\n    NPU = \\\"npu\\\"\\n    XPU = \\\"xpu\\\"\\n\\n\\n@unique\\nclass ReduceOp(StrEnum):\\n    SUM = \\\"sum\\\"\\n    MEAN = \\\"mean\\\"\\n    MAX = \\\"max\\\"\\n    MIN = \\\"min\\\"\\n\\n\\ndef requires_accelerator(fn):\\n    \\\"\\\"\\\"Decorator to check if torch.accelerator is available.\\n\\n    Note: this api requires torch>=2.7.0, otherwise it will raise an AttributeError or RuntimeError\\n    \\\"\\\"\\\"\\n\\n    @wraps(fn)\\n    def wrapper(*args, **kwargs):\\n        if not hasattr(torch, \\\"accelerator\\\"):\\n            raise RuntimeError(\\\"torch.accelerator is not available, please upgrade torch to 2.7.0 or higher.\\\")\\n\\n        return fn(*args, **kwargs)\\n\\n    return wrapper\\n\\n\\ndef is_distributed() -> bool:\\n    \\\"\\\"\\\"Check if distributed environment is available.\\\"\\\"\\\"\\n    return os.getenv(\\\"RANK\\\") is not None\\n\\n\\ndef get_rank() -> int:\\n    \\\"\\\"\\\"Get rank.\\\"\\\"\\\"\\n    return int(os.getenv(\\\"RANK\\\", \\\"0\\\"))\\n\\n\\ndef get_world_size() -> int:\\n    \\\"\\\"\\\"Get world size.\\\"\\\"\\\"\\n    return int(os.getenv(\\\"WORLD_SIZE\\\", \\\"1\\\"))\\n\\n\\ndef get_local_rank() -> int:\\n    \\\"\\\"\\\"Get local rank.\\\"\\\"\\\"\\n    return int(os.getenv(\\\"LOCAL_RANK\\\", \\\"0\\\"))\\n\\n\\ndef get_local_world_size() -> int:\\n    \\\"\\\"\\\"Get local world size.\\\"\\\"\\\"\\n    return int(os.getenv(\\\"LOCAL_WORLD_SIZE\\\", \\\"1\\\"))\\n\\n\\n@lru_cache\\n@requires_accelerator\\ndef get_current_accelerator(check_available: bool = True) -> torch.device:\\n    \\\"\\\"\\\"Get current accelerator.\\\"\\\"\\\"\\n    accelerator = torch.accelerator.current_accelerator(check_available=check_available)\\n    return accelerator or torch.device(DeviceType.CPU.value)\\n\\n\\n@lru_cache\\n@requires_accelerator\\ndef get_device_count() -> int:\\n    \\\"\\\"\\\"Get the number of available devices.\\\"\\\"\\\"\\n    return torch.accelerator.device_count()\\n\\n\\n@requires_accelerator\\ndef synchronize() -> None:\\n    \\\"\\\"\\\"Synchronize all processes.\\\"\\\"\\\"\\n    torch.accelerator.synchronize()\\n\\n\\n@requires_accelerator\\ndef set_device_index() -> None:\\n    \\\"\\\"\\\"Set current accelerator index to local rank.\\\"\\\"\\\"\\n    if get_current_accelerator().type != DeviceType.CPU:\\n        torch.accelerator.set_device_index(get_local_rank())\\n\\n\\n@requires_accelerator\\ndef get_current_device() -> torch.device:\\n    \\\"\\\"\\\"Get current accelerator device.\\\"\\\"\\\"\\n    if get_current_accelerator().type == DeviceType.CPU:\\n        return torch.device(DeviceType.CPU.value)\\n    else:\\n        return torch.device(type=get_current_accelerator().type, index=torch.accelerator.current_device_index())\\n\\n\\ndef is_torch_cuda_available():\\n    \\\"\\\"\\\"Check if CUDA is available.\\\"\\\"\\\"\\n    return get_current_accelerator().type == DeviceType.CUDA\\n\\n\\ndef is_torch_mps_available():\\n    \\\"\\\"\\\"Check if MPS is available.\\\"\\\"\\\"\\n    return get_current_accelerator().type == DeviceType.MPS\\n\\n\\ndef is_torch_npu_available():\\n    \\\"\\\"\\\"Check if NPU is available.\\\"\\\"\\\"\\n    return get_current_accelerator().type == DeviceType.NPU\\n\\n\\ndef is_torch_xpu_available():\\n    \\\"\\\"\\\"Check if XPU is available.\\\"\\\"\\\"\\n    return get_current_accelerator().type == DeviceType.XPU\\n\\n\\ndef operate_tensorlike(fn: Callable[[...], Tensor], data: TensorLike, **kwargs) -> TensorLike:\\n    \\\"\\\"\\\"Operate tensorlike data on current accelerator.\\\"\\\"\\\"\\n    device = get_current_accelerator()\\n    is_tensor = isinstance(data, torch.Tensor)\\n    is_ndarray = isinstance(data, np.ndarray)\\n\\n    if is_tensor:\\n        orig_device = data.device\\n        data = data.to(device=device)\\n    elif is_ndarray:\\n        data = torch.from_numpy(data).to(device=device, dtype=torch.float)\\n    else:\\n        data = torch.tensor(data, dtype=torch.float, device=device)\\n\\n    result = fn(data, **kwargs)\\n\\n    if is_tensor:\\n        return result.to(orig_device)\\n    elif is_ndarray:\\n        return result.cpu().numpy()\\n    elif result.numel() == 1:\\n        return result.item()\\n    else:\\n        return result.tolist()\\n\\n\\ndef get_process_group_backend() -> str:\\n    \\\"\\\"\\\"Get backend for init process group.\\\"\\\"\\\"\\n    if get_current_accelerator().type == DeviceType.NPU:\\n        return \\\"hccl\\\"\\n    elif get_current_accelerator().type == DeviceType.CUDA:\\n        return \\\"nccl\\\"\\n    else:\\n        return \\\"gloo\\\"\\n\\n\\ndef all_gather(tensor: Tensor, group: Optional[ProcessGroup] = None) -> Tensor:\\n    \\\"\\\"\\\"Gathers the tensor from all ranks and stacks them at the first dim.\\\"\\\"\\\"\\n    world_size = get_world_size()\\n    output_tensor = torch.empty(world_size * tensor.numel(), dtype=tensor.dtype, device=tensor.device)\\n    dist.all_gather_into_tensor(output_tensor, tensor, group=group)\\n    return output_tensor.view(-1, *tensor.size())\\n\\n\\ndef all_reduce(tensor: Tensor, op: ReduceOp = ReduceOp.MEAN, group: Optional[ProcessGroup] = None) -> Tensor:\\n    \\\"\\\"\\\"Performs all reduce in the given process group.\\\"\\\"\\\"\\n    reduce_ops = {\\n        ReduceOp.MEAN: dist.ReduceOp.SUM,\\n        ReduceOp.SUM: dist.ReduceOp.SUM,\\n        ReduceOp.MAX: dist.ReduceOp.MAX,\\n        ReduceOp.MIN: dist.ReduceOp.MIN,\\n    }\\n    dist.all_reduce(tensor, op=reduce_ops[op], group=group)\\n    if op == ReduceOp.MEAN:  # ReduceOp.AVG is not supported by the NPU backend\\n        tensor /= dist.get_world_size(group=group)\\n\\n    return tensor\\n\\n\\ndef broadcast(tensor: Tensor, src: int = 0, group: Optional[ProcessGroup] = None) -> Tensor:\\n    \\\"\\\"\\\"Broadcasts the tensor from the src process to all other processes.\\\"\\\"\\\"\\n    dist.broadcast(tensor, src=src, group=group)\\n    return tensor\\n\\n\\n@contextmanager\\ndef main_process_first(local_only: bool = True) -> None:\\n    \\\"\\\"\\\"A context manager for torch distributed environment to do something on the main process firstly.\\\"\\\"\\\"\\n    if get_world_size() > 1:\\n        is_main_process = get_local_rank() == 0 if local_only else get_rank() == 0\\n        try:\\n            if not is_main_process:\\n                dist.barrier()\\n            yield\\n        finally:\\n            if is_main_process:\\n                dist.barrier()\\n    else:\\n        yield\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/accelerator/interface.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"83acbfa9d0cfdc209cb75e93f40c7fd504ec805f0a94e077ca5599b169ba6d7e\",\"content\":\"# Copyright 2025 Bytedance Ltd. and the LlamaFactory team.\\n#\\n# This code is inspired by the Bytedance's VeOmni library.\\n# https://github.com/ByteDance-Seed/VeOmni/blob/v0.1.4/veomni/distributed/parallel_state.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"A unified interface for model parallelism and data parallelism.\\n\\nSupports model parallelism types:\\n- mp_replicate: Replicate model across multiple devices.\\n- mp_shard: Shard model across multiple devices.\\n\\nAnd data parallelism types:\\n- dp: Data parallelism.\\n- cp: Context parallelism.\\n\\\"\\\"\\\"\\n\\nfrom dataclasses import dataclass\\nfrom datetime import timedelta\\nfrom enum import StrEnum\\nfrom typing import TYPE_CHECKING, Any, Optional\\n\\nfrom torch.distributed import barrier, destroy_process_group, init_process_group\\nfrom torch.distributed.device_mesh import DeviceMesh, init_device_mesh\\n\\nfrom ..utils import logging\\nfrom ..utils.types import ProcessGroup, TensorLike\\nfrom . import helper\\n\\n\\nif TYPE_CHECKING:\\n    from ..config.training_args import TrainingArguments\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\nclass Dim(StrEnum):\\n    \\\"\\\"\\\"Dimension names.\\\"\\\"\\\"\\n\\n    MP_REPLICATE = \\\"mp_replicate\\\"\\n    MP_SHARD = \\\"mp_shard\\\"\\n    DP = \\\"dp\\\"\\n    CP = \\\"cp\\\"\\n\\n\\n@dataclass\\nclass DistributedStrategy:\\n    \\\"\\\"\\\"Distributed strategy.\\\"\\\"\\\"\\n\\n    mp_replicate_size: int = 1\\n    \\\"\\\"\\\"Model parallel replicate size, default to 1.\\\"\\\"\\\"\\n    mp_shard_size: int | None = None\\n    \\\"\\\"\\\"Model parallel shard size, default to world_size // mp_replicate_size.\\\"\\\"\\\"\\n    dp_size: int | None = None\\n    \\\"\\\"\\\"Data parallel size, default to world_size // cp_size.\\\"\\\"\\\"\\n    cp_size: int = 1\\n    \\\"\\\"\\\"Context parallel size, default to 1.\\\"\\\"\\\"\\n\\n    def __post_init__(self) -> None:\\n        if not helper.is_distributed():\\n            self.mp_shard_size = 1\\n        elif self.mp_shard_size is None:\\n            if helper.get_world_size() % self.mp_replicate_size != 0:\\n                raise ValueError(\\n                    f\\\"world_size ({helper.get_world_size()}) must be divisible by \\\"\\n                    f\\\"mp_replicate_size ({self.mp_replicate_size}).\\\"\\n                )\\n            self.mp_shard_size = helper.get_world_size() // self.mp_replicate_size\\n        elif self.mp_replicate_size * self.mp_shard_size != helper.get_world_size():\\n            raise ValueError(\\n                f\\\"mp_replicate_size * mp_shard_size must equal to world_size, \\\"\\n                f\\\"got {self.mp_replicate_size} * {self.mp_shard_size} != {helper.get_world_size()}.\\\"\\n            )\\n\\n        if not helper.is_distributed():\\n            self.dp_size = 1\\n        elif self.dp_size is None:\\n            if helper.get_world_size() % self.cp_size != 0:\\n                raise ValueError(\\n                    f\\\"world_size ({helper.get_world_size()}) must be divisible by cp_size ({self.cp_size}).\\\"\\n                )\\n            self.dp_size = helper.get_world_size() // self.cp_size\\n        elif self.dp_size * self.cp_size != helper.get_world_size():\\n            raise ValueError(\\n                f\\\"dp_size * cp_size must equal to world_size, \\\"\\n                f\\\"got {self.dp_size} * {self.cp_size} != {helper.get_world_size()}.\\\"\\n            )\\n\\n    @property\\n    def model_mesh_shape(self) -> tuple[int, int]:\\n        \\\"\\\"\\\"Model parallel mesh shape.\\\"\\\"\\\"\\n        return (self.mp_replicate_size, self.mp_shard_size)\\n\\n    @property\\n    def model_mesh_dim_names(self) -> tuple[str, str]:\\n        \\\"\\\"\\\"Model parallel mesh dimension names.\\\"\\\"\\\"\\n        return (Dim.MP_REPLICATE.value, Dim.MP_SHARD.value)\\n\\n    @property\\n    def data_mesh_shape(self) -> tuple[int, int]:\\n        \\\"\\\"\\\"Data parallel mesh shape.\\\"\\\"\\\"\\n        return (self.dp_size, self.cp_size)\\n\\n    @property\\n    def data_mesh_dim_names(self) -> tuple[str, str]:\\n        \\\"\\\"\\\"Data parallel mesh dimension names.\\\"\\\"\\\"\\n        return (Dim.DP.value, Dim.CP.value)\\n\\n\\nclass DistributedInterface:\\n    \\\"\\\"\\\"Distributed interface.\\\"\\\"\\\"\\n\\n    _instance: Optional[\\\"DistributedInterface\\\"] = None\\n    _initialized: bool = False\\n\\n    def __new__(cls, *args: Any, **kwargs: Any) -> \\\"DistributedInterface\\\":\\n        \\\"\\\"\\\"Singleton pattern.\\\"\\\"\\\"\\n        if cls._instance is None:\\n            cls._instance = super().__new__(cls)\\n\\n        return cls._instance\\n\\n    def __init__(\\n        self,\\n        training_args: \\\"TrainingArguments | None\\\" = None,\\n    ) -> None:\\n        if self._initialized:\\n            return\\n\\n        helper.set_device_index()\\n        self._is_distributed = helper.is_distributed()\\n        self._rank = helper.get_rank()\\n        self._world_size = helper.get_world_size()\\n        self._local_rank = helper.get_local_rank()\\n        self._local_world_size = helper.get_local_world_size()\\n        self.current_device = helper.get_current_device()\\n        self.device_count = helper.get_device_count()\\n\\n        if training_args is None:\\n            self.strategy = DistributedStrategy()\\n            timeout = 18000\\n        else:\\n            self.strategy = DistributedStrategy(\\n                mp_replicate_size=training_args.mp_replicate_size,\\n                mp_shard_size=training_args.mp_shard_size,\\n                dp_size=training_args.dp_size,\\n                cp_size=training_args.cp_size,\\n            )\\n            timeout = training_args.dist_timeout\\n\\n        if self._is_distributed:\\n            init_process_group(timeout=timedelta(seconds=timeout), backend=helper.get_process_group_backend())\\n            self.model_device_mesh = init_device_mesh(\\n                device_type=self.current_device.type,\\n                mesh_shape=self.strategy.model_mesh_shape,\\n                mesh_dim_names=self.strategy.model_mesh_dim_names,\\n            )\\n            self.data_device_mesh = init_device_mesh(\\n                device_type=self.current_device.type,\\n                mesh_shape=self.strategy.data_mesh_shape,\\n                mesh_dim_names=self.strategy.data_mesh_dim_names,\\n            )\\n        else:\\n            self.model_device_mesh = None\\n            self.data_device_mesh = None\\n\\n        self._initialized = True\\n        logger.info_rank0(f\\\"DistributedInterface initialized: {self}.\\\")\\n\\n    def __str__(self) -> str:\\n        return (\\n            f\\\"DistributedInterface(strategy={self.strategy}), is_distributed={self._is_distributed}, \\\"\\n            f\\\"current_device={self.current_device}, rank={self._rank}, world_size={self._world_size}, \\\"\\n            f\\\"model_device_mesh={self.model_device_mesh}, data_device_mesh={self.data_device_mesh}\\\"\\n        )\\n\\n    def get_device_mesh(self, dim: Dim | None = None) -> DeviceMesh | None:\\n        \\\"\\\"\\\"Get device mesh for specified dimension.\\\"\\\"\\\"\\n        if dim is None:\\n            raise ValueError(\\\"dim must be specified.\\\")\\n        elif not self._is_distributed:\\n            return None\\n        elif dim in self.strategy.data_mesh_dim_names:\\n            return self.data_device_mesh[dim.value]\\n        else:\\n            return self.model_device_mesh[dim.value]\\n\\n    def get_group(self, dim: Dim | None = None) -> Optional[ProcessGroup]:\\n        \\\"\\\"\\\"Get process group for specified dimension.\\\"\\\"\\\"\\n        if not self._is_distributed or dim is None:\\n            return None\\n        else:\\n            return self.get_device_mesh(dim).get_group()\\n\\n    def get_rank(self, dim: Dim | None = None) -> int:\\n        \\\"\\\"\\\"Get parallel rank for specified dimension.\\\"\\\"\\\"\\n        if not self._is_distributed:\\n            return 0\\n        elif dim is None:\\n            return self._rank\\n        else:\\n            return self.get_device_mesh(dim).get_local_rank()\\n\\n    def get_world_size(self, dim: Dim | None = None) -> int:\\n        \\\"\\\"\\\"Get parallel size for specified dimension.\\\"\\\"\\\"\\n        if not self._is_distributed:\\n            return 1\\n        elif dim is None:\\n            return self._world_size\\n        else:\\n            return self.get_device_mesh(dim).size()\\n\\n    def get_local_rank(self) -> int:\\n        \\\"\\\"\\\"Get parallel local rank.\\\"\\\"\\\"\\n        return self._local_rank\\n\\n    def get_local_world_size(self) -> int:\\n        \\\"\\\"\\\"Get parallel local world size.\\\"\\\"\\\"\\n        return self._local_world_size\\n\\n    def all_gather(self, data: TensorLike, dim: Dim | None = Dim.DP) -> TensorLike:\\n        \\\"\\\"\\\"Gather tensor across specified parallel group.\\\"\\\"\\\"\\n        if self._is_distributed:\\n            return helper.operate_tensorlike(helper.all_gather, data, group=self.get_group(dim))\\n        else:\\n            return data\\n\\n    def all_reduce(\\n        self, data: TensorLike, op: helper.ReduceOp = helper.ReduceOp.MEAN, dim: Dim | None = Dim.DP\\n    ) -> TensorLike:\\n        \\\"\\\"\\\"Reduce tensor across specified parallel group.\\\"\\\"\\\"\\n        if self._is_distributed:\\n            return helper.operate_tensorlike(helper.all_reduce, data, op=op, group=self.get_group(dim))\\n        else:\\n            return data\\n\\n    def broadcast(self, data: TensorLike, src: int = 0, dim: Dim | None = Dim.DP) -> TensorLike:\\n        \\\"\\\"\\\"Broadcast tensor across specified parallel group.\\\"\\\"\\\"\\n        if self._is_distributed:\\n            return helper.operate_tensorlike(helper.broadcast, data, src=src, group=self.get_group(dim))\\n        else:\\n            return data\\n\\n    def sync(self) -> None:\\n        \\\"\\\"\\\"Synchronize all processes.\\\"\\\"\\\"\\n        if self._is_distributed:\\n            helper.synchronize()\\n\\n    def barrier(self) -> None:\\n        \\\"\\\"\\\"Barrier all processes.\\\"\\\"\\\"\\n        if self._is_distributed:\\n            barrier()\\n\\n    def destroy(self) -> None:\\n        \\\"\\\"\\\"Destroy all processes.\\\"\\\"\\\"\\n        if self._is_distributed:\\n            destroy_process_group()\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    \\\"\\\"\\\"\\n    python -m llamafactory.v1.accelerator.interface\\n    \\\"\\\"\\\"\\n    print(DistributedInterface())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/accelerator/profiler.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/config/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c12c0bea8a5400eaf9fcccaed7dd068d066e8d4469ff8ab3a194b1c5b71492fe\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom ..utils.types import AttentionFunction\\nfrom .arg_parser import InputArgument, get_args\\nfrom .arg_utils import BatchingStrategy, ModelClass, SampleBackend\\nfrom .data_args import DataArguments\\nfrom .model_args import ModelArguments\\nfrom .sample_args import SampleArguments\\nfrom .training_args import TrainingArguments\\n\\n\\n__all__ = [\\n    \\\"AttentionFunction\\\",\\n    \\\"BatchingStrategy\\\",\\n    \\\"DataArguments\\\",\\n    \\\"InputArgument\\\",\\n    \\\"ModelArguments\\\",\\n    \\\"ModelClass\\\",\\n    \\\"SampleArguments\\\",\\n    \\\"SampleBackend\\\",\\n    \\\"TrainingArguments\\\",\\n    \\\"get_args\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/config/arg_parser.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5c0c2eec1b4f49c018009b30d179ff6cd29c10872156a1351ee59f91bfc871b7\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport json\\nimport sys\\nfrom pathlib import Path\\nfrom typing import Any\\n\\nfrom omegaconf import OmegaConf\\nfrom transformers import HfArgumentParser\\n\\nfrom ..utils.env import is_env_enabled\\nfrom ..utils.helper import set_seed\\nfrom .data_args import DataArguments\\nfrom .model_args import ModelArguments\\nfrom .sample_args import SampleArguments\\nfrom .training_args import TrainingArguments\\n\\n\\nInputArgument = dict[str, Any] | list[str] | None\\n\\n\\ndef get_args(args: InputArgument = None) -> tuple[ModelArguments, DataArguments, TrainingArguments, SampleArguments]:\\n    \\\"\\\"\\\"Parse arguments from command line or config file.\\\"\\\"\\\"\\n    parser = HfArgumentParser([ModelArguments, DataArguments, TrainingArguments, SampleArguments])\\n    allow_extra_keys = is_env_enabled(\\\"ALLOW_EXTRA_KEYS\\\")\\n\\n    if args is None:\\n        if len(sys.argv) > 1 and (sys.argv[1].endswith(\\\".yaml\\\") or sys.argv[1].endswith(\\\".yml\\\")):\\n            override_config = OmegaConf.from_cli(sys.argv[2:])\\n            dict_config = OmegaConf.load(Path(sys.argv[1]).absolute())\\n            args = OmegaConf.to_container(OmegaConf.merge(dict_config, override_config))\\n        elif len(sys.argv) > 1 and sys.argv[1].endswith(\\\".json\\\"):\\n            override_config = OmegaConf.from_cli(sys.argv[2:])\\n            dict_config = OmegaConf.create(json.load(Path(sys.argv[1]).absolute()))\\n            args = OmegaConf.to_container(OmegaConf.merge(dict_config, override_config))\\n        else:  # list of strings\\n            args = sys.argv[1:]\\n\\n    if isinstance(args, dict):\\n        (*parsed_args,) = parser.parse_dict(args, allow_extra_keys=allow_extra_keys)\\n    else:\\n        (*parsed_args, unknown_args) = parser.parse_args_into_dataclasses(args, return_remaining_strings=True)\\n        if unknown_args and not allow_extra_keys:\\n            print(parser.format_help())\\n            print(f\\\"Got unknown args, potentially deprecated arguments: {unknown_args}\\\")\\n            raise ValueError(f\\\"Some specified arguments are not used by the HfArgumentParser: {unknown_args}\\\")\\n\\n    model_args, data_args, training_args, sample_args = parsed_args\\n    # Seed as early as possible after argument parsing so all downstream\\n    # components (dist init, dataloader, model init in run_* entrypoints) share the same RNG state.\\n    set_seed(training_args.seed, full_determinism=training_args.full_determinism)\\n\\n    return model_args, data_args, training_args, sample_args\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    print(get_args())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/config/arg_utils.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"dcbc592f9e4ce15dc1be3e80dc7a57797aa40a313dd543affd369ea90ea36fee\",\"content\":\"# Copyright 2025 HuggingFace Inc. and the LlamaFactory team.\\n#\\n# This code is inspired by the HuggingFace's transformers library.\\n# https://github.com/huggingface/transformers/blob/v5.0.0rc0/src/transformers/training_args.py\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\nimport json\\nfrom enum import StrEnum, unique\\n\\n\\nclass PluginConfig(dict):\\n    \\\"\\\"\\\"Dictionary that allows attribute access.\\\"\\\"\\\"\\n\\n    @property\\n    def name(self) -> str:\\n        \\\"\\\"\\\"Plugin name.\\\"\\\"\\\"\\n        if \\\"name\\\" not in self:\\n            raise ValueError(\\\"Plugin configuration must have a 'name' field.\\\")\\n\\n        return self[\\\"name\\\"]\\n\\n\\nPluginArgument = PluginConfig | dict | str | None\\n\\n\\n@unique\\nclass ModelClass(StrEnum):\\n    \\\"\\\"\\\"Auto class for model config.\\\"\\\"\\\"\\n\\n    LLM = \\\"llm\\\"\\n    CLS = \\\"cls\\\"\\n    OTHER = \\\"other\\\"\\n\\n\\n@unique\\nclass SampleBackend(StrEnum):\\n    HF = \\\"hf\\\"\\n    VLLM = \\\"vllm\\\"\\n\\n\\n@unique\\nclass BatchingStrategy(StrEnum):\\n    NORMAL = \\\"normal\\\"\\n    PADDING_FREE = \\\"padding_free\\\"\\n    DYNAMIC_BATCHING = \\\"dynamic_batching\\\"\\n    DYNAMIC_PADDING_FREE = \\\"dynamic_padding_free\\\"\\n\\n\\ndef _convert_str_dict(data: dict) -> dict:\\n    \\\"\\\"\\\"Parse string representation inside the dictionary.\\n\\n    Args:\\n        data: The string or dictionary to convert.\\n\\n    Returns:\\n        The converted dictionary.\\n    \\\"\\\"\\\"\\n    for key, value in data.items():\\n        if isinstance(value, dict):\\n            data[key] = _convert_str_dict(value)\\n        elif isinstance(value, str):\\n            if value.lower() in (\\\"true\\\", \\\"false\\\"):\\n                data[key] = value.lower() == \\\"true\\\"\\n            elif value.isdigit():\\n                data[key] = int(value)\\n            elif value.replace(\\\".\\\", \\\"\\\", 1).isdigit():\\n                data[key] = float(value)\\n\\n    return data\\n\\n\\ndef get_plugin_config(config: PluginArgument) -> PluginConfig | None:\\n    \\\"\\\"\\\"Get the plugin configuration from the argument value.\\n\\n    Args:\\n        config: The argument value to get the plugin configuration from.\\n\\n    Returns:\\n        The plugin configuration.\\n    \\\"\\\"\\\"\\n    if config is None:\\n        return None\\n\\n    if isinstance(config, str) and config.startswith(\\\"{\\\"):\\n        config = json.loads(config)\\n\\n    config = _convert_str_dict(config)\\n    if \\\"name\\\" not in config:\\n        raise ValueError(\\\"Plugin configuration must have a 'name' field.\\\")\\n\\n    return PluginConfig(config)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/config/data_args.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1e19fb378bcaf8a499b7b9fe9125c1d3996eb38ed572d91bdfa60194f9961ea8\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\nfrom dataclasses import dataclass, field\\n\\n\\n@dataclass\\nclass DataArguments:\\n    train_dataset: str | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Path to the training dataset.\\\"},\\n    )\\n    eval_dataset: str | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Path to the evaluation dataset.\\\"},\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/config/model_args.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"24f9ec0d4cddfd3121671a85c6d183f458ac4b573ffce8f641b2305db3372d1e\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\nfrom dataclasses import dataclass, field\\n\\nfrom ..utils.types import AttentionFunction\\nfrom .arg_utils import ModelClass, PluginConfig, get_plugin_config\\n\\n\\n@dataclass\\nclass ModelArguments:\\n    model: str = field(\\n        default=\\\"Qwen/Qwen3-4B-Instruct-2507\\\",\\n        metadata={\\\"help\\\": \\\"Path to the model or model identifier from Hugging Face.\\\"},\\n    )\\n    custom_chat_template: str | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Custom Jinja2 chat template string. Overrides the model's built-in template.\\\"},\\n    )\\n    trust_remote_code: bool = field(\\n        default=False,\\n        metadata={\\\"help\\\": \\\"Trust remote code from Hugging Face.\\\"},\\n    )\\n    flash_attn: AttentionFunction = field(\\n        default=AttentionFunction.SDPA,\\n        metadata={\\n            \\\"help\\\": \\\"Attention implementation to use: eager, sdpa, or flash_attention_2. SDPA is the default implementation for models.\\\"\\n        },\\n    )\\n    model_class: ModelClass = field(\\n        default=ModelClass.LLM,\\n        metadata={\\\"help\\\": \\\"Model class from Hugging Face.\\\"},\\n    )\\n    init_config: PluginConfig | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Initialization configuration for the model.\\\"},\\n    )\\n    peft_config: PluginConfig | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"PEFT configuration for the model.\\\"},\\n    )\\n    kernel_config: PluginConfig | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Kernel configuration for the model.\\\"},\\n    )\\n    quant_config: PluginConfig | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Quantization configuration for the model.\\\"},\\n    )\\n\\n    def __post_init__(self) -> None:\\n        supported_flash_attn = [item.value for item in AttentionFunction]\\n        if self.flash_attn not in supported_flash_attn:\\n            raise ValueError(\\n                f\\\"Unsupported `flash_attn`: {self.flash_attn}. Supported values are: {supported_flash_attn}.\\\"\\n            )\\n\\n        self.init_config = get_plugin_config(self.init_config)\\n        self.peft_config = get_plugin_config(self.peft_config)\\n        self.kernel_config = get_plugin_config(self.kernel_config)\\n        self.quant_config = get_plugin_config(self.quant_config)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/config/sample_args.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"190af49f3a39302231dbb63a5bf025306dc9c72ae86be51922d6c1c191a3422f\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\nfrom dataclasses import dataclass, field\\n\\nfrom .arg_utils import SampleBackend\\n\\n\\n@dataclass\\nclass SampleArguments:\\n    sample_backend: SampleBackend = field(\\n        default=SampleBackend.HF,\\n        metadata={\\\"help\\\": \\\"Sampling backend, default to 'hf'.\\\"},\\n    )\\n    max_new_tokens: int = field(\\n        default=128,\\n        metadata={\\\"help\\\": \\\"Maximum number of new tokens to generate.\\\"},\\n    )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/config/training_args.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7681ce0cb632a4cd7eed16d8bda1c858d0ba67173ff29b46faa3b79e7af8f2ea\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nimport os\\nfrom dataclasses import dataclass, field\\nfrom typing import Literal\\nfrom uuid import uuid4\\n\\nfrom ..utils.logging import get_logger\\nfrom .arg_utils import BatchingStrategy, PluginConfig, get_plugin_config\\n\\n\\nlogger = get_logger(__name__)\\n\\n\\n@dataclass\\nclass TrainingArguments:\\n    output_dir: str = field(\\n        default=os.path.join(\\\"outputs\\\", str(uuid4().hex)),\\n        metadata={\\\"help\\\": \\\"Path to the output directory.\\\"},\\n    )\\n    micro_batch_size: int = field(\\n        default=1,\\n        metadata={\\\"help\\\": \\\"Micro batch size for training.\\\"},\\n    )\\n    global_batch_size: int | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Global batch size for training, default to DP size * micro batch size.\\\"},\\n    )\\n    cutoff_len: int = field(\\n        default=2048,\\n        metadata={\\\"help\\\": \\\"Maximum sequence length for training.\\\"},\\n    )\\n    learning_rate: float = field(\\n        default=1e-4,\\n        metadata={\\\"help\\\": \\\"Learning rate for training.\\\"},\\n    )\\n    num_train_epochs: int = field(\\n        default=3,\\n        metadata={\\\"help\\\": \\\"Number of training epochs.\\\"},\\n    )\\n    max_steps: int | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Maximum number of training steps. If set, overrides num_train_epochs.\\\"},\\n    )\\n    max_grad_norm: float = field(\\n        default=1.0,\\n        metadata={\\\"help\\\": \\\"Maximum gradient norm for training.\\\"},\\n    )\\n    bf16: bool = field(\\n        default=True,\\n        metadata={\\\"help\\\": \\\"Use bf16 for training.\\\"},\\n    )\\n    batching_strategy: BatchingStrategy = field(\\n        default=BatchingStrategy.NORMAL,\\n        metadata={\\\"help\\\": \\\"Batching strategy for training.\\\"},\\n    )\\n    batching_workers: int = field(\\n        default=16,\\n        metadata={\\\"help\\\": \\\"Number of workers for batching.\\\"},\\n    )\\n    enable_activation_checkpointing: bool = field(\\n        default=True,\\n        metadata={\\\"help\\\": \\\"Enable activation checkpointing for training.\\\"},\\n    )\\n    dist_config: PluginConfig | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Distributed backend plugin configuration.\\\"},\\n    )\\n    dp_size: int | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Data parallel size, default to world_size // cp_size.\\\"},\\n    )\\n    cp_size: int = field(\\n        default=1,\\n        metadata={\\\"help\\\": \\\"Context parallel size.\\\"},\\n    )\\n    cp_mode: str = field(\\n        default=\\\"ulysses\\\",\\n        metadata={\\\"help\\\": \\\"Context parallel implementation.\\\"},\\n    )\\n    mp_replicate_size: int = field(\\n        default=1,\\n        metadata={\\\"help\\\": \\\"Model parallel replicate size.\\\"},\\n    )\\n    mp_shard_size: int | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Model parallel shard size, default to world_size // mp_replicate_size.\\\"},\\n    )\\n    dist_timeout: int = field(\\n        default=18000,\\n        metadata={\\\"help\\\": \\\"Distributed process group initialization timeout in seconds.\\\"},\\n    )\\n    optim_config: PluginConfig | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Optimizer configuration for training.\\\"},\\n    )\\n    lr_scheduler_config: PluginConfig | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Learning rate scheduler configuration for training.\\\"},\\n    )\\n    seed: int = field(\\n        default=42,\\n        metadata={\\\"help\\\": \\\"Random seed that will be set at the beginning of training.\\\"},\\n    )\\n    full_determinism: bool = field(\\n        default=False,\\n        metadata={\\\"help\\\": \\\"Enable full deterministic mode for reproducible distributed training.\\\"},\\n    )\\n    resume_from_checkpoint: str | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Path to a checkpoint directory to resume training from, or 'auto' to find the latest.\\\"},\\n    )\\n    save_steps: int | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Save a training checkpoint every N global steps.\\\"},\\n    )\\n    save_epochs: float | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Save a training checkpoint every N epochs.\\\"},\\n    )\\n    save_ckpt_as_hf: bool = field(\\n        default=False,\\n        metadata={\\n            \\\"help\\\": \\\"Save intermediate checkpoints in HuggingFace format instead of distributed format. Warning: doubles memory usage.\\\"\\n        },\\n    )\\n    save_total_limit: int | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Maximum number of checkpoints to keep. Oldest checkpoints are deleted.\\\"},\\n    )\\n    logging_steps: int = field(\\n        default=1,\\n        metadata={\\\"help\\\": \\\"Log metrics every N optimizer steps.\\\"},\\n    )\\n    chunk_loss_size: int | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Maximum flattened token rows per Chunk Loss chunk. None disables Chunk Loss.\\\"},\\n    )\\n    pref_loss: Literal[\\\"sigmoid\\\", \\\"orpo\\\", \\\"simpo\\\"] = field(\\n        default=\\\"sigmoid\\\",\\n        metadata={\\\"help\\\": \\\"The type of DPO loss to use.\\\"},\\n    )\\n    pref_beta: float = field(\\n        default=0.1,\\n        metadata={\\\"help\\\": \\\"The beta parameter in the preference loss.\\\"},\\n    )\\n    pref_ftx: float = field(\\n        default=0.0,\\n        metadata={\\\"help\\\": \\\"The supervised fine-tuning loss coefficient in DPO training.\\\"},\\n    )\\n    simpo_gamma: float = field(\\n        default=0.5,\\n        metadata={\\\"help\\\": \\\"The target reward margin term in SimPO loss.\\\"},\\n    )\\n    dpo_label_smoothing: float = field(\\n        default=0.0,\\n        metadata={\\\"help\\\": \\\"The robust DPO label smoothing parameter in cDPO that should be between 0 and 0.5.\\\"},\\n    )\\n    ld_alpha: float | None = field(\\n        default=None,\\n        metadata={\\\"help\\\": \\\"Alpha parameter from LD-DPO, controls weighting of verbose token log-probabilities.\\\"},\\n    )\\n\\n    def __post_init__(self) -> None:\\n        self.dist_config = get_plugin_config(self.dist_config)\\n        self.optim_config = get_plugin_config(self.optim_config)\\n        self.lr_scheduler_config = get_plugin_config(self.lr_scheduler_config)\\n        if self.chunk_loss_size is not None and self.chunk_loss_size <= 0:\\n            raise ValueError(\\\"`chunk_loss_size` must be positive.\\\")\\n        try:\\n            from ..plugins.model_plugins.deepspeed_utils import register_deepspeed_dist_config\\n\\n            register_deepspeed_dist_config(self.dist_config)\\n        except ImportError:\\n            pass\\n\\n        # The optimizer learning rate has a single source of truth: ``learning_rate``.\\n        # Propagate it into ``optim_config[\\\"lr\\\"]`` so optimizer plugins (e.g. Muon) pick it up\\n        # via ``optim_config.get(\\\"lr\\\")`` without each plugin needing a separate ``learning_rate`` arg.\\n        if self.optim_config is not None:\\n            if \\\"lr\\\" in self.optim_config:\\n                logger.warning_rank0(\\n                    \\\"`optim_config.lr` is overridden by `learning_rate`; set the learning rate via \\\"\\n                    \\\"`learning_rate` instead and remove `lr` from `optim_config`.\\\"\\n                )\\n            self.optim_config[\\\"lr\\\"] = self.learning_rate\\n\\n        if str(self.batching_strategy) == str(BatchingStrategy.DYNAMIC_BATCHING):\\n            if self.max_steps is None or self.max_steps <= 0:\\n                raise ValueError(\\\"`dynamic_batching` requires `max_steps` because it is step-driven.\\\")\\n            if self.save_epochs is not None:\\n                raise ValueError(\\\"`save_epochs` is not supported with `dynamic_batching`; use `save_steps` instead.\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/core/__init__.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855\",\"content\":\"\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/core/base_sampler.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8b62a83295f91c6e095ee8ff898bd05c4e620a68395f9dd9bc60c3c31db22d4c\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\nfrom collections.abc import AsyncGenerator\\n\\nfrom ..config import ModelArguments, SampleArguments, SampleBackend\\nfrom ..utils.types import HFModel, Message, Sample, TorchDataset\\nfrom .rendering import Renderer\\nfrom .utils.inference_engine import HuggingFaceEngine\\n\\n\\nclass BaseSampler:\\n    \\\"\\\"\\\"Base sampler.\\n\\n    Args:\\n        args: Sample arguments.\\n        model_args: Model arguments.\\n        model: Model.\\n        renderer: Renderer.\\n    \\\"\\\"\\\"\\n\\n    def __init__(\\n        self,\\n        args: SampleArguments,\\n        model_args: ModelArguments,\\n        model: HFModel,\\n        renderer: Renderer,\\n    ) -> None:\\n        if args.sample_backend == SampleBackend.HF:\\n            self.engine = HuggingFaceEngine(args, model_args, model, renderer)\\n        else:\\n            raise ValueError(f\\\"Unknown sample backend: {args.sample_backend}\\\")\\n\\n    async def generate(self, messages: list[Message], tools: str | None = None) -> AsyncGenerator[str, None]:\\n        \\\"\\\"\\\"Generate tokens asynchronously.\\n\\n        Args:\\n            messages: List of messages.\\n            tools: Tools string.\\n\\n        Yields:\\n            Generated tokens.\\n        \\\"\\\"\\\"\\n        async for token in self.engine.generate(messages, tools):\\n            yield token\\n\\n    async def batch_infer(self, dataset: TorchDataset) -> list[Sample]:\\n        \\\"\\\"\\\"Batch infer samples.\\n\\n        Args:\\n            dataset: Torch dataset.\\n\\n        Returns:\\n            List of samples.\\n        \\\"\\\"\\\"\\n        return await self.engine.batch_infer(dataset)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"LlamaFactory\",\"source_path\":\"src/llamafactory/v1/core/base_trainer.py\",\"source_license\":\"Apache-2.0\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6c7102d5196274cfedf7e0137f885be43499a28bf80f3447c29ae8d3db26dc79\",\"content\":\"# Copyright 2025 the LlamaFactory team.\\n#\\n# Licensed under the Apache License, Version 2.0 (the \\\"License\\\");\\n# you may not use this file except in compliance with the License.\\n# You may obtain a copy of the License at\\n#\\n#     http://www.apache.org/licenses/LICENSE-2.0\\n#\\n# Unless required by applicable law or agreed to in writing, software\\n# distributed under the License is distributed on an \\\"AS IS\\\" BASIS,\\n# WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.\\n# See the License for the specific language governing permissions and\\n# limitations under the License.\\n\\n\\\"\\\"\\\"The definition of trainer.\\n\\nInit Phase:\\n\\n1. Init batch generator.\\n2. Init optimizer (deepspeed).\\n3. Shard model.\\n4. Init optimizer (fsdp).\\n5. Init lr scheduler.\\n\\nTrain Phase:\\n1. Train Loop\\n\\n\\\"\\\"\\\"\\n\\nfrom abc import abstractmethod\\n\\nimport torch\\nimport torch.nn.functional as F\\nfrom torch.distributed.tensor import DTensor\\n\\nfrom ..accelerator.helper import ReduceOp\\nfrom ..accelerator.interface import Dim, DistributedInterface\\nfrom ..config import BatchingStrategy, TrainingArguments\\nfrom ..utils import logging\\nfrom ..utils.callbacks import (\\n    CallbackHandler,\\n    LoggingCallback,\\n    TrainerCallback,\\n    TrainerState,\\n)\\nfrom ..utils.helper import compute_valid_tokens, is_tokenizer, model_uses_mrope\\nfrom ..utils.types import BatchInput, HFModel, ModelOutput, Tensor, TorchDataset\\nfrom .rendering import Renderer\\nfrom .utils.batching import BatchGenerator\\nfrom .utils.checkpoint import TrainingCheckpointCoordinator\\n\\n\\nlogger = logging.get_logger(__name__)\\n\\n\\nclass BaseTrainer:\\n    def __init__(\\n        self,\\n        args: TrainingArguments,\\n        model: HFModel,\\n        renderer: Renderer,\\n        train_dataset: TorchDataset,\\n        callbacks: list[TrainerCallback] | None = None,\\n    ) -> None:\\n        self.args = args\\n        self.model = model\\n        self.renderer = renderer\\n        self.train_dataset = train_dataset\\n\\n        # info\\n        self.global_step = 0\\n\\n        # cached variables\\n        self.device = DistributedInterface().current_device\\n        self.dp_size = DistributedInterface().get_world_size(Dim.DP)\\n        self.cp_size = DistributedInterface().get_world_size(Dim.CP)\\n        self.model_input_names = self.renderer.processor.model_input_names\\n        self._uses_mrope = model_uses_mrope(self.model.config)\\n\\n        self._create_batch_generator()\\n        # Calculate num_training_steps: max_steps takes priority if set\\n        if self.args.max_steps is not None and self.args.max_steps > 0:\\n            self.num_training_steps = self.args.max_steps\\n        else:\\n            self.num_training_steps = self.args.num_train_epochs * len(self.train_batch_generator)\\n\\n        if self.args.save_epochs is not None:\\n            steps_per_epoch = len(self.train_batch_generator)\\n            self.args.save_steps = max(1, int(steps_per_epoch * self.args.save_epochs))\\n\\n        if self.args.enable_activation_checkpointing:\\n            self.model.gradient_checkpointing_enable({\\\"use_reentrant\\\": False})\\n            # Note: under FSDP2 bf16, encoder-tower nn.LayerNorms are made dtype-safe for the\\n            # checkpoint recompute inside the FSDP2 engine (see fsdp2.py prepare_model), so the\\n";
